INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C1','soc',6,2,'u3',1,'인구 분포에 영향을 주는 요인 — 기온·강수량·지형 등 자연환경과 산업·교통·문화 등 인문환경이 인구 분포에 많은 영향을 줌 · 옛날에는 기후가 온화한 지역·평야·해안처럼 자연환경이 유리한 곳에, 오늘날에는 산업이 발달해 일자리가 풍부하고 교통이 편리하며 교육·문화 시설이 갖춰진 곳에 모여 삶',ARRAY['[6사12-01] 세계의 인구 분포를 파악하고 여러 국가의 인구 특징을 탐구한다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C2','soc',6,2,'u3',1,'세계의 인구 분포 특징 — 세계 인구는 고르게 분포하지 않고 특정 지역에 모여 있음 · 세계 인구의 약 90 %가 육지가 많은 북반구에, 기후가 온화한 중위도에 많고 냉대·한대 기후의 고위도에 적음 · 동아시아와 남부 아시아(온화한 평야·농업)·서부 유럽(산업·일자리·교통)에 많고, 사하라 사막(강수량 매우 적음)·알래스카(기온 매우 낮음)·열대 우림에 적음 · 100명 마을이면 아시아 59명·오세아니아 1명 · 세계 인구는 약 25억 명(1950)에서 약 81억 명(2023)으로 늘고 아프리카 비율이 크게 늘었음(비율이 줄어도 수가 준 것은 아님)',ARRAY['[6사12-01] 세계의 인구 분포를 파악하고 여러 국가의 인구 특징을 탐구한다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C3','soc',6,2,'u3',2,'세계 여러 나라의 인구수 — 나라마다 다르며 대체로 아시아의 나라들은 많고 오세아니아의 나라들은 적음(10억 명 이상은 인도·중국) · 면적이 넓다고 반드시 인구수가 많은 것은 아님 · 인도(강수량 많고 비옥한 토양·농업·높은 출생률), 미국(온화한 기후·다양한 산업·이민), 리비아(국토 대부분 사막이라 면적에 비해 적음), 투발루(작은 섬나라, 기후변화로 잠길 위험) · 인구 성장률은 인구가 증가하는 비율로 아프리카는 높고 유럽은 낮거나 감소 · 인구수는 출생·사망·인구의 이동·환경 변화에 따라 달라짐',ARRAY['[6사12-01] 세계의 인구 분포를 파악하고 여러 국가의 인구 특징을 탐구한다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C4','soc',6,2,'u3',3,'세계 여러 나라의 인구 밀도 — 일정한 면적(1 km²) 안에 사는 인구수로 인구가 모여 있는 정도를 나타냄, 면적에 비해 인구수가 많을수록 높음 · 방글라데시·르완다·인도는 높고 몽골·오스트레일리아·캐나다는 낮음, 아시아·유럽에 높은 나라가 많고 고위도에 낮은 나라가 많음 · 방글라데시(약 1,317명/km², 국토 대부분 평야·온화한 기후·벼농사) vs 캐나다(약 4명/km², 냉대 기후라 농사지을 땅이 적음) · 우리나라(약 515명/km²)는 면적이 비슷한 나라보다 매우 높은 편 · 인구가 늘면 밀도도 높아지는 등 변화할 수 있음',ARRAY['[6사12-01] 세계의 인구 분포를 파악하고 여러 국가의 인구 특징을 탐구한다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C5','soc',6,2,'u3',4,'인구 구조와 인구 피라미드 — 인구 구조는 연령·성 등을 기준으로 한 인구의 짜임새(유소년층 0~14세·청장년층 15~64세·노년층 65세 이상) · 인구 피라미드는 연령별·성별 인구를 나타낸 그래프(가로축 왼쪽 남자·오른쪽 여자 비율, 세로축 나이) · 세계 인구 구조는 1960년보다 2020년에 유소년층 비율이 줄고 노년층 비율이 늘었으며 청장년층 비율이 가장 높음 · 출생률·사망률이 높고 평균 수명이 짧으면 유소년층이 많고(나이지리아), 낮고 길면 노년층이 많음(일본)',ARRAY['[6사12-01] 세계의 인구 분포를 파악하고 여러 국가의 인구 특징을 탐구한다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C6','soc',6,2,'u3',4,'인구 구조와 우리 생활 — 인구 구조로 미래 인구 변화를 예상할 수 있고 경제·문화 등 생활과 밀접함 · 유소년층이 많은 나라는 유치원·학교 같은 어린이 시설, 노년층이 많은 나라는 요양원·노인 복지 센터가 더 필요함 · 청장년층 비율이 높은 인도네시아는 젊은 소비자가 많아 기업이 주목하는 「젊은 시장」 · 석유 자원이 풍부한 사우디아라비아·아랍 에미리트 등은 외국인 근로자를 받아들여 청장년층이 두드러지게 많음 · 아이를 더 낳거나 덜 낳도록 권하는 포스터도 인구 구조와 관련',ARRAY['[6사12-01] 세계의 인구 분포를 파악하고 여러 국가의 인구 특징을 탐구한다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C7','soc',6,2,'u3',5,'지구촌과 지구촌을 위협하는 문제 — 지구촌은 과학 기술과 교통·통신의 발달로 지구가 하나의 마을처럼 가까워진 모습(소식·정보·문화 교류가 쉬워진 좋은 점, 한 나라의 문제가 다른 나라에 영향을 주고 갈등이 생길 수 있는 문제점) · 지구촌은 자원과 에너지 고갈(광산 개발), 생태계 파괴(열대 우림 벌채 — 농사·목축·산업 등 인간 활동이 원인, 동식물의 터전과 탄소 흡수가 사라짐), 기후변화(화석 연료 과다 사용 — 녹는 빙하), 난민(전쟁·재난으로 살던 곳을 떠남) 문제를 겪음 · 지구촌 전등 끄기 캠페인처럼 함께 노력함',ARRAY['[6사12-02] 지구촌을 위협하는 다양한 문제들을 파악하고, 지속가능한 미래를 위한 해결 방안을 탐색한다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C8','soc',6,2,'u3',6,'지구촌 문제 조사하기 — 문제 생각하기 → 조사 방법 정하기 → 문제 상황·원인 조사하기 → 내용 정리하기 · 자료는 누리집 통계·책·신문 기사·카드 뉴스·다큐멘터리, 출처가 명확하고 믿을 만한지 확인 · 붙임쪽지에 지역·문제 상황·문제 원인을 요약해 세계지도의 해당 나라에 붙이면 지구촌 곳곳의 문제를 한눈에 파악 · 탄소를 적게 내는 나라가 가뭄을 겪고(동아프리카), 해수면 상승으로 섬이 잠기는(투발루) 것처럼 지구촌 문제는 한 지역에 그치지 않는 우리 모두의 문제 · 옷 한 벌에도 많은 물이 들어 내 작은 행동이 지구에 영향을 줌',ARRAY['[6사12-02] 지구촌을 위협하는 다양한 문제들을 파악하고, 지속가능한 미래를 위한 해결 방안을 탐색한다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C9','soc',6,2,'u3',7,'지속가능한 미래와 개인·기업·국가의 노력 — 지속가능한 미래는 오늘날의 모든 사람이 지구 환경을 개선하고 보존해 미래 세대에 물려주려는 노력 속에서 이루어짐(인간 위주가 아니라 지구촌 모두를 생각하는 자세) · 개인: 녹색 제품 소비(생산 때 자원·에너지를 적게 써 오염 물질 최소화), 일회용품 줄이기, 분리배출·재활용, 에너지 절약 · 기업: 탄소를 줄이는 제품·친환경 소재·자원을 적게 쓴 제품(라벨 없앤 생수병), 책임 있는 경영 · 국가: 법과 제도·정책, 국제 협약 준수(기후변화 협약), 난민 보호 · 여러 주체의 노력이 모두 모여야 함',ARRAY['[6사12-02] 지구촌을 위협하는 다양한 문제들을 파악하고, 지속가능한 미래를 위한 해결 방안을 탐색한다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C10','soc',6,2,'u3',7,'국제기구와 비정부 기구의 노력 — 국제기구: 국제 연합(국제 평화와 안전·협력), 국제 연합 아동 기금(어려운 어린이에게 의료·식량·교육), 국제 연합 난민 기구(난민 보호·물품·의료·교육) · 비정부 기구는 개인이나 민간단체가 중심이 되어 공공의 이익을 지키려고 만든 단체: 국경 없는 의사회(차별 없는 의료), 세계 자연 기금(생물 다양성·기후변화 대응), 그린피스(환경 연구·해양 생태계 보호)',ARRAY['[6사12-02] 지구촌을 위협하는 다양한 문제들을 파악하고, 지속가능한 미래를 위한 해결 방안을 탐색한다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C11','soc',6,2,'u3',8,'세계시민과 실천 — 세계시민은 지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람으로, 지구촌 문제를 우리 모두의 문제로 여기고 관심을 두며 해결 방법을 고민함 · 할 일을 정할 때 일상에서 실천 가능한지·효과가 있는지 생각하고 더하기(+) 노력(장바구니·다회용품)과 빼기(−) 노력(플라스틱 덜 쓰기·안 쓰는 전등 끄기)을 구분 · 실천 인증 릴레이: 인증 사진 → 구체적 기록 → 다음 친구에게 알리기 · 개인의 노력이 기업과 사회의 변화를 만들 수 있음 · 주제를 정할 때 서로 다른 관심을 존중 · 에코 제품 디자이너처럼 직업으로도 이바지',ARRAY['[6사12-02] 지구촌을 위협하는 다양한 문제들을 파악하고, 지속가능한 미래를 위한 해결 방안을 탐색한다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u3-C12','soc',6,2,'u3',9,'그림책 스토리보드 만들기 — 스토리보드는 장면을 구성하며 이야기의 흐름을 작성한 것으로 장면별 줄거리와 스케치 형식의 그림(그림 순서·그림·그림 설명·글·대사 칸)이 들어감 · 계획: 주제·줄거리, 독자를 정하고 그 수준에 맞게(어린 독자면 쉬운 낱말·짧은 문장), 세계 인구의 특징과 지속가능한 지구촌이 골고루 드러나게, 이야기 흐름이 자연스럽게 · 역할을 나누어 만들고 발표회에서 내용과 수준이 적절한지, 계획대로 만들었는지 살펴봄',ARRAY['[6사12-01] 세계의 인구 분포를 파악하고 여러 국가의 인구 특징을 탐구한다. / [6사12-02] 지구촌을 위협하는 다양한 문제들을 파악하고, 지속가능한 미래를 위한 해결 방안을 탐색한다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X01','soc',6,'u3',ARRAY['SO6-2-u3-C1']::text[],'인구 분포에 영향을 주는 자연환경 요인(기온·강수량·지형)과 인문환경 요인(산업·교통·문화)을 바꾸어 나눈다','자연이 만든 것 · 사람이 만든 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X02','soc',6,'u3',ARRAY['SO6-2-u3-C1','SO6-2-u3-C2']::text[],'세계 인구가 고르게 퍼져 있다고, 또는 땅이 넓은 곳일수록 사람이 많다고 여긴다','특정한 지역에 모여 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X03','soc',6,'u3',ARRAY['SO6-2-u3-C2']::text[],'인구가 많은 지역과 적은 지역, 그 까닭을 바꾸어 짝짓는다(알래스카·사하라에 많다고, 서부 유럽은 기후 탓에 적다고 하는 등)','점이 빽빽한 곳과 드문 곳의 환경') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X04','soc',6,'u3',ARRAY['SO6-2-u3-C2']::text[],'인구가 많은 반구와 위도를 거꾸로 안다(남반구·고위도에 많다고)','북반구 약 90 % · 온화한 중위도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X05','soc',6,'u3',ARRAY['SO6-2-u3-C2']::text[],'인구 비율과 인구수를 같은 것으로 여기거나(비율이 줄면 수도 줄었다고) 세계 인구의 변화를 거꾸로 읽는다','비율 ≠ 인구수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X06','soc',6,'u3',ARRAY['SO6-2-u3-C3','SO6-2-u3-C4']::text[],'나라의 면적이 넓으면 인구수도 많다고 여긴다','넓어도 살기 어려우면 적어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X07','soc',6,'u3',ARRAY['SO6-2-u3-C3']::text[],'대륙·나라별 인구수의 많고 적음과 그 까닭을 바꾸어 안다(오세아니아에 인구가 많다고, 리비아가 사막 때문에 인구가 많다고 하는 등)','아시아는 많고 오세아니아는 적어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X08','soc',6,'u3',ARRAY['SO6-2-u3-C3']::text[],'인구 성장률의 뜻이나 인구수를 바꾸는 요인(출생·사망·이동·환경 변화)을 잘못 안다','늘어나는 비율 · 들어오고 나가고 태어나고 사망하고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X09','soc',6,'u3',ARRAY['SO6-2-u3-C4']::text[],'인구 밀도를 인구수만으로, 또는 면적만으로 판단한다','1 km² 안의 인구수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X10','soc',6,'u3',ARRAY['SO6-2-u3-C4']::text[],'인구 밀도가 높은 나라와 낮은 나라, 그 까닭(평야·벼농사 / 냉대 기후)을 바꾸어 안다','방글라데시 높음 · 캐나다 낮음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X11','soc',6,'u3',ARRAY['SO6-2-u3-C5']::text[],'인구 구조의 뜻이나 인구 피라미드의 축(가로 — 남녀 비율, 세로 — 나이)·연령층을 잘못 읽는다','아래층 유소년 · 위층 노년') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X12','soc',6,'u3',ARRAY['SO6-2-u3-C5']::text[],'출생률·사망률·평균 수명과 인구 구조의 관계를 거꾸로 안다(출생률이 낮은 나라에 유소년층이 많다고 하는 등)','낮은 출생률 → 노년층 비율 높음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X13','soc',6,'u3',ARRAY['SO6-2-u3-C6']::text[],'인구 구조와 생활(필요한 시설·젊은 시장·외국인 근로자)을 맞지 않게 잇는다','많은 연령층에 맞는 시설과 시장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X14','soc',6,'u3',ARRAY['SO6-2-u3-C7']::text[],'지구촌의 뜻을 오해하거나 지구촌 시대의 좋은 점과 문제점을 바꾸어 안다','하나의 마을처럼 가까워진 지구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X15','soc',6,'u3',ARRAY['SO6-2-u3-C7','SO6-2-u3-C8']::text[],'지구촌 문제(자원·에너지 고갈, 생태계 파괴, 기후변화, 난민)와 그 장면·원인을 바꾸어 짝짓는다','광산 · 열대 우림 · 빙하 · 보트') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X16','soc',6,'u3',ARRAY['SO6-2-u3-C7','SO6-2-u3-C8','SO6-2-u3-C11']::text[],'지구촌 문제를 그 나라만의 일로 여겨 나와 관계없다고 생각한다','우리 모두의 문제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X17','soc',6,'u3',ARRAY['SO6-2-u3-C8']::text[],'지구촌 문제를 조사할 때 출처를 확인하지 않거나, 지역·문제 상황·원인 가운데 일부를 빠뜨린다','믿을 만한 자료 · 지역·상황·원인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X18','soc',6,'u3',ARRAY['SO6-2-u3-C9']::text[],'지속가능한 미래를 지금 세대의 편리함만 생각하는 것으로, 또는 인간 위주로 생각하는 것으로 오해한다','미래 세대에 물려주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X19','soc',6,'u3',ARRAY['SO6-2-u3-C9']::text[],'개인·기업·국가가 하는 노력을 서로 바꾸어 짝짓는다','생활 속 실천 · 제품 · 법과 협약') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X20','soc',6,'u3',ARRAY['SO6-2-u3-C10']::text[],'국제기구와 비정부 기구를 헷갈리거나 각 단체가 하는 일을 바꾸어 안다','나라들이 만든 기구 · 민간이 만든 단체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X21','soc',6,'u3',ARRAY['SO6-2-u3-C11']::text[],'세계시민의 자세와 실천 방법을 잘못 안다(나 하나로는 소용없다고, 실천하기 어려운 계획을 세우거나 더하기·빼기 노력을 바꾸는 등)','작은 일부터 · 책임감 · 실천 가능하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X22','soc',6,'u3',ARRAY['SO6-2-u3-C12']::text[],'그림책 스토리보드를 만들 때 독자의 수준·이야기의 흐름·단원 주제를 고려하지 않는다','누가 읽나 · 흐름 · 두 주제 골고루') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X23','soc',6,'u3',ARRAY['SO6-2-u3-C2','SO6-2-u3-C3','SO6-2-u3-C4']::text[],'인구 공부를 나라별 인구수·수치를 외우는 것으로 여겨 자료에서 특징과 까닭을 읽어 내는 것을 놓친다','외우기보다 자료를 읽고 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X24','soc',6,'u3',ARRAY['SO6-2-u3-C3','SO6-2-u3-C4','SO6-2-u3-C5']::text[],'인구수·인구 밀도·인구 구조 같은 인구 특징만 보고 그 나라를 좋다·나쁘다, 앞섰다·뒤떨어졌다로 단정하는 편견을 갖는다','인구 특징은 자연환경·인문환경에서 생긴 모습일 뿐이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X25','soc',6,'u3',ARRAY['SO6-2-u3-C5','SO6-2-u3-C6']::text[],'인구 구조는 출생률·사망률로만 정해진다고 여겨, 외국인 근로자를 받아들이는 것 같은 인구 이동이 만든 인구 구조를 놓친다','다른 나라에서 일하러 온 사람들도 인구 구조를 바꿔요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X26','soc',6,'u3',ARRAY['SO6-2-u3-C8']::text[],'지구촌 문제의 원인과 피해가 같은 나라 안에 있다고 여긴다(탄소를 적게 내는 나라는 기후변화 피해를 입지 않는다고 여기는 등)','원인이 생긴 곳과 피해를 입는 곳이 다를 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u3-X27','soc',6,'u3',ARRAY['SO6-2-u3-C11']::text[],'지구촌을 위한 실천은 한 번 해 보고 인증하면 끝난다고 여겨, 기간과 횟수를 정해 꾸준히 이어 가는 것을 놓친다','한 번의 실천으로 끝나지 않도록 기간과 횟수를 정해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_basic#1','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',1,'mc','auto','「세계가 100명이 사는 마을이라면」 자료에서 가장 많은 사람이 사는 대륙은 어디인가요?',ARRAY['SO6-2-u3-X07']::text[],true,'{"seq":1,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"mc","stem":"「세계가 100명이 사는 마을이라면」 자료에서 가장 많은 사람이 사는 대륙은 어디인가요?","options":[{"t":"아시아","correct":true},{"t":"아프리카","mis":"SO6-2-u3-X07"},{"t":"유럽","mis":"SO6-2-u3-X07"},{"t":"오세아니아","mis":"SO6-2-u3-X07"}],"explanation":["대륙별 사람 수를 견줘요.","아시아가 59명으로 가장 많아요.","답은 아시아예요."],"asset":{"type":"passage","lines":["아시아 59명 · 아프리카 18명 · 유럽 9명","남아메리카 8명 · 북아메리카 5명 · 오세아니아 1명"],"title":"124쪽 세계가 100명이 사는 마을이라면(국제 연합, 2024)"},"variant_rule":{"alt":[{"stem":"「세계가 100명이 사는 마을이라면」 자료에서 가장 적은 사람이 사는 대륙은 어디인가요?","options":[{"t":"오세아니아","correct":true},{"t":"북아메리카","mis":"SO6-2-u3-X07"},{"t":"남아메리카","mis":"SO6-2-u3-X07"},{"t":"유럽","mis":"SO6-2-u3-X07"}],"explanation":["가장 작은 수를 찾아요.","오세아니아는 1명이에요.","답은 오세아니아예요."],"asset":{"type":"passage","lines":["아시아 59명 · 아프리카 18명 · 유럽 9명","남아메리카 8명 · 북아메리카 5명 · 오세아니아 1명"],"title":"124쪽 세계가 100명이 사는 마을이라면(국제 연합, 2024)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_basic#2','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C1',1,'sa','auto','꼭 기억해요 — 「기온, 강수량, 지형 등 (    )과/와 산업, 교통, 문화 등 인문환경은 세계의 인구 분포에 많은 영향을 줍니다.」 빈칸에 알맞은 말을 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"SO6-2-u3-C1","difficulty":1,"kind":"sa","stem":"꼭 기억해요 — 「기온, 강수량, 지형 등 (    )과/와 산업, 교통, 문화 등 인문환경은 세계의 인구 분포에 많은 영향을 줍니다.」 빈칸에 알맞은 말을 쓰세요.","answer":["자연환경","자연 환경"],"explanation":["기온·강수량·지형은 자연이 만든 환경이에요.","산업·교통·문화는 사람이 만든 인문환경이에요.","빈칸은 자연환경이에요."],"mis":"SO6-2-u3-X01","variant_rule":{"alt":[{"stem":"꼭 기억해요 — 「기온, 강수량, 지형 등 자연환경과 산업, 교통, 문화 등 (    )은/는 세계의 인구 분포에 많은 영향을 줍니다.」 빈칸에 알맞은 말을 쓰세요.","answer":["인문환경","인문 환경"],"explanation":["산업·교통·문화를 묶는 말이에요.","사람이 만든 환경이에요.","빈칸은 인문환경이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_basic#3','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',1,'ox','auto','꼭 기억해요 — 세계 인구는 지구상에 고르게 분포합니다.',ARRAY['SO6-2-u3-X02']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"ox","stem":"꼭 기억해요 — 세계 인구는 지구상에 고르게 분포합니다.","answer":"X","reason_options":[{"t":"세계의 인구는 특정한 지역에 모여 있어 많은 곳과 적은 곳이 있기 때문에","correct":true},{"t":"모든 대륙에 사람이 똑같이 나뉘어 살기 때문에","mis":"SO6-2-u3-X02"}],"mis":"SO6-2-u3-X02","explanation":["100명 마을도 대륙마다 수가 달라요.","지도에도 점이 빽빽한 곳과 드문 곳이 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_basic#4','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',1,'mc','auto','126쪽 세계의 인구 분포 지도는 인구를 무엇으로 나타냈나요?',ARRAY['SO6-2-u3-X03','SO6-2-u3-X06']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"mc","stem":"126쪽 세계의 인구 분포 지도는 인구를 무엇으로 나타냈나요?","options":[{"t":"점 — 점 1개가 100만 명이고 점이 많을수록 인구가 많다","correct":true},{"t":"색 — 색이 진할수록 땅이 높다","mis":"SO6-2-u3-X03"},{"t":"선 — 선이 많을수록 비가 많이 온다","mis":"SO6-2-u3-X03"},{"t":"점 — 점이 많을수록 나라가 넓다","mis":"SO6-2-u3-X06"}],"explanation":["지도 아래 설명을 읽어요.","점 1개가 100만 명이에요.","점이 빽빽하면 인구가 많아요."],"asset":{"type":"passage","lines":["점 1개 — 100만 명","점이 빽빽한 곳 — 동아시아, 남부 아시아, 서부 유럽","점이 드문 곳 — 사막, 열대 우림, 극지방","말풍선 — 세계 인구의 약 90 %가 북반구에 살아요.","가 지역 — 북아메리카 북서쪽 끝의 알래스카"],"numbered":false,"title":"126~127쪽 세계의 인구 분포 지도(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_basic#5','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C1',2,'mc','auto','125쪽 붙임딱지 가운데 인구가 적게 분포하는 지역에 붙일 것은 어느 것인가요?',ARRAY['SO6-2-u3-X03']::text[],true,'{"seq":5,"concept":"SO6-2-u3-C1","difficulty":2,"kind":"mc","stem":"125쪽 붙임딱지 가운데 인구가 적게 분포하는 지역에 붙일 것은 어느 것인가요?","options":[{"t":"㉤ 강수량이 매우 적어 물을 구하기 어렵다.","correct":true},{"t":"㉠ 일찍부터 과학과 기술이 발전하여 다양한 산업이 발달했다.","mis":"SO6-2-u3-X03"},{"t":"㉡ 강수량이 많고 비옥한 평야가 있어 농사에 유리하다.","mis":"SO6-2-u3-X03"},{"t":"㉢ 바다를 이용해 무역을 하거나 해산물을 쉽게 얻을 수 있다.","mis":"SO6-2-u3-X03"}],"explanation":["살기 어려운 조건을 찾아요.","물을 구하기 어려우면 사람이 모이기 힘들어요.","㉤이 인구가 적은 지역이에요."],"asset":{"type":"passage","lines":["㉠ 일찍부터 과학과 기술이 발전하여 다양한 산업이 발달했다.","㉡ 강수량이 많고 비옥한 평야가 있어 농사에 유리하다.","㉢ 바다를 이용해 무역을 하거나 해산물을 쉽게 얻을 수 있다.","㉣ 기온이 높고 강수량이 많아 열대 우림이 우거져 있다.","㉤ 강수량이 매우 적어 물을 구하기 어렵다.","㉥ 기온이 매우 낮아 식물이 자라기 어렵다."],"numbered":false,"title":"125쪽 사진에 붙일 붙임딱지 여섯"},"variant_rule":{"alt":[{"stem":"125쪽 붙임딱지 가운데 인구가 많이 분포하는 지역에 붙일 것은 어느 것인가요?","options":[{"t":"㉡ 강수량이 많고 비옥한 평야가 있어 농사에 유리하다.","correct":true},{"t":"㉣ 기온이 높고 강수량이 많아 열대 우림이 우거져 있다.","mis":"SO6-2-u3-X03"},{"t":"㉤ 강수량이 매우 적어 물을 구하기 어렵다.","mis":"SO6-2-u3-X03"},{"t":"㉥ 기온이 매우 낮아 식물이 자라기 어렵다.","mis":"SO6-2-u3-X03"}],"explanation":["살기 좋은 조건을 찾아요.","비옥한 평야는 농사에 유리해요.","㉡이 인구가 많은 지역이에요."],"asset":{"type":"passage","lines":["㉠ 일찍부터 과학과 기술이 발전하여 다양한 산업이 발달했다.","㉡ 강수량이 많고 비옥한 평야가 있어 농사에 유리하다.","㉢ 바다를 이용해 무역을 하거나 해산물을 쉽게 얻을 수 있다.","㉣ 기온이 높고 강수량이 많아 열대 우림이 우거져 있다.","㉤ 강수량이 매우 적어 물을 구하기 어렵다.","㉥ 기온이 매우 낮아 식물이 자라기 어렵다."],"numbered":false,"title":"125쪽 사진에 붙일 붙임딱지 여섯"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_basic#6','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',2,'match','auto','126~127쪽 지도의 지역과 인구가 많거나 적은 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"match","stem":"126~127쪽 지도의 지역과 인구가 많거나 적은 까닭을 알맞게 이으세요.","pairs":[{"l":"동아시아와 남부 아시아","r":"기후가 온화한 평야, 농업 발달"},{"l":"서부 유럽","r":"산업 발달, 풍부한 일자리, 편리한 교통"},{"l":"사하라 사막","r":"강수량이 매우 적어 물을 구하기 어려움"},{"l":"가 지역(알래스카)","r":"기온이 매우 낮아 식물이 자라기 어려움"}],"mis":"SO6-2-u3-X03","explanation":["점이 빽빽한 곳과 드문 곳을 나눠요.","평야와 산업이 있으면 사람이 모여요.","물이 없거나 너무 추우면 적어요."],"asset":{"type":"passage","lines":["점 1개 — 100만 명","점이 빽빽한 곳 — 동아시아, 남부 아시아, 서부 유럽","점이 드문 곳 — 사막, 열대 우림, 극지방","말풍선 — 세계 인구의 약 90 %가 북반구에 살아요.","가 지역 — 북아메리카 북서쪽 끝의 알래스카"],"numbered":false,"title":"126~127쪽 세계의 인구 분포 지도(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_basic#7','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',2,'ox','auto','활동지의 ㉡ 시베리아는 기온이 매우 낮아 식물이 자라기 어려워 인구가 적게 분포해요.',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"ox","stem":"활동지의 ㉡ 시베리아는 기온이 매우 낮아 식물이 자라기 어려워 인구가 적게 분포해요.","answer":"O","reason_options":[{"t":"고위도의 매우 추운 곳이라 사람이 생활하기 어렵기 때문에","correct":true},{"t":"시베리아는 기후가 온화한 평야라 사람이 많이 살기 때문에","mis":"SO6-2-u3-X03"}],"mis":"SO6-2-u3-X03","explanation":["시베리아의 기후를 떠올려요.","매우 추운 고위도 지역이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 사하라 사막","㉡ 시베리아","㉢ 히말라야산맥","㉣ 아마존 열대 우림"],"numbered":false,"title":"활동지 — 지도에서 인구가 적게 분포하는 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_basic#8','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',2,'mc','auto','저위도, 중위도, 고위도 가운데 인구가 가장 많이 분포하는 곳과 그 까닭을 알맞게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X04','SO6-2-u3-X02']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"mc","stem":"저위도, 중위도, 고위도 가운데 인구가 가장 많이 분포하는 곳과 그 까닭을 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"중위도 — 온대 기후처럼 온화한 기후가 나타나기 때문에","correct":true},{"t":"고위도 — 냉대 기후와 한대 기후가 나타나기 때문에","mis":"SO6-2-u3-X04"},{"t":"저위도 — 일 년 내내 매우 덥기 때문에","mis":"SO6-2-u3-X04"},{"t":"세 곳 모두 같다 — 위도는 인구와 관계없기 때문에","mis":"SO6-2-u3-X02"}],"explanation":["생활하고 농사짓기 좋은 기후를 떠올려요.","중위도에는 온화한 기후가 나타나요.","그래서 중위도에 사람이 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_basic#9','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',2,'mc','auto','128쪽 원그래프에서 1950년과 비교하여 2023년에 세계 인구에서 차지하는 비율이 줄어든 대륙은 어디인가요?',ARRAY['SO6-2-u3-X05']::text[],true,'{"seq":9,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"mc","stem":"128쪽 원그래프에서 1950년과 비교하여 2023년에 세계 인구에서 차지하는 비율이 줄어든 대륙은 어디인가요?","options":[{"t":"유럽","correct":true},{"t":"아프리카","mis":"SO6-2-u3-X05"},{"t":"아시아","mis":"SO6-2-u3-X05"},{"t":"오세아니아","mis":"SO6-2-u3-X05"}],"explanation":["두 해의 비율을 견줘요.","유럽은 22.0 %에서 9.2 %가 되었어요.","비율이 줄어든 대륙은 유럽이에요."],"asset":{"type":"passage","lines":["1950년(약 25억 명) — 아시아 54.9 % · 유럽 22.0 % · 아프리카 9.1 %","　북아메리카 6.8 % · 남아메리카 6.7 % · 오세아니아 0.5 %","2023년(약 81억 명) — 아시아 59.1 % · 아프리카 18.3 % · 유럽 9.2 %","　남아메리카 8.1 % · 북아메리카 4.7 % · 오세아니아 0.6 %","원의 크기는 세계의 인구수를 나타낸다."],"numbered":false,"title":"128쪽 대륙별 세계 인구의 변화(국제 연합, 2024)"},"variant_rule":{"alt":[{"stem":"128쪽 원그래프에서 1950년과 비교하여 2023년에 비율이 가장 크게 늘어난 대륙은 어디인가요?","options":[{"t":"아프리카","correct":true},{"t":"유럽","mis":"SO6-2-u3-X05"},{"t":"북아메리카","mis":"SO6-2-u3-X05"},{"t":"오세아니아","mis":"SO6-2-u3-X05"}],"explanation":["늘어난 폭을 견줘요.","아프리카는 9.1 %에서 18.3 %가 되었어요.","가장 크게 늘어난 대륙은 아프리카예요."],"asset":{"type":"passage","lines":["1950년(약 25억 명) — 아시아 54.9 % · 유럽 22.0 % · 아프리카 9.1 %","　북아메리카 6.8 % · 남아메리카 6.7 % · 오세아니아 0.5 %","2023년(약 81억 명) — 아시아 59.1 % · 아프리카 18.3 % · 유럽 9.2 %","　남아메리카 8.1 % · 북아메리카 4.7 % · 오세아니아 0.6 %","원의 크기는 세계의 인구수를 나타낸다."],"numbered":false,"title":"128쪽 대륙별 세계 인구의 변화(국제 연합, 2024)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_basic#10','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',3,'mc','auto','128쪽 원그래프를 보고 「유럽의 비율이 줄었으니 유럽에 사는 사람 수도 줄었다」고 말한 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X05','SO6-2-u3-X06']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"mc","stem":"128쪽 원그래프를 보고 「유럽의 비율이 줄었으니 유럽에 사는 사람 수도 줄었다」고 말한 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"비율은 전체에서 차지하는 몫이라, 세계 인구가 약 25억 명에서 약 81억 명으로 늘면 비율이 줄어도 사람 수가 줄었다고 단정할 수 없어","correct":true},{"t":"맞아, 비율이 줄면 사람 수도 반드시 줄어","mis":"SO6-2-u3-X05"},{"t":"유럽의 땅이 좁아졌기 때문에 비율이 줄었어","mis":"SO6-2-u3-X06"},{"t":"세계 인구 전체가 줄었기 때문이야","mis":"SO6-2-u3-X05"}],"explanation":["원의 크기는 세계 인구수를 나타내요.","전체가 세 배 넘게 커졌어요.","비율과 사람 수는 따로 봐야 해요."],"asset":{"type":"passage","lines":["1950년(약 25억 명) — 아시아 54.9 % · 유럽 22.0 % · 아프리카 9.1 %","　북아메리카 6.8 % · 남아메리카 6.7 % · 오세아니아 0.5 %","2023년(약 81억 명) — 아시아 59.1 % · 아프리카 18.3 % · 유럽 9.2 %","　남아메리카 8.1 % · 북아메리카 4.7 % · 오세아니아 0.6 %","원의 크기는 세계의 인구수를 나타낸다."],"numbered":false,"title":"128쪽 대륙별 세계 인구의 변화(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_challenge#1','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',2,'sa','auto','위도와 경도 가운데 인구 분포와 더 관련이 있는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"sa","stem":"위도와 경도 가운데 인구 분포와 더 관련이 있는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["위도"],"explanation":["기후는 적도에서 극지방으로 가며 달라져요.","그 기준이 위도예요.","기후가 인구 분포에 큰 영향을 주니 위도예요."],"mis":"SO6-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_challenge#2','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',2,'ox','auto','같은 나라 안에서는 인구가 고르게 분포해요.',ARRAY['SO6-2-u3-X02']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"ox","stem":"같은 나라 안에서는 인구가 고르게 분포해요.","answer":"X","reason_options":[{"t":"같은 대륙이나 나라 안에서도 지역마다 사람들이 모여 사는 정도가 다르기 때문에","correct":true},{"t":"나라 안의 땅은 모두 환경이 같기 때문에","mis":"SO6-2-u3-X02"}],"mis":"SO6-2-u3-X02","explanation":["지도의 한 나라 안을 보세요.","점이 빽빽한 곳과 드문 곳이 섞여 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["점 1개 — 100만 명","점이 빽빽한 곳 — 동아시아, 남부 아시아, 서부 유럽","점이 드문 곳 — 사막, 열대 우림, 극지방","말풍선 — 세계 인구의 약 90 %가 북반구에 살아요.","가 지역 — 북아메리카 북서쪽 끝의 알래스카"],"numbered":false,"title":"126~127쪽 세계의 인구 분포 지도(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_challenge#3','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',3,'mc','auto','활동지의 ㉢ 히말라야산맥에 인구가 적은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X03','SO6-2-u3-X01']::text[],true,'{"seq":3,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"mc","stem":"활동지의 ㉢ 히말라야산맥에 인구가 적은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"매우 높은 산지라서 평지가 적고 기온이 낮아 농사를 짓기 어렵기 때문에","correct":true},{"t":"강수량이 많고 비옥한 평야가 넓기 때문에","mis":"SO6-2-u3-X03"},{"t":"바다를 끼고 있어 무역이 발달했기 때문에","mis":"SO6-2-u3-X03"},{"t":"산업이 발달해 일자리가 풍부하기 때문에","mis":"SO6-2-u3-X01"}],"explanation":["히말라야산맥은 매우 높은 산지예요.","평지가 적고 기온이 낮아요.","농사짓기 어려워 사람이 적어요."],"asset":{"type":"passage","lines":["㉠ 사하라 사막","㉡ 시베리아","㉢ 히말라야산맥","㉣ 아마존 열대 우림"],"numbered":false,"title":"활동지 — 지도에서 인구가 적게 분포하는 네 곳"},"variant_rule":{"alt":[{"stem":"활동지의 ㉣ 아마존 열대 우림에 인구가 적은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기온이 높고 강수량이 많아 열대 우림이 우거져 있기 때문에","correct":true},{"t":"기온이 매우 낮아 식물이 자라기 어렵기 때문에","mis":"SO6-2-u3-X03"},{"t":"강수량이 매우 적어 물이 없기 때문에","mis":"SO6-2-u3-X03"},{"t":"교통이 편리하고 산업이 발달했기 때문에","mis":"SO6-2-u3-X01"}],"explanation":["아마존은 열대 우림이에요.","덥고 비가 많아 숲이 빽빽해요.","사람이 모여 살기 어려워요."],"asset":{"type":"passage","lines":["㉠ 사하라 사막","㉡ 시베리아","㉢ 히말라야산맥","㉣ 아마존 열대 우림"],"numbered":false,"title":"활동지 — 지도에서 인구가 적게 분포하는 네 곳"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_challenge#4','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',3,'mc','auto','128쪽 원그래프로 볼 때 2023년에 아시아와 아프리카에 사는 사람은 세계 인구의 약 몇 % 이상인가요?',ARRAY['SO6-2-u3-X05','SO6-2-u3-X07']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"mc","stem":"128쪽 원그래프로 볼 때 2023년에 아시아와 아프리카에 사는 사람은 세계 인구의 약 몇 % 이상인가요?","options":[{"t":"약 70 % 이상","correct":true},{"t":"세계 인구의 절반에 못 미친다","mis":"SO6-2-u3-X05"},{"t":"오세아니아보다 적다","mis":"SO6-2-u3-X07"},{"t":"두 자료로는 알 수 없다","mis":"SO6-2-u3-X05"}],"explanation":["두 대륙의 비율을 더해요.","59.1 %와 18.3 %를 더하면 77.4 %예요.","세계 인구의 70 % 이상이에요."],"asset":{"type":"passage","lines":["1950년(약 25억 명) — 아시아 54.9 % · 유럽 22.0 % · 아프리카 9.1 %","　북아메리카 6.8 % · 남아메리카 6.7 % · 오세아니아 0.5 %","2023년(약 81억 명) — 아시아 59.1 % · 아프리카 18.3 % · 유럽 9.2 %","　남아메리카 8.1 % · 북아메리카 4.7 % · 오세아니아 0.6 %","원의 크기는 세계의 인구수를 나타낸다."],"numbered":false,"title":"128쪽 대륙별 세계 인구의 변화(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_challenge#5','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',3,'mc','auto','1950년과 비교하여 2023년에 세계 인구에서 차지하는 비율이 늘어난 대륙을 모두 바르게 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X05']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"mc","stem":"1950년과 비교하여 2023년에 세계 인구에서 차지하는 비율이 늘어난 대륙을 모두 바르게 든 것은 어느 것인가요?","options":[{"t":"아프리카, 아시아, 남아메리카, 오세아니아","correct":true},{"t":"아프리카, 아시아","mis":"SO6-2-u3-X05"},{"t":"유럽, 북아메리카","mis":"SO6-2-u3-X05"},{"t":"여섯 대륙 모두","mis":"SO6-2-u3-X05"}],"explanation":["대륙마다 두 해의 비율을 견줘요.","남아메리카 6.7 %→8.1 %, 오세아니아 0.5 %→0.6 %도 늘었어요.","네 대륙이 늘었어요."],"asset":{"type":"passage","lines":["1950년(약 25억 명) — 아시아 54.9 % · 유럽 22.0 % · 아프리카 9.1 %","　북아메리카 6.8 % · 남아메리카 6.7 % · 오세아니아 0.5 %","2023년(약 81억 명) — 아시아 59.1 % · 아프리카 18.3 % · 유럽 9.2 %","　남아메리카 8.1 % · 북아메리카 4.7 % · 오세아니아 0.6 %","원의 크기는 세계의 인구수를 나타낸다."],"numbered":false,"title":"128쪽 대륙별 세계 인구의 변화(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_challenge#6','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C1',3,'mc','auto','125쪽 붙임딱지 ㉠과 ㉡이 말하는 요인을 알맞게 나눈 것은 어느 것인가요?',ARRAY['SO6-2-u3-X01']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C1","difficulty":3,"kind":"mc","stem":"125쪽 붙임딱지 ㉠과 ㉡이 말하는 요인을 알맞게 나눈 것은 어느 것인가요?","options":[{"t":"㉠ 인문환경(산업) · ㉡ 자연환경(강수량·지형)","correct":true},{"t":"㉠ 자연환경 · ㉡ 인문환경","mis":"SO6-2-u3-X01"},{"t":"㉠과 ㉡ 모두 자연환경","mis":"SO6-2-u3-X01"},{"t":"㉠과 ㉡ 모두 인문환경","mis":"SO6-2-u3-X01"}],"explanation":["사람이 만든 것과 자연이 만든 것을 가려요.","㉠의 산업은 사람이 발달시킨 거예요.","㉡의 강수량과 평야는 자연환경이에요."],"asset":{"type":"passage","lines":["㉠ 일찍부터 과학과 기술이 발전하여 다양한 산업이 발달했다.","㉡ 강수량이 많고 비옥한 평야가 있어 농사에 유리하다.","㉢ 바다를 이용해 무역을 하거나 해산물을 쉽게 얻을 수 있다.","㉣ 기온이 높고 강수량이 많아 열대 우림이 우거져 있다.","㉤ 강수량이 매우 적어 물을 구하기 어렵다.","㉥ 기온이 매우 낮아 식물이 자라기 어렵다."],"numbered":false,"title":"125쪽 사진에 붙일 붙임딱지 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_challenge#7','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',3,'error','auto','127쪽 지도를 보고 친구들이 세계 인구 분포를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X04','SO6-2-u3-X03','SO6-2-u3-X01']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"error","stem":"127쪽 지도를 보고 친구들이 세계 인구 분포를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「세계 인구의 대부분은 육지가 적은 남반구에 살아.」","correct":true,"mis_target":"SO6-2-u3-X04"},{"t":"서아 — 「해발 고도가 낮은 평야나 해안 지역에 사람이 많이 모여 살아.」","mis":"SO6-2-u3-X03"},{"t":"지후 — 「산업이 발달한 지역에도 사람이 많아.」","mis":"SO6-2-u3-X01"}],"explanation":["말풍선을 다시 읽어요.","세계 인구의 약 90 %가 육지가 많은 북반구에 살아요.","도윤이가 거꾸로 말했어요."],"asset":{"type":"passage","lines":["점 1개 — 100만 명","점이 빽빽한 곳 — 동아시아, 남부 아시아, 서부 유럽","점이 드문 곳 — 사막, 열대 우림, 극지방","말풍선 — 세계 인구의 약 90 %가 북반구에 살아요.","가 지역 — 북아메리카 북서쪽 끝의 알래스카"],"numbered":false,"title":"126~127쪽 세계의 인구 분포 지도(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_challenge#8','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C1',4,'mc','auto','125쪽 본문으로 옛날과 오늘날 사람들이 모여 산 곳을 알맞게 견준 것은 어느 것인가요?',ARRAY['SO6-2-u3-X01','SO6-2-u3-X02']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C1","difficulty":4,"kind":"mc","stem":"125쪽 본문으로 옛날과 오늘날 사람들이 모여 산 곳을 알맞게 견준 것은 어느 것인가요?","options":[{"t":"옛날 — 기후가 온화하거나 평야·해안처럼 자연환경이 유리한 곳 / 오늘날 — 일자리·교통·교육과 문화 시설이 갖추어진 곳","correct":true},{"t":"옛날 — 공장이 많은 도시 / 오늘날 — 사막과 극지방","mis":"SO6-2-u3-X01"},{"t":"옛날과 오늘날 모두 아무 곳에나 고르게","mis":"SO6-2-u3-X02"},{"t":"옛날과 오늘날 모두 자연환경만 따진다","mis":"SO6-2-u3-X01"}],"explanation":["옛날에는 자연환경이 중요했어요.","오늘날에는 인문환경도 크게 작용해요.","모여 사는 까닭이 넓어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_challenge#9','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',4,'essay','teacher','128쪽 원그래프의 변화를 바탕으로 2050년 이후 대륙별 세계 인구 비율이 어떻게 될지 예상하고, 그렇게 생각한 근거를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u3-C2","difficulty":4,"kind":"essay","stem":"128쪽 원그래프의 변화를 바탕으로 2050년 이후 대륙별 세계 인구 비율이 어떻게 될지 예상하고, 그렇게 생각한 근거를 쓰세요.","answer_guide":{"answer":"예: 세계 인구에서 아프리카가 차지하는 비율은 계속 늘어나고, 유럽의 비율은 줄어들 것 같다. 1950년 9.1 %였던 아프리카는 2023년 18.3 %로 크게 늘었고, 유럽은 22.0 %에서 9.2 %로 줄었기 때문이다.","scoring_points":["늘어날 대륙과 줄어들 대륙을 예상했는가","그래프의 두 해 비율을 근거로 들었는가","비율과 인구수를 헷갈리지 않았는가"]},"explanation":["두 해의 변화를 먼저 읽어요.","늘어난 대륙과 줄어든 대륙을 가려요.","변화가 이어진다고 보고 예상해요."],"asset":{"type":"passage","lines":["1950년(약 25억 명) — 아시아 54.9 % · 유럽 22.0 % · 아프리카 9.1 %","　북아메리카 6.8 % · 남아메리카 6.7 % · 오세아니아 0.5 %","2023년(약 81억 명) — 아시아 59.1 % · 아프리카 18.3 % · 유럽 9.2 %","　남아메리카 8.1 % · 북아메리카 4.7 % · 오세아니아 0.6 %","원의 크기는 세계의 인구수를 나타낸다."],"numbered":false,"title":"128쪽 대륙별 세계 인구의 변화(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L01_challenge#10','soc',6,2,'u3','L01','tb_g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',4,'essay','teacher','127쪽 본문과 지도를 바탕으로 세계 인구가 많이 분포하는 곳의 특징을 반구·위도·지형·산업의 네 가지로 정리해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C2","difficulty":4,"kind":"essay","stem":"127쪽 본문과 지도를 바탕으로 세계 인구가 많이 분포하는 곳의 특징을 반구·위도·지형·산업의 네 가지로 정리해 쓰세요.","answer_guide":{"answer":"예: 세계 인구의 대부분은 육지가 많은 북반구에 분포한다. 기후가 온화한 중위도 지역에 많고, 해발 고도가 낮은 평야 지역이나 해안 지역에 많다. 또 산업이 발달해 일자리가 풍부한 지역에 많은 사람이 모여 산다.","scoring_points":["북반구를 썼는가","온화한 중위도와 평야·해안을 썼는가","산업이 발달한 지역을 썼는가"]},"explanation":["반구는 북반구예요.","위도는 중위도, 지형은 평야와 해안이에요.","산업과 일자리도 함께 써요."],"asset":{"type":"passage","lines":["점 1개 — 100만 명","점이 빽빽한 곳 — 동아시아, 남부 아시아, 서부 유럽","점이 드문 곳 — 사막, 열대 우림, 극지방","말풍선 — 세계 인구의 약 90 %가 북반구에 살아요.","가 지역 — 북아메리카 북서쪽 끝의 알래스카"],"numbered":false,"title":"126~127쪽 세계의 인구 분포 지도(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_basic#1','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',1,'ox','auto','꼭 기억해요 — 대체로 오세아니아에 있는 나라들은 인구수가 많습니다.',ARRAY['SO6-2-u3-X06']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C3","difficulty":1,"kind":"ox","stem":"꼭 기억해요 — 대체로 오세아니아에 있는 나라들은 인구수가 많습니다.","answer":"X","reason_options":[{"t":"대체로 아시아에 있는 나라들은 인구수가 많고 오세아니아에 있는 나라들은 적기 때문에","correct":true},{"t":"오세아니아는 면적이 넓어 인구수도 많기 때문에","mis":"SO6-2-u3-X06"}],"mis":"SO6-2-u3-X06","explanation":["129쪽 지도의 색을 견줘요.","오세아니아에는 1억 명 넘는 나라가 없어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_basic#2','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',1,'mc','auto','130쪽 네 나라 가운데 세계에서 인구수가 가장 많은 나라는 어디인가요?',ARRAY['SO6-2-u3-X07','SO6-2-u3-X06']::text[],true,'{"seq":2,"concept":"SO6-2-u3-C3","difficulty":1,"kind":"mc","stem":"130쪽 네 나라 가운데 세계에서 인구수가 가장 많은 나라는 어디인가요?","options":[{"t":"인도","correct":true},{"t":"미국","mis":"SO6-2-u3-X07"},{"t":"리비아","mis":"SO6-2-u3-X06"},{"t":"투발루","mis":"SO6-2-u3-X07"}],"explanation":["네 나라의 인구수를 견줘요.","인도는 약 14억 3,807만 명이에요.","가장 많은 나라는 인도예요."],"asset":{"type":"passage","lines":["① 인도 — 약 14억 3,807만 명 · 세계에서 인구수가 가장 많다.","　강수량이 많고 토양이 비옥해 농업 발달 · 출생률이 높아 증가 전망","② 미국 — 약 3억 4,348만 명 · 세계에서 세 번째로 많다.","　기후가 온화하고 다양한 산업 발달 · 일자리를 찾아 이민 오는 사람이 많다.","③ 투발루 — 9,816명 · 남태평양의 작은 섬나라","　기후변화로 바다에 잠길 위험 · 주민들이 다른 나라로 이주할 계획","④ 리비아 — 약 731만 명 · 국토 대부분이 건조한 기후의 사막","　그래서 국토의 면적에 비해 인구수가 매우 적다."],"numbered":false,"title":"130쪽 네 나라의 인구(2023년 기준, 국제 연합, 2024)"},"variant_rule":{"alt":[{"stem":"130쪽 네 나라 가운데 인구수가 가장 적은 나라는 어디인가요?","options":[{"t":"투발루","correct":true},{"t":"리비아","mis":"SO6-2-u3-X07"},{"t":"미국","mis":"SO6-2-u3-X07"},{"t":"인도","mis":"SO6-2-u3-X07"}],"explanation":["가장 작은 수를 찾아요.","투발루는 9,816명이에요.","가장 적은 나라는 투발루예요."],"asset":{"type":"passage","lines":["① 인도 — 약 14억 3,807만 명 · 세계에서 인구수가 가장 많다.","　강수량이 많고 토양이 비옥해 농업 발달 · 출생률이 높아 증가 전망","② 미국 — 약 3억 4,348만 명 · 세계에서 세 번째로 많다.","　기후가 온화하고 다양한 산업 발달 · 일자리를 찾아 이민 오는 사람이 많다.","③ 투발루 — 9,816명 · 남태평양의 작은 섬나라","　기후변화로 바다에 잠길 위험 · 주민들이 다른 나라로 이주할 계획","④ 리비아 — 약 731만 명 · 국토 대부분이 건조한 기후의 사막","　그래서 국토의 면적에 비해 인구수가 매우 적다."],"numbered":false,"title":"130쪽 네 나라의 인구(2023년 기준, 국제 연합, 2024)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_basic#3','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',1,'sa','auto','「자기 나라를 떠나 다른 나라로 이주하는 일」을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C3","difficulty":1,"kind":"sa","stem":"「자기 나라를 떠나 다른 나라로 이주하는 일」을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["이민"],"explanation":["130쪽 낱말 풀이예요.","미국에는 일자리를 찾아 오는 사람이 많아요.","이 일을 이민이라고 해요."],"mis":"SO6-2-u3-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_basic#4','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',1,'mc','auto','129쪽 지도에서 인구수가 10억 명 이상인 나라를 알맞게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X07']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C3","difficulty":1,"kind":"mc","stem":"129쪽 지도에서 인구수가 10억 명 이상인 나라를 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"인도와 중국","correct":true},{"t":"미국과 러시아","mis":"SO6-2-u3-X06"},{"t":"인도와 미국","mis":"SO6-2-u3-X07"},{"t":"인도네시아와 브라질","mis":"SO6-2-u3-X07"}],"explanation":["가장 진한 색의 나라를 찾아요.","두 나라 모두 아시아에 있어요.","인도와 중국이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_basic#5','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',2,'mc','auto','리비아가 국토의 면적에 비해 인구수가 매우 적은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X08','SO6-2-u3-X06','SO6-2-u3-X07']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"리비아가 국토의 면적에 비해 인구수가 매우 적은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"국토 대부분이 건조한 기후가 나타나는 사막이기 때문에","correct":true},{"t":"출생률이 매우 높기 때문에","mis":"SO6-2-u3-X08"},{"t":"국토의 면적이 매우 좁기 때문에","mis":"SO6-2-u3-X06"},{"t":"일자리를 찾아 이민 오는 사람이 많기 때문에","mis":"SO6-2-u3-X07"}],"explanation":["130쪽 리비아 설명을 읽어요.","국토 대부분이 사막이에요.","사람이 살 만한 곳이 좁아 인구가 적어요."],"asset":{"type":"passage","lines":["① 인도 — 약 14억 3,807만 명 · 세계에서 인구수가 가장 많다.","　강수량이 많고 토양이 비옥해 농업 발달 · 출생률이 높아 증가 전망","② 미국 — 약 3억 4,348만 명 · 세계에서 세 번째로 많다.","　기후가 온화하고 다양한 산업 발달 · 일자리를 찾아 이민 오는 사람이 많다.","③ 투발루 — 9,816명 · 남태평양의 작은 섬나라","　기후변화로 바다에 잠길 위험 · 주민들이 다른 나라로 이주할 계획","④ 리비아 — 약 731만 명 · 국토 대부분이 건조한 기후의 사막","　그래서 국토의 면적에 비해 인구수가 매우 적다."],"numbered":false,"title":"130쪽 네 나라의 인구(2023년 기준, 국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_basic#6','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',2,'match','auto','130쪽 네 나라와 인구 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"match","stem":"130쪽 네 나라와 인구 특징을 알맞게 이으세요.","pairs":[{"l":"인도","r":"강수량이 많고 토양이 비옥해 농업 발달"},{"l":"미국","r":"다양한 산업 발달, 이민 오는 사람이 많음"},{"l":"투발루","r":"기후변화로 바다에 잠길 위험"},{"l":"리비아","r":"국토 대부분이 건조한 사막"}],"mis":"SO6-2-u3-X07","explanation":["나라마다 설명을 읽어요.","인도와 미국은 인구가 많은 까닭이에요.","투발루와 리비아는 적은 까닭이에요."],"asset":{"type":"passage","lines":["① 인도 — 약 14억 3,807만 명 · 세계에서 인구수가 가장 많다.","　강수량이 많고 토양이 비옥해 농업 발달 · 출생률이 높아 증가 전망","② 미국 — 약 3억 4,348만 명 · 세계에서 세 번째로 많다.","　기후가 온화하고 다양한 산업 발달 · 일자리를 찾아 이민 오는 사람이 많다.","③ 투발루 — 9,816명 · 남태평양의 작은 섬나라","　기후변화로 바다에 잠길 위험 · 주민들이 다른 나라로 이주할 계획","④ 리비아 — 약 731만 명 · 국토 대부분이 건조한 기후의 사막","　그래서 국토의 면적에 비해 인구수가 매우 적다."],"numbered":false,"title":"130쪽 네 나라의 인구(2023년 기준, 국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_basic#7','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',2,'ox','auto','꼭 기억해요 — 나라의 인구수는 출생과 사망, 인구의 이동, 환경의 변화 등에 따라 달라집니다.',ARRAY['SO6-2-u3-X08']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"ox","stem":"꼭 기억해요 — 나라의 인구수는 출생과 사망, 인구의 이동, 환경의 변화 등에 따라 달라집니다.","answer":"O","reason_options":[{"t":"태어나는 사람, 사망하는 사람, 옮겨 오고 떠나는 사람, 환경 변화에 따라 인구수가 바뀌기 때문에","correct":true},{"t":"나라의 인구수는 한번 정해지면 바뀌지 않기 때문에","mis":"SO6-2-u3-X08"}],"mis":"SO6-2-u3-X08","explanation":["131쪽 본문이에요.","투발루처럼 환경 변화로도 인구가 바뀌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_basic#8','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',2,'mc','auto','129쪽 지도에서 인구수가 1억 명 이상인 나라가 하나도 없는 대륙은 어디인가요?',ARRAY['SO6-2-u3-X07']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"129쪽 지도에서 인구수가 1억 명 이상인 나라가 하나도 없는 대륙은 어디인가요?","options":[{"t":"오세아니아","correct":true},{"t":"아시아","mis":"SO6-2-u3-X07"},{"t":"아프리카","mis":"SO6-2-u3-X07"},{"t":"남아메리카","mis":"SO6-2-u3-X07"}],"explanation":["대륙별 목록을 살펴봐요.","오세아니아 칸은 「없음」이에요.","답은 오세아니아예요."],"asset":{"type":"passage","lines":["아시아 — 인도, 중국, 인도네시아, 파키스탄, 방글라데시, 일본, 필리핀, 베트남","유럽 — 러시아","북아메리카 — 미국, 멕시코","남아메리카 — 브라질","아프리카 — 나이지리아, 에티오피아, 이집트, 콩고 민주 공화국","오세아니아 — 없음"],"title":"129쪽 지도 — 인구수가 1억 명 이상인 나라(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_basic#9','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',2,'mc','auto','「인구 성장률」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X11','SO6-2-u3-X08']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"「인구 성장률」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"일정한 지역 안에 사는 인구가 증가하는 비율","correct":true},{"t":"일정한 면적 안에 사는 인구수","mis":"SO6-2-u3-X09"},{"t":"연령과 성을 기준으로 한 인구의 짜임새","mis":"SO6-2-u3-X11"},{"t":"한 나라에 사는 전체 사람 수","mis":"SO6-2-u3-X08"}],"explanation":["131쪽 낱말 풀이예요.","인구가 늘어나는 빠르기를 나타내요.","증가하는 비율이에요."],"asset":{"type":"passage","lines":["인구 성장률 — 일정한 지역 안에 사는 인구가 증가하는 비율","3 % 이상인 나라가 가장 많은 대륙 — 아프리카","인구가 감소하는 나라가 가장 많은 대륙 — 유럽","인구가 감소하는 나라의 예 — 이탈리아, 그리스, 러시아, 일본, 쿠바 등"],"numbered":false,"title":"131쪽 나라별 인구 성장률 지도(국제 연합, 2018~2023)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_basic#10','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_basic','lesson_basic','SO6-2-u3-C3',3,'mc','auto','131쪽 지도에 나타난 인구 성장률이 지속된다면 아프리카 나라들의 인구수는 어떻게 될까요?',ARRAY['SO6-2-u3-X08','SO6-2-u3-X06']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"131쪽 지도에 나타난 인구 성장률이 지속된다면 아프리카 나라들의 인구수는 어떻게 될까요?","options":[{"t":"인구가 성장하는 나라가 많으므로 지금보다 늘어날 것이다","correct":true},{"t":"인구가 감소하는 나라가 가장 많으므로 줄어들 것이다","mis":"SO6-2-u3-X08"},{"t":"성장률과 관계없이 그대로일 것이다","mis":"SO6-2-u3-X08"},{"t":"면적이 넓으므로 반드시 세계에서 가장 많아질 것이다","mis":"SO6-2-u3-X06"}],"explanation":["아프리카에는 성장률 3 % 이상인 나라가 많아요.","성장률이 높으면 인구가 늘어요.","앞으로 인구수가 늘어날 거예요."],"asset":{"type":"passage","lines":["인구 성장률 — 일정한 지역 안에 사는 인구가 증가하는 비율","3 % 이상인 나라가 가장 많은 대륙 — 아프리카","인구가 감소하는 나라가 가장 많은 대륙 — 유럽","인구가 감소하는 나라의 예 — 이탈리아, 그리스, 러시아, 일본, 쿠바 등"],"numbered":false,"title":"131쪽 나라별 인구 성장률 지도(국제 연합, 2018~2023)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_challenge#1','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',2,'mc','auto','129쪽 말풍선 「나라의 면적이 넓으면 인구수도 많나요?」에 대한 답으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X01']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"129쪽 말풍선 「나라의 면적이 넓으면 인구수도 많나요?」에 대한 답으로 알맞은 것은 어느 것인가요?","options":[{"t":"반드시 그렇지는 않아요. 사람들이 살기 어려운 지역에 있는 나라들은 면적에 비해 인구수가 적어요.","correct":true},{"t":"네, 면적이 넓을수록 언제나 인구수가 많아요.","mis":"SO6-2-u3-X06"},{"t":"면적이 좁을수록 반드시 인구수가 많아요.","mis":"SO6-2-u3-X06"},{"t":"면적과 환경은 인구수와 아무 관계가 없어요.","mis":"SO6-2-u3-X01"}],"explanation":["리비아를 떠올려요.","넓어도 사막이면 살 곳이 좁아요.","면적만으로 인구수를 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_challenge#2','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',2,'sa','auto','131쪽 지도에서 인구가 감소하는 나라가 가장 많이 모여 있는 대륙은 어디인가요?','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"sa","stem":"131쪽 지도에서 인구가 감소하는 나라가 가장 많이 모여 있는 대륙은 어디인가요?","answer":["유럽"],"explanation":["「인구 감소」 색을 찾아요.","이탈리아·그리스 등이 모여 있어요.","답은 유럽이에요."],"asset":{"type":"passage","lines":["인구 성장률 — 일정한 지역 안에 사는 인구가 증가하는 비율","3 % 이상인 나라가 가장 많은 대륙 — 아프리카","인구가 감소하는 나라가 가장 많은 대륙 — 유럽","인구가 감소하는 나라의 예 — 이탈리아, 그리스, 러시아, 일본, 쿠바 등"],"numbered":false,"title":"131쪽 나라별 인구 성장률 지도(국제 연합, 2018~2023)"},"mis":"SO6-2-u3-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_challenge#3','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',3,'mc','auto','투발루의 인구는 앞으로 어떻게 변할지, 그 까닭과 함께 알맞게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X07','SO6-2-u3-X08','SO6-2-u3-X06']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"투발루의 인구는 앞으로 어떻게 변할지, 그 까닭과 함께 알맞게 말한 것은 어느 것인가요?","options":[{"t":"기후변화로 나라가 바다에 잠길 위험이 있어 주민들이 다른 나라로 이주하면 인구가 줄어들 것이다","correct":true},{"t":"섬나라이므로 이민 오는 사람이 많아 인구가 크게 늘 것이다","mis":"SO6-2-u3-X07"},{"t":"인구수는 환경과 관계없으므로 그대로일 것이다","mis":"SO6-2-u3-X08"},{"t":"면적이 작으니 인구가 저절로 늘 것이다","mis":"SO6-2-u3-X06"}],"explanation":["투발루 설명을 다시 읽어요.","주민들이 다른 나라로 이주할 계획이에요.","떠나는 사람이 많으면 인구가 줄어요."],"asset":{"type":"passage","lines":["① 인도 — 약 14억 3,807만 명 · 세계에서 인구수가 가장 많다.","　강수량이 많고 토양이 비옥해 농업 발달 · 출생률이 높아 증가 전망","② 미국 — 약 3억 4,348만 명 · 세계에서 세 번째로 많다.","　기후가 온화하고 다양한 산업 발달 · 일자리를 찾아 이민 오는 사람이 많다.","③ 투발루 — 9,816명 · 남태평양의 작은 섬나라","　기후변화로 바다에 잠길 위험 · 주민들이 다른 나라로 이주할 계획","④ 리비아 — 약 731만 명 · 국토 대부분이 건조한 기후의 사막","　그래서 국토의 면적에 비해 인구수가 매우 적다."],"numbered":false,"title":"130쪽 네 나라의 인구(2023년 기준, 국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_challenge#4','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',3,'mc','auto','어떤 나라의 인구수가 계속 늘어나고 있다면 어떤 요인이 영향을 주었다고 추론할 수 있을까요?',ARRAY['SO6-2-u3-X08','SO6-2-u3-X06']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"어떤 나라의 인구수가 계속 늘어나고 있다면 어떤 요인이 영향을 주었다고 추론할 수 있을까요?","options":[{"t":"태어나는 사람이 사망하는 사람보다 많거나, 다른 나라에서 이민 오는 사람이 많은 경우","correct":true},{"t":"사망하는 사람이 태어나는 사람보다 많은 경우","mis":"SO6-2-u3-X08"},{"t":"다른 나라로 떠나는 사람이 많은 경우","mis":"SO6-2-u3-X08"},{"t":"나라의 면적이 넓어진 경우","mis":"SO6-2-u3-X06"}],"explanation":["인구수를 바꾸는 요인을 떠올려요.","출생과 사망, 인구의 이동이에요.","들어오는 사람이 많을 때 늘어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_challenge#5','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',3,'error','auto','129~131쪽을 공부한 뒤 친구들이 나라별 인구수를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X07']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"error","stem":"129~131쪽을 공부한 뒤 친구들이 나라별 인구수를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「러시아는 면적이 아주 넓으니까 인구수도 세계에서 가장 많을 거야.」","correct":true,"mis_target":"SO6-2-u3-X06"},{"t":"주안 — 「인구수가 많은 나라가 모여 있는 대륙은 아시아야.」","mis":"SO6-2-u3-X07"},{"t":"예나 — 「리비아는 사막이 넓어서 면적에 비해 인구수가 적어.」","mis":"SO6-2-u3-X06"}],"explanation":["129쪽 지도를 다시 봐요.","10억 명 넘는 나라는 인도와 중국이에요.","하린이가 면적과 인구수를 같게 봤어요."],"asset":{"type":"passage","lines":["아시아 — 인도, 중국, 인도네시아, 파키스탄, 방글라데시, 일본, 필리핀, 베트남","유럽 — 러시아","북아메리카 — 미국, 멕시코","남아메리카 — 브라질","아프리카 — 나이지리아, 에티오피아, 이집트, 콩고 민주 공화국","오세아니아 — 없음"],"title":"129쪽 지도 — 인구수가 1억 명 이상인 나라(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_challenge#6','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',3,'mc','auto','131쪽 말풍선에서 사람들이 다른 나라로 이동하는 까닭으로 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X09','SO6-2-u3-X08']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"131쪽 말풍선에서 사람들이 다른 나라로 이동하는 까닭으로 든 것은 어느 것인가요?","options":[{"t":"일자리를 얻거나 전쟁을 피하는 등 다양한 목적 때문에","correct":true},{"t":"나라의 면적을 넓히기 위해서","mis":"SO6-2-u3-X06"},{"t":"인구 밀도를 낮추라는 법 때문에","mis":"SO6-2-u3-X09"},{"t":"출생률을 높이기 위해서","mis":"SO6-2-u3-X08"}],"explanation":["말풍선의 답을 읽어요.","일자리와 전쟁이 나왔어요.","여러 목적으로 이동해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_challenge#7','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',3,'mc','auto','일자리가 많아 다른 나라 사람들이 많이 옮겨 오는 나라의 인구수는 어떻게 될까요?',ARRAY['SO6-2-u3-X08','SO6-2-u3-X06']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"일자리가 많아 다른 나라 사람들이 많이 옮겨 오는 나라의 인구수는 어떻게 될까요?","options":[{"t":"인구의 이동으로 인구수가 늘어난다","correct":true},{"t":"옮겨 온 사람은 인구에 포함되지 않아 그대로다","mis":"SO6-2-u3-X08"},{"t":"면적이 그대로이므로 인구수도 그대로다","mis":"SO6-2-u3-X06"},{"t":"반드시 줄어든다","mis":"SO6-2-u3-X08"}],"explanation":["인구의 이동도 인구수를 바꿔요.","들어오는 사람이 늘어요.","그래서 인구수가 늘어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_challenge#8','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',4,'essay','teacher','130쪽 네 나라 가운데 한 나라를 골라 인구수와 인구 특징을 소개하고, 그 특징을 자연환경이나 인문환경과 이어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u3-C3","difficulty":4,"kind":"essay","stem":"130쪽 네 나라 가운데 한 나라를 골라 인구수와 인구 특징을 소개하고, 그 특징을 자연환경이나 인문환경과 이어 쓰세요.","answer_guide":{"answer":"예: 리비아의 인구수는 약 731만 명이다. 리비아는 국토 대부분이 건조한 기후가 나타나는 사막으로 이루어져 있어 사람이 살기 어려운 곳이 많다. 그래서 넓은 국토 면적에 비해 인구가 매우 적은 편이다.","scoring_points":["나라와 인구수를 바르게 썼는가","인구 특징을 썼는가","특징을 자연환경이나 인문환경과 이어 썼는가"]},"explanation":["자료에서 인구수를 찾아요.","많은지 적은지 특징을 써요.","까닭을 환경과 이어요."],"asset":{"type":"passage","lines":["① 인도 — 약 14억 3,807만 명 · 세계에서 인구수가 가장 많다.","　강수량이 많고 토양이 비옥해 농업 발달 · 출생률이 높아 증가 전망","② 미국 — 약 3억 4,348만 명 · 세계에서 세 번째로 많다.","　기후가 온화하고 다양한 산업 발달 · 일자리를 찾아 이민 오는 사람이 많다.","③ 투발루 — 9,816명 · 남태평양의 작은 섬나라","　기후변화로 바다에 잠길 위험 · 주민들이 다른 나라로 이주할 계획","④ 리비아 — 약 731만 명 · 국토 대부분이 건조한 기후의 사막","　그래서 국토의 면적에 비해 인구수가 매우 적다."],"numbered":false,"title":"130쪽 네 나라의 인구(2023년 기준, 국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_challenge#9','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',4,'mc','auto','세계 여러 나라의 인구수를 공부하는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X23','SO6-2-u3-X24']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C3","difficulty":4,"kind":"mc","stem":"세계 여러 나라의 인구수를 공부하는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"정확한 순위를 외우기보다 자료를 살펴 인구 특징과 까닭을 찾고, 인구가 많거나 적다고 그 나라를 낮추어 보지 않는다","correct":true},{"t":"나라별 인구수와 순위를 모두 외운다","mis":"SO6-2-u3-X23"},{"t":"인구가 적은 나라는 뒤떨어진 나라라고 생각한다","mis":"SO6-2-u3-X24"},{"t":"인구가 많은 나라는 살기 나쁜 나라라고 생각한다","mis":"SO6-2-u3-X24"}],"explanation":["순위 외우기가 목표가 아니에요.","자료에서 특징과 까닭을 읽어요.","특정 나라에 편견을 갖지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L02_challenge#10','soc',6,2,'u3','L02','tb_g6_2_soc_u3_L02_challenge','lesson_challenge','SO6-2-u3-C3',4,'essay','teacher','인도와 투발루의 인구수가 앞으로 어떻게 달라질지 예상하고, 인구수를 바꾸는 요인(출생·사망·인구의 이동·환경의 변화) 가운데 무엇이 작용하는지 각각 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C3","difficulty":4,"kind":"essay","stem":"인도와 투발루의 인구수가 앞으로 어떻게 달라질지 예상하고, 인구수를 바꾸는 요인(출생·사망·인구의 이동·환경의 변화) 가운데 무엇이 작용하는지 각각 쓰세요.","answer_guide":{"answer":"예: 인도는 출생률이 높아 인구수가 계속 늘어날 것이다. 출생이 작용한다. 투발루는 기후변화로 나라가 바다에 잠길 위험이 있어 주민들이 다른 나라로 이주하면 인구수가 줄어들 것이다. 환경의 변화와 인구의 이동이 작용한다.","scoring_points":["인도의 변화를 예상하고 요인을 썼는가","투발루의 변화를 예상하고 요인을 썼는가","자료의 내용을 근거로 썼는가"]},"explanation":["인도는 출생률이 높아요.","투발루는 이주할 계획이에요.","요인을 하나씩 짝지어요."],"asset":{"type":"passage","lines":["① 인도 — 약 14억 3,807만 명 · 세계에서 인구수가 가장 많다.","　강수량이 많고 토양이 비옥해 농업 발달 · 출생률이 높아 증가 전망","② 미국 — 약 3억 4,348만 명 · 세계에서 세 번째로 많다.","　기후가 온화하고 다양한 산업 발달 · 일자리를 찾아 이민 오는 사람이 많다.","③ 투발루 — 9,816명 · 남태평양의 작은 섬나라","　기후변화로 바다에 잠길 위험 · 주민들이 다른 나라로 이주할 계획","④ 리비아 — 약 731만 명 · 국토 대부분이 건조한 기후의 사막","　그래서 국토의 면적에 비해 인구수가 매우 적다."],"numbered":false,"title":"130쪽 네 나라의 인구(2023년 기준, 국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_basic#1','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',1,'sa','auto','꼭 기억해요 — 「세계 여러 나라는 면적과 인구수에 따라 (    )이/가 다르게 나타납니다.」 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"sa","stem":"꼭 기억해요 — 「세계 여러 나라는 면적과 인구수에 따라 (    )이/가 다르게 나타납니다.」 빈칸에 알맞은 말을 쓰세요.","answer":["인구 밀도","인구밀도"],"explanation":["면적과 인구수를 함께 보는 말이에요.","1 km² 안에 사는 인구수예요.","빈칸은 인구 밀도예요."],"mis":"SO6-2-u3-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_basic#2','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',1,'ox','auto','꼭 기억해요 — 캐나다는 냉대 기후가 넓게 나타나 국토 면적에 비해 인구 밀도가 높습니다.',ARRAY['SO6-2-u3-X10']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"ox","stem":"꼭 기억해요 — 캐나다는 냉대 기후가 넓게 나타나 국토 면적에 비해 인구 밀도가 높습니다.","answer":"X","reason_options":[{"t":"냉대 기후가 넓어 농사지을 땅이 적으므로 인구 밀도가 매우 낮기 때문에","correct":true},{"t":"캐나다는 면적이 넓어 인구 밀도도 높기 때문에","mis":"SO6-2-u3-X10"}],"mis":"SO6-2-u3-X10","explanation":["캐나다의 인구 밀도를 찾아요.","약 4명/km²로 매우 낮아요.","그래서 X예요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km²","　국토 대부분이 평야 · 기후가 온화 · 벼농사 발달","캐나다 — 약 4명/km²","　냉대 기후가 넓어 농사지을 땅이 국토 면적에 비해 적다."],"numbered":false,"title":"133쪽 인구 밀도가 매우 높은 나라와 매우 낮은 나라(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_basic#3','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',1,'mc','auto','133쪽에서 인구 밀도가 높은 나라로 든 나라끼리 묶인 것은 어느 것인가요?',ARRAY['SO6-2-u3-X10']::text[],true,'{"seq":3,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"mc","stem":"133쪽에서 인구 밀도가 높은 나라로 든 나라끼리 묶인 것은 어느 것인가요?","options":[{"t":"방글라데시, 르완다, 인도","correct":true},{"t":"몽골, 오스트레일리아, 캐나다","mis":"SO6-2-u3-X10"},{"t":"캐나다, 아이슬란드, 리비아","mis":"SO6-2-u3-X10"},{"t":"몽골, 인도, 캐나다","mis":"SO6-2-u3-X10"}],"explanation":["133쪽 본문을 읽어요.","높은 나라와 낮은 나라를 나눴어요.","방글라데시·르완다·인도예요."],"asset":{"type":"passage","lines":["인구 밀도 — 일정한 면적(1 km²) 안에 사는 인구수","　인구가 모여 있는 정도를 나타낸다.","높은 나라 — 방글라데시, 르완다, 인도 등","낮은 나라 — 몽골, 오스트레일리아, 캐나다 등"],"numbered":false,"title":"132~133쪽 세계 여러 나라의 인구 밀도"},"variant_rule":{"alt":[{"stem":"133쪽에서 인구 밀도가 낮은 나라로 든 나라끼리 묶인 것은 어느 것인가요?","options":[{"t":"몽골, 오스트레일리아, 캐나다","correct":true},{"t":"방글라데시, 르완다, 인도","mis":"SO6-2-u3-X10"},{"t":"방글라데시, 몽골, 인도","mis":"SO6-2-u3-X10"},{"t":"르완다, 캐나다, 인도","mis":"SO6-2-u3-X10"}],"explanation":["133쪽 본문을 읽어요.","낮은 나라 셋을 찾아요.","몽골·오스트레일리아·캐나다예요."],"asset":{"type":"passage","lines":["인구 밀도 — 일정한 면적(1 km²) 안에 사는 인구수","　인구가 모여 있는 정도를 나타낸다.","높은 나라 — 방글라데시, 르완다, 인도 등","낮은 나라 — 몽골, 오스트레일리아, 캐나다 등"],"numbered":false,"title":"132~133쪽 세계 여러 나라의 인구 밀도"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_basic#4','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',1,'mc','auto','133쪽 스스로 활동의 네 나라 가운데 인구 밀도가 가장 높은 나라는 어디인가요?',ARRAY['SO6-2-u3-X09']::text[],true,'{"seq":4,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"mc","stem":"133쪽 스스로 활동의 네 나라 가운데 인구 밀도가 가장 높은 나라는 어디인가요?","options":[{"t":"우리나라","correct":true},{"t":"아이슬란드","mis":"SO6-2-u3-X09"},{"t":"과테말라","mis":"SO6-2-u3-X09"},{"t":"헝가리","mis":"SO6-2-u3-X09"}],"explanation":["네 수를 견줘요.","우리나라는 약 515명/km²예요.","가장 높은 나라는 우리나라예요."],"asset":{"type":"passage","lines":["우리나라 — 약 515명/km²(남한 통계)","아이슬란드 — 약 4명/km²","과테말라 — 약 169명/km²","헝가리 — 약 107명/km²"],"title":"133쪽 우리나라와 면적이 비슷한 나라의 인구 밀도"},"variant_rule":{"alt":[{"stem":"133쪽 스스로 활동의 네 나라 가운데 인구 밀도가 가장 낮은 나라는 어디인가요?","options":[{"t":"아이슬란드","correct":true},{"t":"우리나라","mis":"SO6-2-u3-X09"},{"t":"과테말라","mis":"SO6-2-u3-X09"},{"t":"헝가리","mis":"SO6-2-u3-X09"}],"explanation":["가장 작은 수를 찾아요.","아이슬란드는 약 4명/km²예요.","가장 낮은 나라는 아이슬란드예요."],"asset":{"type":"passage","lines":["우리나라 — 약 515명/km²(남한 통계)","아이슬란드 — 약 4명/km²","과테말라 — 약 169명/km²","헝가리 — 약 107명/km²"],"title":"133쪽 우리나라와 면적이 비슷한 나라의 인구 밀도"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_basic#5','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',2,'mc','auto','133쪽에서 방글라데시의 인구 밀도가 매우 높은 까닭으로 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X10']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"mc","stem":"133쪽에서 방글라데시의 인구 밀도가 매우 높은 까닭으로 든 것은 어느 것인가요?","options":[{"t":"국토 대부분이 평야이고 기후가 온화하며 벼농사가 발달했기 때문에","correct":true},{"t":"나라의 면적이 매우 넓기 때문에","mis":"SO6-2-u3-X06"},{"t":"냉대 기후가 넓게 나타나기 때문에","mis":"SO6-2-u3-X10"},{"t":"국토 대부분이 높은 산지이기 때문에","mis":"SO6-2-u3-X10"}],"explanation":["방글라데시 설명을 읽어요.","평야와 온화한 기후, 벼농사가 있어요.","면적에 비해 사람이 매우 많아요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km²","　국토 대부분이 평야 · 기후가 온화 · 벼농사 발달","캐나다 — 약 4명/km²","　냉대 기후가 넓어 농사지을 땅이 국토 면적에 비해 적다."],"numbered":false,"title":"133쪽 인구 밀도가 매우 높은 나라와 매우 낮은 나라(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_basic#6','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',2,'ox','auto','면적에 비해 인구수가 많으면 그 나라의 인구 밀도는 높게 나타나요.',ARRAY['SO6-2-u3-X09']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"ox","stem":"면적에 비해 인구수가 많으면 그 나라의 인구 밀도는 높게 나타나요.","answer":"O","reason_options":[{"t":"같은 넓이에 사는 사람이 많을수록 인구가 빽빽하게 모여 있기 때문에","correct":true},{"t":"인구 밀도는 면적만으로 정해지기 때문에","mis":"SO6-2-u3-X09"}],"mis":"SO6-2-u3-X09","explanation":["132쪽 본문이에요.","1 km² 안의 사람 수가 많아져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_basic#7','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',2,'blank','auto','「한 나라의 인구 밀도를 알려면 그 나라의 인구수와 (    )을/를 함께 알아야 합니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u3-X11','SO6-2-u3-X08','SO6-2-u3-X12']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"blank","stem":"「한 나라의 인구 밀도를 알려면 그 나라의 인구수와 (    )을/를 함께 알아야 합니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"면적","correct":true},{"t":"연령별 인구 비율","mis":"SO6-2-u3-X11"},{"t":"인구 성장률","mis":"SO6-2-u3-X08"},{"t":"평균 수명","mis":"SO6-2-u3-X12"}],"explanation":["인구 밀도는 1 km² 안의 인구수예요.","사람 수와 땅의 넓이가 필요해요.","빈칸은 면적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_basic#8','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',2,'ox','auto','우리나라는 면적이 비슷한 아이슬란드, 과테말라, 헝가리보다 인구 밀도가 높은 편이에요.',ARRAY['SO6-2-u3-X09']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"ox","stem":"우리나라는 면적이 비슷한 아이슬란드, 과테말라, 헝가리보다 인구 밀도가 높은 편이에요.","answer":"O","reason_options":[{"t":"우리나라는 약 515명/km²로 세 나라(약 4·169·107명/km²)보다 높기 때문에","correct":true},{"t":"면적이 비슷하면 인구 밀도도 언제나 같기 때문에","mis":"SO6-2-u3-X09"}],"mis":"SO6-2-u3-X09","explanation":["네 나라의 수를 견줘요.","515가 가장 커요.","그래서 O예요."],"asset":{"type":"passage","lines":["우리나라 — 약 515명/km²(남한 통계)","아이슬란드 — 약 4명/km²","과테말라 — 약 169명/km²","헝가리 — 약 107명/km²"],"title":"133쪽 우리나라와 면적이 비슷한 나라의 인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_basic#9','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',2,'mc','auto','134쪽 별별 직업 속으로에서 통계학 연구원이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X23','SO6-2-u3-X09','SO6-2-u3-X06']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"mc","stem":"134쪽 별별 직업 속으로에서 통계학 연구원이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"수집한 데이터를 숫자로 정리하고 분석해 규칙과 관계를 찾고 미래를 예측하는 정보를 만든다","correct":true},{"t":"나라별 인구수를 외워 순위를 정한다","mis":"SO6-2-u3-X23"},{"t":"인구가 많은 나라에 사람을 보낸다","mis":"SO6-2-u3-X09"},{"t":"나라의 면적을 직접 재어 넓힌다","mis":"SO6-2-u3-X06"}],"explanation":["직업 소개를 읽어요.","데이터에서 규칙과 관계를 찾아요.","그것으로 미래를 예측해요."],"asset":{"type":"passage","lines":["수집한 데이터를 숫자로 정리하고 분석하여 규칙과 관계를 찾는다.","이 규칙으로 문제 해결에 필요한 판단을 돕거나 미래를 예측한다.","과학적이고 논리적인 사고력과 수학에 대한 흥미가 필요하다.","데이터의 양이 빠르게 늘어나는 정보화 사회에서 역할이 커지고 있다."],"title":"134쪽 별별 직업 속으로 — 통계학 연구원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_basic#10','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_basic','lesson_basic','SO6-2-u3-C4',3,'mc','auto','131쪽의 인구 성장률이 지속되면 세계 여러 나라의 인구 밀도는 어떻게 변할까요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X02']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"mc","stem":"131쪽의 인구 성장률이 지속되면 세계 여러 나라의 인구 밀도는 어떻게 변할까요?","options":[{"t":"인구가 증가하는 나라는 인구 밀도가 점차 높아지고, 인구가 감소하는 나라는 점차 낮아질 것이다","correct":true},{"t":"인구 밀도는 면적으로만 정해지므로 변하지 않는다","mis":"SO6-2-u3-X09"},{"t":"인구가 증가하는 나라는 인구 밀도가 낮아진다","mis":"SO6-2-u3-X09"},{"t":"모든 나라의 인구 밀도가 똑같아진다","mis":"SO6-2-u3-X02"}],"explanation":["면적은 거의 그대로예요.","인구수가 늘면 밀도가 높아져요.","줄면 밀도가 낮아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_challenge#1','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',2,'mc','auto','132쪽 말풍선은 인구 밀도가 높은 나라를 예상할 때 무엇을 함께 살펴보라고 했나요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X11']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"mc","stem":"132쪽 말풍선은 인구 밀도가 높은 나라를 예상할 때 무엇을 함께 살펴보라고 했나요?","options":[{"t":"세계의 지형과 기후","correct":true},{"t":"나라의 면적만","mis":"SO6-2-u3-X09"},{"t":"나라의 인구수만","mis":"SO6-2-u3-X09"},{"t":"나라의 인구 구조","mis":"SO6-2-u3-X11"}],"explanation":["말풍선을 다시 읽어요.","1단원의 지형과 기후 지도를 보래요.","지형과 기후가 인구 밀도에 영향을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_challenge#2','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',2,'sa','auto','인구 밀도를 나타내는 단위를 쓰세요. (예: 약 515○/○○²)','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"sa","stem":"인구 밀도를 나타내는 단위를 쓰세요. (예: 약 515○/○○²)","answer":["명/km²","명/km2","명/㎢"],"explanation":["1 km² 안에 사는 사람 수예요.","사람은 「명」, 넓이는 km²예요.","단위는 명/km²예요."],"mis":"SO6-2-u3-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_challenge#3','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',3,'mc','auto','활동 자료 4를 백지도에 겹쳐 보고 알 수 있는 사실로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X10','SO6-2-u3-X06','SO6-2-u3-X02']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"mc","stem":"활동 자료 4를 백지도에 겹쳐 보고 알 수 있는 사실로 알맞은 것은 어느 것인가요?","options":[{"t":"아시아와 유럽에 인구 밀도가 높은 나라가 많고, 고위도에 있는 나라들은 낮은 편이다","correct":true},{"t":"고위도에 있는 나라들의 인구 밀도가 가장 높다","mis":"SO6-2-u3-X10"},{"t":"면적이 넓은 나라일수록 인구 밀도가 높다","mis":"SO6-2-u3-X06"},{"t":"모든 대륙의 인구 밀도가 같다","mis":"SO6-2-u3-X02"}],"explanation":["빽빽한 나라가 모인 곳을 봐요.","아시아와 유럽에 많아요.","추운 고위도 나라는 낮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_challenge#4','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',3,'error','auto','132~133쪽을 공부한 뒤 친구들이 인구 밀도를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X09']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"error","stem":"132~133쪽을 공부한 뒤 친구들이 인구 밀도를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「캐나다는 땅이 넓으니까 인구 밀도도 높을 거야.」","correct":true,"mis_target":"SO6-2-u3-X06"},{"t":"수빈 — 「방글라데시는 면적에 비해 인구수가 많아 인구 밀도가 높아.」","mis":"SO6-2-u3-X09"},{"t":"정우 — 「인구가 감소하는 나라는 인구 밀도가 점점 낮아질 거야.」","mis":"SO6-2-u3-X09"}],"explanation":["캐나다의 인구 밀도는 약 4명/km²예요.","땅이 넓어도 사람이 적으면 낮아요.","태오가 잘못 말했어요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km²","　국토 대부분이 평야 · 기후가 온화 · 벼농사 발달","캐나다 — 약 4명/km²","　냉대 기후가 넓어 농사지을 땅이 국토 면적에 비해 적다."],"numbered":false,"title":"133쪽 인구 밀도가 매우 높은 나라와 매우 낮은 나라(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_challenge#5','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',3,'mc','auto','아이슬란드는 우리나라와 면적이 비슷한데 인구 밀도가 매우 낮아요. 활동지 예시 답안에서 든 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X10','SO6-2-u3-X03']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"mc","stem":"아이슬란드는 우리나라와 면적이 비슷한데 인구 밀도가 매우 낮아요. 활동지 예시 답안에서 든 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한대 기후가 넓게 나타나 농사를 지을 수 있는 지역이 매우 적고 생활하기 불편하기 때문에","correct":true},{"t":"면적이 우리나라보다 훨씬 좁기 때문에","mis":"SO6-2-u3-X06"},{"t":"벼농사가 크게 발달했기 때문에","mis":"SO6-2-u3-X10"},{"t":"일자리를 찾아 사람이 많이 모이기 때문에","mis":"SO6-2-u3-X03"}],"explanation":["아이슬란드의 기후를 떠올려요.","겨울이 길고 몹시 추워요.","사람이 살기 어려워 밀도가 낮아요."],"asset":{"type":"passage","lines":["우리나라 — 약 515명/km²(남한 통계)","아이슬란드 — 약 4명/km²","과테말라 — 약 169명/km²","헝가리 — 약 107명/km²"],"title":"133쪽 우리나라와 면적이 비슷한 나라의 인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_challenge#6','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',3,'mc','auto','같은 넓이의 땅에 방글라데시처럼 사람이 산다면 약 1,317명이 살 때, 캐나다처럼 산다면 약 몇 명이 살까요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X23']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"mc","stem":"같은 넓이의 땅에 방글라데시처럼 사람이 산다면 약 1,317명이 살 때, 캐나다처럼 산다면 약 몇 명이 살까요?","options":[{"t":"약 4명","correct":true},{"t":"약 1,317명","mis":"SO6-2-u3-X09"},{"t":"약 515명","mis":"SO6-2-u3-X23"},{"t":"약 107명","mis":"SO6-2-u3-X23"}],"explanation":["133쪽 두 나라의 수를 읽어요.","캐나다는 약 4명/km²예요.","같은 넓이에 약 4명이 살아요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km²","　국토 대부분이 평야 · 기후가 온화 · 벼농사 발달","캐나다 — 약 4명/km²","　냉대 기후가 넓어 농사지을 땅이 국토 면적에 비해 적다."],"numbered":false,"title":"133쪽 인구 밀도가 매우 높은 나라와 매우 낮은 나라(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_challenge#7','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',3,'mc','auto','방글라데시와 캐나다의 인구 밀도 차이를 만든 요인으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X24','SO6-2-u3-X11']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"mc","stem":"방글라데시와 캐나다의 인구 밀도 차이를 만든 요인으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"평야와 온화한 기후, 냉대 기후처럼 서로 다른 자연환경","correct":true},{"t":"두 나라 면적의 크기만","mis":"SO6-2-u3-X06"},{"t":"두 나라 국민의 성격","mis":"SO6-2-u3-X24"},{"t":"두 나라 노년층의 비율","mis":"SO6-2-u3-X11"}],"explanation":["두 나라 설명을 견줘요.","방글라데시는 평야·온화한 기후예요.","캐나다는 냉대 기후가 넓어요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km²","　국토 대부분이 평야 · 기후가 온화 · 벼농사 발달","캐나다 — 약 4명/km²","　냉대 기후가 넓어 농사지을 땅이 국토 면적에 비해 적다."],"numbered":false,"title":"133쪽 인구 밀도가 매우 높은 나라와 매우 낮은 나라(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_challenge#8','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',4,'essay','teacher','133쪽 스스로 활동의 네 나라 인구 밀도를 견주어 알게 된 점을 쓰고, 우리나라의 인구 밀도가 높은 까닭을 인구수와 면적으로 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u3-C4","difficulty":4,"kind":"essay","stem":"133쪽 스스로 활동의 네 나라 인구 밀도를 견주어 알게 된 점을 쓰고, 우리나라의 인구 밀도가 높은 까닭을 인구수와 면적으로 설명하세요.","answer_guide":{"answer":"예: 우리나라는 약 515명/km²로 아이슬란드(약 4명/km²), 과테말라(약 169명/km²), 헝가리(약 107명/km²)보다 인구 밀도가 매우 높은 편이다. 면적은 비슷하지만 우리나라는 그 면적에 비해 인구수가 많아서 인구 밀도가 높다.","scoring_points":["네 나라의 수를 견주었는가","우리나라가 높은 편임을 썼는가","인구수와 면적으로 까닭을 썼는가"]},"explanation":["네 수를 큰 차례로 봐요.","우리나라가 가장 높아요.","면적에 비해 인구가 많아서예요."],"asset":{"type":"passage","lines":["우리나라 — 약 515명/km²(남한 통계)","아이슬란드 — 약 4명/km²","과테말라 — 약 169명/km²","헝가리 — 약 107명/km²"],"title":"133쪽 우리나라와 면적이 비슷한 나라의 인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_challenge#9','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',4,'mc','auto','인구 밀도가 매우 높은 방글라데시를 두고 바르게 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X24','SO6-2-u3-X06']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C4","difficulty":4,"kind":"mc","stem":"인구 밀도가 매우 높은 방글라데시를 두고 바르게 말한 친구는 누구인가요?","options":[{"t":"은재 — 「평야와 온화한 기후, 벼농사 덕분에 많은 사람이 모여 사는 나라야.」","correct":true},{"t":"민혁 — 「사람이 너무 많으니 살기 나쁜 나라일 거야.」","mis":"SO6-2-u3-X24"},{"t":"소율 — 「인구 밀도가 높으니 면적이 매우 넓은 나라겠지.」","mis":"SO6-2-u3-X06"},{"t":"지안 — 「인구 밀도가 낮은 나라보다 못한 나라야.」","mis":"SO6-2-u3-X24"}],"explanation":["인구 밀도는 모여 사는 정도일 뿐이에요.","까닭은 자연환경에서 찾아요.","편견 없이 말한 친구는 은재예요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km²","　국토 대부분이 평야 · 기후가 온화 · 벼농사 발달","캐나다 — 약 4명/km²","　냉대 기후가 넓어 농사지을 땅이 국토 면적에 비해 적다."],"numbered":false,"title":"133쪽 인구 밀도가 매우 높은 나라와 매우 낮은 나라(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L03_challenge#10','soc',6,2,'u3','L03','tb_g6_2_soc_u3_L03_challenge','lesson_challenge','SO6-2-u3-C4',4,'essay','teacher','통계학 연구원이 되어 131쪽 인구 성장률 지도로 앞으로의 인구 밀도를 예측해 보세요. 인구 성장률이 높은 아프리카 나라들과 인구가 감소하는 유럽 나라들의 인구 밀도가 어떻게 변할지 쓰고, 그렇게 예측한 근거를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C4","difficulty":4,"kind":"essay","stem":"통계학 연구원이 되어 131쪽 인구 성장률 지도로 앞으로의 인구 밀도를 예측해 보세요. 인구 성장률이 높은 아프리카 나라들과 인구가 감소하는 유럽 나라들의 인구 밀도가 어떻게 변할지 쓰고, 그렇게 예측한 근거를 쓰세요.","answer_guide":{"answer":"예: 인구 성장률이 높은 아프리카 나라들은 인구수가 늘어나 인구 밀도가 점차 높아질 것이다. 인구가 감소하는 유럽 나라들은 인구 밀도가 점차 낮아질 것이다. 나라의 면적은 거의 그대로인데 인구수가 달라지면 1 km² 안에 사는 사람 수가 달라지기 때문이다.","scoring_points":["아프리카 나라들의 변화를 예측했는가","유럽 나라들의 변화를 예측했는가","면적과 인구수로 근거를 썼는가"]},"explanation":["성장률은 인구수의 변화예요.","면적은 거의 그대로예요.","인구수가 바뀌면 밀도가 바뀌어요."],"asset":{"type":"passage","lines":["인구 성장률 — 일정한 지역 안에 사는 인구가 증가하는 비율","3 % 이상인 나라가 가장 많은 대륙 — 아프리카","인구가 감소하는 나라가 가장 많은 대륙 — 유럽","인구가 감소하는 나라의 예 — 이탈리아, 그리스, 러시아, 일본, 쿠바 등"],"numbered":false,"title":"131쪽 나라별 인구 성장률 지도(국제 연합, 2018~2023)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_basic#1','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',1,'sa','auto','「인구 구조」는 연령, 성 등을 기준으로 한 인구의 무엇을 말하나요? (□□□)','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"sa","stem":"「인구 구조」는 연령, 성 등을 기준으로 한 인구의 무엇을 말하나요? (□□□)","answer":["짜임새"],"explanation":["135쪽 낱말 풀이예요.","연령과 성으로 인구를 나누어 봐요.","인구의 짜임새예요."],"mis":"SO6-2-u3-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_basic#2','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',1,'mc','auto','135쪽 그래프에서 1960년에 비해 2020년에 비율이 줄어든 연령층은 어느 것인가요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X11']::text[],true,'{"seq":2,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"mc","stem":"135쪽 그래프에서 1960년에 비해 2020년에 비율이 줄어든 연령층은 어느 것인가요?","options":[{"t":"유소년층","correct":true},{"t":"노년층","mis":"SO6-2-u3-X12"},{"t":"세 연령층 모두","mis":"SO6-2-u3-X11"},{"t":"어느 연령층도 아니다","mis":"SO6-2-u3-X11"}],"explanation":["1960년과 2020년을 견줘요.","유소년층은 37.4 %에서 25.8 %가 되었어요.","줄어든 연령층은 유소년층이에요."],"asset":{"type":"passage","lines":["차례 — 유소년층(0~14세) · 청장년층(15~64세) · 노년층(65세 이상)","1960년 — 37.4 % · 57.6 % · 5.0 %","1980년 — 35.5 % · 58.7 % · 5.8 %","2000년 — 30.4 % · 62.8 % · 6.8 %","2020년 — 25.8 % · 64.9 % · 9.3 %"],"numbered":false,"title":"135쪽 연령별 세계 인구 구조의 변화(국제 연합, 2024)"},"variant_rule":{"alt":[{"stem":"135쪽 그래프에서 1960년에 비해 2020년에 비율이 늘어난 연령층은 어느 것인가요?","options":[{"t":"노년층","correct":true},{"t":"유소년층","mis":"SO6-2-u3-X12"},{"t":"어느 연령층도 아니다","mis":"SO6-2-u3-X11"},{"t":"세 연령층이 똑같이 늘었다","mis":"SO6-2-u3-X11"}],"explanation":["노년층의 두 수를 견줘요.","5.0 %에서 9.3 %가 되었어요.","늘어난 연령층은 노년층이에요."],"asset":{"type":"passage","lines":["차례 — 유소년층(0~14세) · 청장년층(15~64세) · 노년층(65세 이상)","1960년 — 37.4 % · 57.6 % · 5.0 %","1980년 — 35.5 % · 58.7 % · 5.8 %","2000년 — 30.4 % · 62.8 % · 6.8 %","2020년 — 25.8 % · 64.9 % · 9.3 %"],"numbered":false,"title":"135쪽 연령별 세계 인구 구조의 변화(국제 연합, 2024)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_basic#3','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',1,'ox','auto','꼭 기억해요 — 나라나 특정 지역의 인구 구조를 살펴보면 미래의 인구 변화를 예상할 수 있습니다.',ARRAY['SO6-2-u3-X12']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"ox","stem":"꼭 기억해요 — 나라나 특정 지역의 인구 구조를 살펴보면 미래의 인구 변화를 예상할 수 있습니다.","answer":"O","reason_options":[{"t":"어느 연령층이 늘고 줄어드는지 보면 앞으로의 인구를 짐작할 수 있기 때문에","correct":true},{"t":"인구 구조는 지금의 모습일 뿐 미래와는 아무 관계가 없기 때문에","mis":"SO6-2-u3-X12"}],"mis":"SO6-2-u3-X12","explanation":["135쪽 본문이에요.","유소년층이 줄면 앞으로 일할 사람도 줄어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_basic#4','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',1,'match','auto','연령층과 나이를 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"match","stem":"연령층과 나이를 알맞게 이으세요.","pairs":[{"l":"유소년층","r":"0~14세"},{"l":"청장년층","r":"15~64세"},{"l":"노년층","r":"65세 이상"}],"mis":"SO6-2-u3-X11","explanation":["135쪽 그래프의 범례를 봐요.","아래부터 유소년층·청장년층·노년층이에요.","나이로 셋을 나눠요."],"asset":{"type":"passage","lines":["차례 — 유소년층(0~14세) · 청장년층(15~64세) · 노년층(65세 이상)","1960년 — 37.4 % · 57.6 % · 5.0 %","1980년 — 35.5 % · 58.7 % · 5.8 %","2000년 — 30.4 % · 62.8 % · 6.8 %","2020년 — 25.8 % · 64.9 % · 9.3 %"],"numbered":false,"title":"135쪽 연령별 세계 인구 구조의 변화(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_basic#5','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',2,'mc','auto','인구 피라미드의 가로축 왼쪽은 무엇을 나타내나요?',ARRAY['SO6-2-u3-X11','SO6-2-u3-X09']::text[],true,'{"seq":5,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"mc","stem":"인구 피라미드의 가로축 왼쪽은 무엇을 나타내나요?","options":[{"t":"남자 인구 비율","correct":true},{"t":"여자 인구 비율","mis":"SO6-2-u3-X11"},{"t":"나이(연령)","mis":"SO6-2-u3-X11"},{"t":"나라의 면적","mis":"SO6-2-u3-X09"}],"explanation":["136쪽 설명을 읽어요.","가로축 왼쪽은 남자, 오른쪽은 여자예요.","답은 남자 인구 비율이에요."],"asset":{"type":"passage","lines":["인구 피라미드 — 가로축 왼쪽은 남자, 오른쪽은 여자 인구 비율, 세로축은 나이","나이지리아 — 유소년층 비율 높다 · 노년층 비율 낮다","　출생률 높다 · 사망률 높다 · 평균 수명 짧다","일본 — 유소년층 비율 낮다 · 노년층 비율 높다","　출생률 낮다 · 사망률 낮다 · 평균 수명 길다"],"numbered":false,"title":"136쪽 할 수 있어요 — 두 나라의 인구 구조 비교(국제 연합, 2024)"},"variant_rule":{"alt":[{"stem":"인구 피라미드의 세로축은 무엇을 나타내나요?","options":[{"t":"나이(연령)","correct":true},{"t":"남자 인구 비율","mis":"SO6-2-u3-X11"},{"t":"여자 인구 비율","mis":"SO6-2-u3-X11"},{"t":"인구 밀도","mis":"SO6-2-u3-X09"}],"explanation":["136쪽 설명을 읽어요.","아래로 갈수록 어리고 위로 갈수록 나이가 많아요.","세로축은 나이예요."],"asset":{"type":"passage","lines":["인구 피라미드 — 가로축 왼쪽은 남자, 오른쪽은 여자 인구 비율, 세로축은 나이","나이지리아 — 유소년층 비율 높다 · 노년층 비율 낮다","　출생률 높다 · 사망률 높다 · 평균 수명 짧다","일본 — 유소년층 비율 낮다 · 노년층 비율 높다","　출생률 낮다 · 사망률 낮다 · 평균 수명 길다"],"numbered":false,"title":"136쪽 할 수 있어요 — 두 나라의 인구 구조 비교(국제 연합, 2024)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_basic#6','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',2,'match','auto','136쪽 표를 보고 나라별 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"match","stem":"136쪽 표를 보고 나라별 특징을 알맞게 이으세요.","pairs":[{"l":"나이지리아의 출생률","r":"높다"},{"l":"일본의 출생률","r":"낮다"},{"l":"나이지리아의 평균 수명","r":"짧다"},{"l":"일본의 평균 수명","r":"길다"}],"mis":"SO6-2-u3-X12","explanation":["표의 칸을 하나씩 읽어요.","나이지리아는 출생률이 높고 평균 수명이 짧아요.","일본은 그 반대예요."],"asset":{"type":"passage","lines":["인구 피라미드 — 가로축 왼쪽은 남자, 오른쪽은 여자 인구 비율, 세로축은 나이","나이지리아 — 유소년층 비율 높다 · 노년층 비율 낮다","　출생률 높다 · 사망률 높다 · 평균 수명 짧다","일본 — 유소년층 비율 낮다 · 노년층 비율 높다","　출생률 낮다 · 사망률 낮다 · 평균 수명 길다"],"numbered":false,"title":"136쪽 할 수 있어요 — 두 나라의 인구 구조 비교(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_basic#7','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C6',2,'mc','auto','노년층 비율이 높은 일본에 더 많이 필요할 시설로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X13']::text[],true,'{"seq":7,"concept":"SO6-2-u3-C6","difficulty":2,"kind":"mc","stem":"노년층 비율이 높은 일본에 더 많이 필요할 시설로 알맞은 것은 어느 것인가요?","options":[{"t":"요양원, 노인 복지 센터","correct":true},{"t":"유치원, 초등학교","mis":"SO6-2-u3-X13"},{"t":"놀이터, 키즈 카페","mis":"SO6-2-u3-X13"},{"t":"어떤 시설도 필요 없다","mis":"SO6-2-u3-X13"}],"explanation":["노년층이 많아요.","노인을 위한 시설이 필요해요.","요양원과 노인 복지 센터예요."],"asset":{"type":"passage","lines":["인구 피라미드 — 가로축 왼쪽은 남자, 오른쪽은 여자 인구 비율, 세로축은 나이","나이지리아 — 유소년층 비율 높다 · 노년층 비율 낮다","　출생률 높다 · 사망률 높다 · 평균 수명 짧다","일본 — 유소년층 비율 낮다 · 노년층 비율 높다","　출생률 낮다 · 사망률 낮다 · 평균 수명 길다"],"numbered":false,"title":"136쪽 할 수 있어요 — 두 나라의 인구 구조 비교(국제 연합, 2024)"},"variant_rule":{"alt":[{"stem":"유소년층 비율이 높은 나이지리아에 더 많이 필요할 시설로 알맞은 것은 어느 것인가요?","options":[{"t":"유치원, 학교","correct":true},{"t":"요양원, 노인 복지 센터","mis":"SO6-2-u3-X13"},{"t":"경로당, 노인 교실","mis":"SO6-2-u3-X13"},{"t":"어떤 시설도 필요 없다","mis":"SO6-2-u3-X13"}],"explanation":["유소년층이 많아요.","어린이를 위한 시설이 필요해요.","유치원과 학교예요."],"asset":{"type":"passage","lines":["인구 피라미드 — 가로축 왼쪽은 남자, 오른쪽은 여자 인구 비율, 세로축은 나이","나이지리아 — 유소년층 비율 높다 · 노년층 비율 낮다","　출생률 높다 · 사망률 높다 · 평균 수명 짧다","일본 — 유소년층 비율 낮다 · 노년층 비율 높다","　출생률 낮다 · 사망률 낮다 · 평균 수명 길다"],"numbered":false,"title":"136쪽 할 수 있어요 — 두 나라의 인구 구조 비교(국제 연합, 2024)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_basic#8','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C6',2,'mc','auto','137쪽 기사와 자료를 보고 인도네시아의 인구 구조를 고른 것은 어느 것인가요?',ARRAY['SO6-2-u3-X11','SO6-2-u3-X13']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C6","difficulty":2,"kind":"mc","stem":"137쪽 기사와 자료를 보고 인도네시아의 인구 구조를 고른 것은 어느 것인가요?","options":[{"t":"⑵ — 1980~1990년대생이 많아 청장년층(15~64세) 비율이 높다","correct":true},{"t":"⑴ — 노년층(65세 이상) 비율이 36.4 %로 높다","mis":"SO6-2-u3-X11"},{"t":"⑴과 ⑵ 모두 인도네시아이다","mis":"SO6-2-u3-X11"},{"t":"기사로는 알 수 없다","mis":"SO6-2-u3-X13"}],"explanation":["전체 인구의 54.4 %가 1980~1990년대생이에요.","그들은 지금 청장년층이에요.","청장년층이 68.0 %인 ⑵예요."],"asset":{"type":"passage","lines":["⑴ 0~14세 13.1 % · 15~64세 50.5 % · 65세 이상 36.4 %","⑵ 0~14세 25.0 % · 15~64세 68.0 % · 65세 이상 7.0 %"],"title":"137쪽 인도네시아의 인구 구조는 어느 것일까?(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_basic#9','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',2,'blank','auto','꼭 기억해요 — 「인구 구조는 (    ), 사망률 등에 따라 다르게 나타납니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X06','SO6-2-u3-X08']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"blank","stem":"꼭 기억해요 — 「인구 구조는 (    ), 사망률 등에 따라 다르게 나타납니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"출생률","correct":true},{"t":"인구 밀도","mis":"SO6-2-u3-X09"},{"t":"면적","mis":"SO6-2-u3-X06"},{"t":"인구 성장률","mis":"SO6-2-u3-X08"}],"explanation":["137쪽 본문이에요.","태어나는 아기의 비율이에요.","빈칸은 출생률이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_basic#10','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_basic','lesson_basic','SO6-2-u3-C5',3,'mc','auto','135쪽 그래프에서 유소년층의 비율이 계속 줄어들고 있다는 것은 무엇을 뜻하나요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X05']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C5","difficulty":3,"kind":"mc","stem":"135쪽 그래프에서 유소년층의 비율이 계속 줄어들고 있다는 것은 무엇을 뜻하나요?","options":[{"t":"출생률이 계속 낮아져 왔다는 뜻이다","correct":true},{"t":"사망률이 계속 높아져 왔다는 뜻이다","mis":"SO6-2-u3-X12"},{"t":"평균 수명이 계속 짧아져 왔다는 뜻이다","mis":"SO6-2-u3-X12"},{"t":"세계 인구가 계속 줄어 왔다는 뜻이다","mis":"SO6-2-u3-X05"}],"explanation":["유소년층은 0~14세예요.","아기가 적게 태어나면 줄어요.","출생률이 낮아진 거예요."],"asset":{"type":"passage","lines":["차례 — 유소년층(0~14세) · 청장년층(15~64세) · 노년층(65세 이상)","1960년 — 37.4 % · 57.6 % · 5.0 %","1980년 — 35.5 % · 58.7 % · 5.8 %","2000년 — 30.4 % · 62.8 % · 6.8 %","2020년 — 25.8 % · 64.9 % · 9.3 %"],"numbered":false,"title":"135쪽 연령별 세계 인구 구조의 변화(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_challenge#1','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C5',2,'mc','auto','135쪽 그래프의 변화가 이어진다면 2040년의 연령별 세계 인구 구조는 어떻게 될까요?',ARRAY['SO6-2-u3-X12']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"mc","stem":"135쪽 그래프의 변화가 이어진다면 2040년의 연령별 세계 인구 구조는 어떻게 될까요?","options":[{"t":"2020년보다 유소년층 비율은 더 줄고 노년층 비율은 더 늘어날 것이다","correct":true},{"t":"유소년층 비율이 1960년처럼 다시 크게 늘 것이다","mis":"SO6-2-u3-X12"},{"t":"노년층 비율이 줄어들 것이다","mis":"SO6-2-u3-X12"},{"t":"2020년과 똑같을 것이다","mis":"SO6-2-u3-X12"}],"explanation":["1960년부터 변화 방향을 봐요.","유소년층은 계속 줄고 노년층은 계속 늘었어요.","그 흐름이 이어질 거예요."],"asset":{"type":"passage","lines":["차례 — 유소년층(0~14세) · 청장년층(15~64세) · 노년층(65세 이상)","1960년 — 37.4 % · 57.6 % · 5.0 %","1980년 — 35.5 % · 58.7 % · 5.8 %","2000년 — 30.4 % · 62.8 % · 6.8 %","2020년 — 25.8 % · 64.9 % · 9.3 %"],"numbered":false,"title":"135쪽 연령별 세계 인구 구조의 변화(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_challenge#2','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C5',2,'sa','auto','「국가나 특정 지역의 연령별, 성별 인구를 나타낸 그래프」를 무엇이라고 하나요?','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"sa","stem":"「국가나 특정 지역의 연령별, 성별 인구를 나타낸 그래프」를 무엇이라고 하나요?","answer":["인구 피라미드","인구피라미드"],"explanation":["136쪽 낱말 풀이예요.","연령별·성별 인구를 한눈에 보여 줘요.","인구 피라미드예요."],"mis":"SO6-2-u3-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_challenge#3','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C6',3,'mc','auto','세계 여러 나라의 기업들이 인도네시아에 주목하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X13','SO6-2-u3-X12']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C6","difficulty":3,"kind":"mc","stem":"세계 여러 나라의 기업들이 인도네시아에 주목하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"유행에 민감하고 소비 성향이 높은 젊은 인구의 비율이 높아 시장이 더 커질 것이기 때문에","correct":true},{"t":"노년층 비율이 높아 요양원이 많이 필요하기 때문에","mis":"SO6-2-u3-X13"},{"t":"인구가 빠르게 줄어 물건을 살 사람이 적기 때문에","mis":"SO6-2-u3-X12"},{"t":"인구 구조는 기업과 관계없기 때문에","mis":"SO6-2-u3-X13"}],"explanation":["기사의 「젊은 시장」을 떠올려요.","젊은 소비자가 화장품·스마트폰을 많이 사요.","시장이 커질 것으로 예상해요."],"asset":{"type":"passage","lines":["높은 경제성장을 이어 오고 있는 인도네시아는","전체 인구의 54.4 %가 1980~1990년대생이다.","이들은 유행에 민감하고 소비 성향이 높아 시장 규모가 더 커질 것이다.","여러 나라 기업들이 화장품, 스마트폰 등에 투자를 늘리고 있다."],"title":"137쪽 세계가 주목하는 「젊은 시장」 인도네시아(2024년 기사를 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_challenge#4','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C6',3,'mc','auto','인도네시아의 인구 구조를 인구 피라미드로 나타낸다면 나이지리아와 일본 가운데 어느 나라와 더 비슷할까요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X11']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C6","difficulty":3,"kind":"mc","stem":"인도네시아의 인구 구조를 인구 피라미드로 나타낸다면 나이지리아와 일본 가운데 어느 나라와 더 비슷할까요?","options":[{"t":"나이지리아 — 젊은 연령층이 두껍기 때문에","correct":true},{"t":"일본 — 노년층이 두껍기 때문에","mis":"SO6-2-u3-X12"},{"t":"두 나라 모두와 똑같다","mis":"SO6-2-u3-X11"},{"t":"피라미드로 나타낼 수 없다","mis":"SO6-2-u3-X11"}],"explanation":["인도네시아는 노년층이 7.0 %로 적어요.","젊은 연령층이 두꺼워요.","나이지리아와 더 비슷해요."],"asset":{"type":"passage","lines":["⑴ 0~14세 13.1 % · 15~64세 50.5 % · 65세 이상 36.4 %","⑵ 0~14세 25.0 % · 15~64세 68.0 % · 65세 이상 7.0 %"],"title":"137쪽 인도네시아의 인구 구조는 어느 것일까?(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_challenge#5','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C6',3,'mc','auto','사우디아라비아와 아랍 에미리트에서 청장년층 인구가 두드러지게 많은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X25','SO6-2-u3-X12']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C6","difficulty":3,"kind":"mc","stem":"사우디아라비아와 아랍 에미리트에서 청장년층 인구가 두드러지게 많은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"경제성장을 위해 세계 여러 나라에서 외국인 근로자를 적극적으로 받아들였기 때문에","correct":true},{"t":"출생률이 매우 높아 아기가 많이 태어났기 때문에","mis":"SO6-2-u3-X25"},{"t":"평균 수명이 매우 짧기 때문에","mis":"SO6-2-u3-X12"},{"t":"노인들이 모두 다른 나라로 떠났기 때문에","mis":"SO6-2-u3-X25"}],"explanation":["138쪽 글을 읽어요.","인도·파키스탄·필리핀 등에서 근로자가 왔어요.","일하는 나이의 인구가 많아졌어요."],"asset":{"type":"passage","lines":["석유 자원이 풍부한 사우디아라비아, 아랍 에미리트, 쿠웨이트, 카타르 등은","경제성장 과정에서 인도, 파키스탄, 필리핀 등에서 근로자를 받아들였다.","그래서 전체 인구에서 외국인 근로자가 차지하는 비중이 높고","생산 활동에 참여할 수 있는 청장년층 인구가 많다."],"title":"138쪽 풍덩 사회 속으로 — 독특한 인구 구조를 가진 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_challenge#6','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C5',3,'match','auto','과정 중심 평가 활동지의 인구 특징과 나라를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u3-C5","difficulty":3,"kind":"match","stem":"과정 중심 평가 활동지의 인구 특징과 나라를 알맞게 이으세요.","pairs":[{"l":"⑴ 출생률·사망률이 낮고 노년층 비율이 높은 나라","r":"독일"},{"l":"⑵ 외국인 근로자를 대거 받아들여 청장년층이 많은 나라","r":"카타르"},{"l":"⑶ 출생률·사망률이 높고 유소년층 비율이 높은 나라","r":"니제르"}],"mis":"SO6-2-u3-X25","explanation":["특징을 하나씩 읽어요.","독일은 노년층, 니제르는 유소년층이 많아요.","카타르는 외국인 근로자로 청장년층이 많아요."],"asset":{"type":"passage","lines":["⑴ 출생률과 사망률이 낮고 평균 수명이 길며, 유소년층 비율이 낮고 노년층 비율이 높다.","⑵ 세계 각지에서 외국인 근로자를 대거 받아들여 청장년층 인구가 많다.","⑶ 출생률과 사망률이 높고 평균 수명이 짧으며, 유소년층 비율이 높고 노년층 비율이 낮다."],"title":"과정 중심 평가 — 니제르·독일·카타르 인구 피라미드의 특징"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_challenge#7','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C5',3,'mc','auto','어느 나라의 인구 피라미드에서 청장년층, 그중에서도 남자 쪽이 유난히 넓고 유소년층과 노년층은 좁아요. 이 피라미드에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X25','SO6-2-u3-X11']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C5","difficulty":3,"kind":"mc","stem":"어느 나라의 인구 피라미드에서 청장년층, 그중에서도 남자 쪽이 유난히 넓고 유소년층과 노년층은 좁아요. 이 피라미드에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"외국인 근로자를 많이 받아들인 나라의 인구 피라미드이다","correct":true},{"t":"출생률과 사망률이 모두 높은 나라의 인구 피라미드이다","mis":"SO6-2-u3-X25"},{"t":"노년층의 비율이 매우 높은 나라의 인구 피라미드이다","mis":"SO6-2-u3-X11"},{"t":"유소년층의 비율이 매우 높은 나라의 인구 피라미드이다","mis":"SO6-2-u3-X11"}],"explanation":["가운데가 유난히 넓어요.","일하러 온 사람들 때문이에요.","외국인 근로자를 받아들인 나라예요."],"asset":{"type":"passage","lines":["석유 자원이 풍부한 사우디아라비아, 아랍 에미리트, 쿠웨이트, 카타르 등은","경제성장 과정에서 인도, 파키스탄, 필리핀 등에서 근로자를 받아들였다.","그래서 전체 인구에서 외국인 근로자가 차지하는 비중이 높고","생산 활동에 참여할 수 있는 청장년층 인구가 많다."],"title":"138쪽 풍덩 사회 속으로 — 독특한 인구 구조를 가진 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_challenge#8','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C6',4,'essay','teacher','과정 중심 평가 — 니제르와 독일에 수출하고 싶은 물건을 하나씩 정하고, 그 까닭을 두 나라의 인구 구조와 이어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u3-C6","difficulty":4,"kind":"essay","stem":"과정 중심 평가 — 니제르와 독일에 수출하고 싶은 물건을 하나씩 정하고, 그 까닭을 두 나라의 인구 구조와 이어 쓰세요.","answer_guide":{"answer":"예: 니제르에는 학용품을 수출하고 싶다. 출생률이 높아 유소년층 인구가 계속 늘어날 것이기 때문이다. 독일에는 보행 보조기를 수출하고 싶다. 사망률이 낮고 평균 수명이 길어 노년층 인구가 계속 늘어날 것이기 때문이다.","scoring_points":["니제르에 알맞은 물건과 까닭을 썼는가","독일에 알맞은 물건과 까닭을 썼는가","연령층의 비율과 변화를 근거로 들었는가"]},"explanation":["니제르는 유소년층이 많아요.","독일은 노년층이 많아요.","많은 연령층에 필요한 물건을 골라요."],"asset":{"type":"passage","lines":["⑴ 출생률과 사망률이 낮고 평균 수명이 길며, 유소년층 비율이 낮고 노년층 비율이 높다.","⑵ 세계 각지에서 외국인 근로자를 대거 받아들여 청장년층 인구가 많다.","⑶ 출생률과 사망률이 높고 평균 수명이 짧으며, 유소년층 비율이 높고 노년층 비율이 낮다."],"title":"과정 중심 평가 — 니제르·독일·카타르 인구 피라미드의 특징"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_challenge#9','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C6',4,'mc','auto','경제적인 이유로 사우디아라비아와 아랍 에미리트에 외국인 근로자가 더 이상 필요하지 않게 된다면 두 나라의 인구 구조는 어떻게 변할까요?',ARRAY['SO6-2-u3-X25','SO6-2-u3-X12']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C6","difficulty":4,"kind":"mc","stem":"경제적인 이유로 사우디아라비아와 아랍 에미리트에 외국인 근로자가 더 이상 필요하지 않게 된다면 두 나라의 인구 구조는 어떻게 변할까요?","options":[{"t":"외국인 근로자들이 자기 나라로 돌아가면서 청장년층의 인구 비율이 줄어들 것이다","correct":true},{"t":"출생률이 높아져 유소년층이 갑자기 늘 것이다","mis":"SO6-2-u3-X25"},{"t":"노년층이 모두 사라질 것이다","mis":"SO6-2-u3-X12"},{"t":"인구 이동은 인구 구조를 바꾸지 않으므로 그대로일 것이다","mis":"SO6-2-u3-X25"}],"explanation":["청장년층이 많았던 까닭을 떠올려요.","외국인 근로자 때문이었어요.","그들이 떠나면 청장년층 비율이 줄어요."],"asset":{"type":"passage","lines":["석유 자원이 풍부한 사우디아라비아, 아랍 에미리트, 쿠웨이트, 카타르 등은","경제성장 과정에서 인도, 파키스탄, 필리핀 등에서 근로자를 받아들였다.","그래서 전체 인구에서 외국인 근로자가 차지하는 비중이 높고","생산 활동에 참여할 수 있는 청장년층 인구가 많다."],"title":"138쪽 풍덩 사회 속으로 — 독특한 인구 구조를 가진 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L04_challenge#10','soc',6,2,'u3','L04','tb_g6_2_soc_u3_L04_challenge','lesson_challenge','SO6-2-u3-C5',4,'essay','teacher','135쪽 그래프를 보고 2040년의 연령별 세계 인구 구조를 예상해 쓰고, 그렇게 예상한 까닭과 그에 따라 더 많이 필요해질 시설을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C5","difficulty":4,"kind":"essay","stem":"135쪽 그래프를 보고 2040년의 연령별 세계 인구 구조를 예상해 쓰고, 그렇게 예상한 까닭과 그에 따라 더 많이 필요해질 시설을 쓰세요.","answer_guide":{"answer":"예: 2040년에는 2020년보다 유소년층 비율은 줄고 노년층 비율은 늘어날 것이다. 1960년 이후 유소년층의 비율은 계속 줄고 노년층의 비율은 계속 늘어 왔기 때문이다. 그래서 요양원이나 노인 복지 센터 같은 노인을 위한 시설이 더 많이 필요해질 것이다.","scoring_points":["2040년의 인구 구조를 예상했는가","1960년 이후의 변화를 근거로 들었는가","필요해질 시설을 인구 구조와 이어 썼는가"]},"explanation":["그래프의 흐름을 먼저 읽어요.","흐름이 이어진다고 보고 예상해요.","늘어나는 연령층에 필요한 시설을 써요."],"asset":{"type":"passage","lines":["차례 — 유소년층(0~14세) · 청장년층(15~64세) · 노년층(65세 이상)","1960년 — 37.4 % · 57.6 % · 5.0 %","1980년 — 35.5 % · 58.7 % · 5.8 %","2000년 — 30.4 % · 62.8 % · 6.8 %","2020년 — 25.8 % · 64.9 % · 9.3 %"],"numbered":false,"title":"135쪽 연령별 세계 인구 구조의 변화(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_basic#1','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',1,'sa','auto','「과학 기술과 교통·통신의 발달로 지구가 하나의 마을처럼 가까워진 모습」을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"sa","stem":"「과학 기술과 교통·통신의 발달로 지구가 하나의 마을처럼 가까워진 모습」을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["지구촌"],"explanation":["141쪽 본문이에요.","지구가 한 마을처럼 가까워졌어요.","지구촌이에요."],"mis":"SO6-2-u3-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_basic#2','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',1,'mc','auto','140쪽 생각을 열어요 — 세계 여러 나라 사람들이 지구촌 전등 끄기 캠페인에 참여하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X14']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"mc","stem":"140쪽 생각을 열어요 — 세계 여러 나라 사람들이 지구촌 전등 끄기 캠페인에 참여하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"에너지를 절약하고 지구 환경을 보호하는 일을 함께 실천하려고","correct":true},{"t":"전기 요금을 더 많이 내려고","mis":"SO6-2-u3-X16"},{"t":"밤에 별을 보는 놀이를 하려고","mis":"SO6-2-u3-X14"},{"t":"우리나라만 하는 행사라서","mis":"SO6-2-u3-X16"}],"explanation":["140쪽 사진을 떠올려요.","한 시간 동안 함께 불을 꺼요.","에너지를 아끼고 지구 환경을 지키려는 거예요."],"asset":{"type":"passage","lines":["세계 여러 나라 사람들이 매년 3월 마지막 주 토요일에","한 시간 동안 불을 끄는 「지구촌 전등 끄기 캠페인」에 참여한다.","사진 — 우리나라와 말레이시아의 불 끄기 전과 불 끈 후 모습"],"title":"140쪽 생각을 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_basic#3','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',1,'ox','auto','꼭 기억해요 — 우리는 지구가 하나의 마을처럼 가까워진 지구촌 시대에 살고 있습니다.',ARRAY['SO6-2-u3-X14']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"ox","stem":"꼭 기억해요 — 우리는 지구가 하나의 마을처럼 가까워진 지구촌 시대에 살고 있습니다.","answer":"O","reason_options":[{"t":"과학 기술과 교통·통신의 발달로 세계 여러 나라가 서로 가까워졌기 때문에","correct":true},{"t":"세계 여러 나라는 서로 아무 영향도 주고받지 않기 때문에","mis":"SO6-2-u3-X14"}],"mis":"SO6-2-u3-X14","explanation":["141쪽 본문이에요.","다른 나라 소식을 바로 알 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_basic#4','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',1,'blank','auto','꼭 기억해요 — 「지구촌에는 자원과 에너지 고갈, 생태계 파괴, (    ), 난민 등의 문제가 나타나고 있습니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"blank","stem":"꼭 기억해요 — 「지구촌에는 자원과 에너지 고갈, 생태계 파괴, (    ), 난민 등의 문제가 나타나고 있습니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"기후변화","correct":true},{"t":"인구 밀도","mis":"SO6-2-u3-X15"},{"t":"인구 피라미드","mis":"SO6-2-u3-X15"},{"t":"인구 성장률","mis":"SO6-2-u3-X15"}],"explanation":["142쪽 네 문제를 떠올려요.","빙하가 녹는 사진이 있어요.","빈칸은 기후변화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_basic#5','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',2,'match','auto','142쪽 사진과 지구촌 문제를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"match","stem":"142쪽 사진과 지구촌 문제를 알맞게 이으세요.","pairs":[{"l":"① 깎여 나간 구리 광산","r":"자원과 에너지 고갈"},{"l":"② 벌채로 손상된 열대 우림","r":"생태계 파괴"},{"l":"③ 녹아 무너지는 빙하","r":"기후변화"},{"l":"④ 보트에서 구조를 요청하는 사람들","r":"난민"}],"mis":"SO6-2-u3-X15","explanation":["사진 속 장면을 하나씩 봐요.","광산은 자원, 숲은 생태계예요.","빙하는 기후변화, 보트는 난민이에요."],"asset":{"type":"passage","lines":["① 산지 일부가 깎여 나간 페루의 라스밤바스 구리 광산","② 벌채로 손상된 인도네시아 수마트라섬의 열대 우림","③ 녹아 무너지고 있는 아르헨티나 로스글라시아레스 국립공원의 빙하","④ 남지중해에서 보트를 타고 구조를 요청하며 손을 흔드는 사람들"],"numbered":false,"title":"142쪽 지구촌을 위협하는 문제 — 사진 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_basic#6','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',2,'mc','auto','141쪽 기사에서 열대 우림이 파괴된 가장 큰 원인으로 꼽은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"mc","stem":"141쪽 기사에서 열대 우림이 파괴된 가장 큰 원인으로 꼽은 것은 어느 것인가요?","options":[{"t":"농사, 에너지 사용, 목축, 각종 산업 등 인간의 활동","correct":true},{"t":"열대 우림에 사는 동물들의 활동","mis":"SO6-2-u3-X15"},{"t":"화산 폭발과 지진","mis":"SO6-2-u3-X15"},{"t":"열대 우림에 비가 너무 적게 와서","mis":"SO6-2-u3-X15"}],"explanation":["기사의 원인 부분을 읽어요.","농사·에너지·목축·산업이 나와요.","모두 인간의 활동이에요."],"asset":{"type":"passage","lines":["지구 표면의 약 13 %를 덮고 있던 열대 우림 중 3분의 2가 파괴됐다.","2002년 이후 사라진 열대 우림의 면적이 프랑스의 영토보다 넓다.","원인 — 농사, 에너지 사용, 목축, 각종 산업 등 인간의 활동","열대 우림에는 지구 생명체의 절반 이상이 살고 있다.","열대 우림은 탄소를 많이 흡수하여 지구 온난화의 속도를 늦춘다."],"numbered":false,"title":"141쪽 파괴되고 있는 열대 우림(2021년 기사를 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_basic#7','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',2,'mc','auto','열대 우림이 지금처럼 계속 훼손된다면 지구촌에 어떤 영향을 미칠까요?',ARRAY['SO6-2-u3-X15','SO6-2-u3-X16']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"mc","stem":"열대 우림이 지금처럼 계속 훼손된다면 지구촌에 어떤 영향을 미칠까요?","options":[{"t":"동식물이 살 곳을 잃고, 탄소를 흡수하는 숲이 줄어 기후변화가 더 커질 수 있다","correct":true},{"t":"동식물이 살 곳이 더 넓어진다","mis":"SO6-2-u3-X15"},{"t":"탄소가 더 많이 흡수되어 지구가 시원해진다","mis":"SO6-2-u3-X15"},{"t":"열대 우림이 있는 나라에만 영향을 준다","mis":"SO6-2-u3-X16"}],"explanation":["열대 우림에는 생명체의 절반 이상이 살아요.","탄소를 많이 흡수해요.","사라지면 동식물과 기후 모두 위험해요."],"asset":{"type":"passage","lines":["지구 표면의 약 13 %를 덮고 있던 열대 우림 중 3분의 2가 파괴됐다.","2002년 이후 사라진 열대 우림의 면적이 프랑스의 영토보다 넓다.","원인 — 농사, 에너지 사용, 목축, 각종 산업 등 인간의 활동","열대 우림에는 지구 생명체의 절반 이상이 살고 있다.","열대 우림은 탄소를 많이 흡수하여 지구 온난화의 속도를 늦춘다."],"numbered":false,"title":"141쪽 파괴되고 있는 열대 우림(2021년 기사를 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_basic#8','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',2,'ox','auto','지구촌 시대에는 멀리 떨어진 곳의 소식을 쉽고 빠르게 듣고 여러 나라 사람과 문화를 나눌 수 있어요.',ARRAY['SO6-2-u3-X14']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"ox","stem":"지구촌 시대에는 멀리 떨어진 곳의 소식을 쉽고 빠르게 듣고 여러 나라 사람과 문화를 나눌 수 있어요.","answer":"O","reason_options":[{"t":"교통·통신이 발달해 세계 여러 나라가 가까워졌기 때문에","correct":true},{"t":"지구촌 시대에는 다른 나라와 교류가 줄어들기 때문에","mis":"SO6-2-u3-X14"}],"mis":"SO6-2-u3-X14","explanation":["지구촌 시대의 좋은 점이에요.","정보와 문화를 쉽게 나눠요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_basic#9','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',2,'sa','auto','「돈이나 물자 등이 다하여 없어짐」을 뜻하는 낱말을 쓰세요. 두 글자예요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"sa","stem":"「돈이나 물자 등이 다하여 없어짐」을 뜻하는 낱말을 쓰세요. 두 글자예요.","answer":["고갈"],"explanation":["142쪽 낱말 풀이예요.","자원과 에너지 ○○이라고 해요.","고갈이에요."],"mis":"SO6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_basic#10','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_basic','lesson_basic','SO6-2-u3-C7',3,'mc','auto','142쪽에서 기후변화 문제가 심해지는 원인으로 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],true,'{"seq":10,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"mc","stem":"142쪽에서 기후변화 문제가 심해지는 원인으로 든 것은 어느 것인가요?","options":[{"t":"석유나 석탄 등의 화석 연료를 지나치게 사용한 것","correct":true},{"t":"전쟁과 재난으로 사람들이 살던 곳을 떠난 것","mis":"SO6-2-u3-X15"},{"t":"광산 개발로 산지가 깎인 것","mis":"SO6-2-u3-X15"},{"t":"인구 밀도가 낮은 나라가 많은 것","mis":"SO6-2-u3-X15"}],"explanation":["문제마다 원인이 달라요.","기후변화는 화석 연료와 관련 있어요.","화석 연료를 지나치게 쓴 거예요."],"variant_rule":{"alt":[{"stem":"142쪽에서 난민이 늘고 있는 까닭으로 든 것은 어느 것인가요?","options":[{"t":"전쟁, 재난, 정치·종교·인종 등의 차이에 따른 갈등으로 살던 곳을 떠나서","correct":true},{"t":"석유와 석탄을 지나치게 사용해서","mis":"SO6-2-u3-X15"},{"t":"열대 우림을 벌채해서","mis":"SO6-2-u3-X15"},{"t":"자원을 많이 사용해서","mis":"SO6-2-u3-X15"}],"explanation":["난민 사진을 떠올려요.","살던 곳을 떠난 사람들이에요.","전쟁·재난·갈등 때문이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_challenge#1','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',2,'mc','auto','세계가 지구촌이 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X14']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"mc","stem":"세계가 지구촌이 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"과학 기술과 교통·통신이 발달했기 때문에","correct":true},{"t":"지구의 크기가 작아졌기 때문에","mis":"SO6-2-u3-X14"},{"t":"모든 나라가 한 나라로 합쳐졌기 때문에","mis":"SO6-2-u3-X14"},{"t":"사람들이 한 마을에 모여 살기 시작했기 때문에","mis":"SO6-2-u3-X14"}],"explanation":["141쪽 본문을 읽어요.","빨리 오가고 바로 연락할 수 있어요.","과학 기술과 교통·통신 덕분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_challenge#2','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',2,'ox','auto','지구촌 시대에는 좋은 점만 있고 문제점은 없어요.',ARRAY['SO6-2-u3-X14']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"ox","stem":"지구촌 시대에는 좋은 점만 있고 문제점은 없어요.","answer":"X","reason_options":[{"t":"나라끼리 가까워진 만큼 한 나라의 문제가 다른 나라에 영향을 주고 갈등이 생기기도 하기 때문에","correct":true},{"t":"나라끼리 가까워지면 문제는 모두 사라지기 때문에","mis":"SO6-2-u3-X14"}],"mis":"SO6-2-u3-X14","explanation":["좋은 점도 있어요.","문제점도 함께 나타나요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_challenge#3','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',3,'mc','auto','「인도네시아 수마트라섬의 열대 우림이 파괴되면서 그곳에 사는 희귀 호랑이와 코끼리의 서식지가 줄고 있다.」 이것은 어떤 지구촌 문제인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"mc","stem":"「인도네시아 수마트라섬의 열대 우림이 파괴되면서 그곳에 사는 희귀 호랑이와 코끼리의 서식지가 줄고 있다.」 이것은 어떤 지구촌 문제인가요?","options":[{"t":"생태계 파괴","correct":true},{"t":"난민","mis":"SO6-2-u3-X15"},{"t":"자원과 에너지 고갈","mis":"SO6-2-u3-X15"},{"t":"인구 밀도","mis":"SO6-2-u3-X15"}],"explanation":["동식물의 살 곳이 줄었어요.","자연환경이 파괴된 거예요.","생태계 파괴 문제예요."],"asset":{"type":"passage","lines":["① 산지 일부가 깎여 나간 페루의 라스밤바스 구리 광산","② 벌채로 손상된 인도네시아 수마트라섬의 열대 우림","③ 녹아 무너지고 있는 아르헨티나 로스글라시아레스 국립공원의 빙하","④ 남지중해에서 보트를 타고 구조를 요청하며 손을 흔드는 사람들"],"numbered":false,"title":"142쪽 지구촌을 위협하는 문제 — 사진 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_challenge#4','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',3,'error','auto','142쪽 사진을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"error","stem":"142쪽 사진을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「빙하가 녹아 무너지는 것은 난민 문제를 보여 줘.」","correct":true,"mis_target":"SO6-2-u3-X15"},{"t":"채원 — 「깎여 나간 구리 광산은 자원이 줄어드는 문제를 보여 줘.」","mis":"SO6-2-u3-X15"},{"t":"건우 — 「보트에서 구조를 요청하는 사람들은 난민 문제를 보여 줘.」","mis":"SO6-2-u3-X15"}],"explanation":["사진과 문제를 하나씩 짝지어요.","빙하가 녹는 것은 기후변화예요.","라온이가 잘못 짝지었어요."],"asset":{"type":"passage","lines":["① 산지 일부가 깎여 나간 페루의 라스밤바스 구리 광산","② 벌채로 손상된 인도네시아 수마트라섬의 열대 우림","③ 녹아 무너지고 있는 아르헨티나 로스글라시아레스 국립공원의 빙하","④ 남지중해에서 보트를 타고 구조를 요청하며 손을 흔드는 사람들"],"numbered":false,"title":"142쪽 지구촌을 위협하는 문제 — 사진 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_challenge#5','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',3,'mc','auto','「지구의 온도가 높아져 북극곰의 살 곳이 사라지고 있다.」 이 내용과 가장 관련 깊은 지구촌 문제는 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"mc","stem":"「지구의 온도가 높아져 북극곰의 살 곳이 사라지고 있다.」 이 내용과 가장 관련 깊은 지구촌 문제는 어느 것인가요?","options":[{"t":"기후변화","correct":true},{"t":"난민","mis":"SO6-2-u3-X15"},{"t":"자원과 에너지 고갈","mis":"SO6-2-u3-X15"},{"t":"인구 구조의 변화","mis":"SO6-2-u3-X15"}],"explanation":["지구의 온도가 높아졌어요.","얼음이 녹아 살 곳이 사라져요.","기후변화 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_challenge#6','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',3,'mc','auto','141쪽 기사가 「세계 여러 나라가 함께 열대 우림 보존을 위해 힘써야 한다」고 한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X15']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"mc","stem":"141쪽 기사가 「세계 여러 나라가 함께 열대 우림 보존을 위해 힘써야 한다」고 한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"열대 우림이 파괴되면 탄소 흡수가 줄어 지구 전체의 기후에 영향을 주기 때문에","correct":true},{"t":"열대 우림은 그 나라 사람들만 쓰는 곳이기 때문에","mis":"SO6-2-u3-X16"},{"t":"열대 우림이 사라지면 인구 밀도가 낮아지기 때문에","mis":"SO6-2-u3-X15"},{"t":"열대 우림은 지구 온난화를 빠르게 하기 때문에","mis":"SO6-2-u3-X15"}],"explanation":["열대 우림의 역할을 떠올려요.","탄소를 흡수해 온난화를 늦춰요.","지구 전체의 문제라 함께 힘써야 해요."],"asset":{"type":"passage","lines":["지구 표면의 약 13 %를 덮고 있던 열대 우림 중 3분의 2가 파괴됐다.","2002년 이후 사라진 열대 우림의 면적이 프랑스의 영토보다 넓다.","원인 — 농사, 에너지 사용, 목축, 각종 산업 등 인간의 활동","열대 우림에는 지구 생명체의 절반 이상이 살고 있다.","열대 우림은 탄소를 많이 흡수하여 지구 온난화의 속도를 늦춘다."],"numbered":false,"title":"141쪽 파괴되고 있는 열대 우림(2021년 기사를 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_challenge#7','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',3,'sa','auto','활동지 예시 — 「전쟁 때문에 나라를 떠나 임시 보호소에 머무는 사람이 있다.」 이것은 어떤 지구촌 문제인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u3-C7","difficulty":3,"kind":"sa","stem":"활동지 예시 — 「전쟁 때문에 나라를 떠나 임시 보호소에 머무는 사람이 있다.」 이것은 어떤 지구촌 문제인가요? 두 글자로 쓰세요.","answer":["난민"],"explanation":["살던 곳을 떠난 사람들이에요.","전쟁 때문에 떠났어요.","난민 문제예요."],"mis":"SO6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_challenge#8','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',4,'essay','teacher','141쪽 기사에 나타난 지구촌 문제를 쓰고, 그 문제가 지구촌에 미칠 영향을 두 가지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u3-C7","difficulty":4,"kind":"essay","stem":"141쪽 기사에 나타난 지구촌 문제를 쓰고, 그 문제가 지구촌에 미칠 영향을 두 가지 쓰세요.","answer_guide":{"answer":"예: 인간의 활동으로 열대 우림이 파괴되고 있다. 열대 우림에서 살아가는 동식물이 살 곳을 잃게 된다. 탄소 흡수를 돕는 열대 우림이 사라져 기후변화 문제가 커질 수 있다.","scoring_points":["기사 속 문제를 바르게 썼는가","동식물에 미칠 영향을 썼는가","기후에 미칠 영향을 썼는가"]},"explanation":["문제는 열대 우림 파괴예요.","숲에 사는 생명을 떠올려요.","숲이 흡수하던 탄소를 떠올려요."],"asset":{"type":"passage","lines":["지구 표면의 약 13 %를 덮고 있던 열대 우림 중 3분의 2가 파괴됐다.","2002년 이후 사라진 열대 우림의 면적이 프랑스의 영토보다 넓다.","원인 — 농사, 에너지 사용, 목축, 각종 산업 등 인간의 활동","열대 우림에는 지구 생명체의 절반 이상이 살고 있다.","열대 우림은 탄소를 많이 흡수하여 지구 온난화의 속도를 늦춘다."],"numbered":false,"title":"141쪽 파괴되고 있는 열대 우림(2021년 기사를 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_challenge#9','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',4,'mc','auto','지구촌을 위협하는 문제들이 서로 이어져 있음을 보여 주는 예로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15','SO6-2-u3-X16']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C7","difficulty":4,"kind":"mc","stem":"지구촌을 위협하는 문제들이 서로 이어져 있음을 보여 주는 예로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"열대 우림을 벌채하면 생태계가 파괴되고, 탄소 흡수가 줄어 기후변화도 커질 수 있다","correct":true},{"t":"광산을 개발해도 자원은 줄어들지 않는다","mis":"SO6-2-u3-X15"},{"t":"네 문제는 서로 아무 관계가 없다","mis":"SO6-2-u3-X15"},{"t":"각 문제는 한 나라 안에서만 일어난다","mis":"SO6-2-u3-X16"}],"explanation":["한 문제가 다른 문제를 부를 수 있어요.","숲이 사라지면 생태계와 기후가 함께 흔들려요.","문제들은 서로 이어져 있어요."],"asset":{"type":"passage","lines":["① 산지 일부가 깎여 나간 페루의 라스밤바스 구리 광산","② 벌채로 손상된 인도네시아 수마트라섬의 열대 우림","③ 녹아 무너지고 있는 아르헨티나 로스글라시아레스 국립공원의 빙하","④ 남지중해에서 보트를 타고 구조를 요청하며 손을 흔드는 사람들"],"numbered":false,"title":"142쪽 지구촌을 위협하는 문제 — 사진 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L05_challenge#10','soc',6,2,'u3','L05','tb_g6_2_soc_u3_L05_challenge','lesson_challenge','SO6-2-u3-C7',4,'essay','teacher','활동지처럼 지구촌을 위협하는 문제 가운데 가장 관심 있는 문제를 하나 고르고, 고른 까닭과 그 문제가 생기는 원인을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C7","difficulty":4,"kind":"essay","stem":"활동지처럼 지구촌을 위협하는 문제 가운데 가장 관심 있는 문제를 하나 고르고, 고른 까닭과 그 문제가 생기는 원인을 쓰세요.","answer_guide":{"answer":"예: 가장 관심 있는 문제는 기후변화이다. 지난여름에 무척 더웠던 경험이 있어 기후변화가 우리 생활에 어떤 영향을 미치는지 알고 싶기 때문이다. 기후변화는 석유나 석탄 같은 화석 연료를 지나치게 사용하면서 심해지고 있다.","scoring_points":["관심 있는 지구촌 문제를 골랐는가","고른 까닭을 경험과 이어 썼는가","그 문제의 원인을 교과서 내용으로 썼는가"]},"explanation":["네 문제 가운데 하나를 골라요.","나의 경험과 이어요.","원인은 142쪽에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_basic#1','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',1,'ox','auto','꼭 기억해요 — 지구촌 문제는 문제가 발생한 나라에만 영향을 줍니다.',ARRAY['SO6-2-u3-X16']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C8","difficulty":1,"kind":"ox","stem":"꼭 기억해요 — 지구촌 문제는 문제가 발생한 나라에만 영향을 줍니다.","answer":"X","reason_options":[{"t":"나라들이 서로 긴밀하게 이어져 있어 문제가 발생한 나라뿐만 아니라 다른 나라에도 영향을 주기 때문에","correct":true},{"t":"지구촌 문제는 국경을 넘지 못하기 때문에","mis":"SO6-2-u3-X16"}],"mis":"SO6-2-u3-X16","explanation":["143쪽 본문이에요.","각 나라는 서로 긴밀하게 이어져 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_basic#2','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',1,'sa','auto','꼭 기억해요 — 「지구촌에서 어떤 문제가 나타나고 있으며, (    )은/는 무엇인지 관심을 기울여야 합니다.」 빈칸에 알맞은 말을 쓰세요. 두 글자예요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C8","difficulty":1,"kind":"sa","stem":"꼭 기억해요 — 「지구촌에서 어떤 문제가 나타나고 있으며, (    )은/는 무엇인지 관심을 기울여야 합니다.」 빈칸에 알맞은 말을 쓰세요. 두 글자예요.","answer":["원인"],"explanation":["문제를 일으킨 까닭이에요.","붙임쪽지에도 「문제 원인」 칸이 있어요.","빈칸은 원인이에요."],"mis":"SO6-2-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_basic#3','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',1,'mc','auto','143쪽 편지에서 친구의 나라가 겪고 있는 문제는 무엇인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C8","difficulty":1,"kind":"mc","stem":"143쪽 편지에서 친구의 나라가 겪고 있는 문제는 무엇인가요?","options":[{"t":"40년 만에 가장 건조한 기후가 나타나 물이 매우 부족한 최악의 가뭄","correct":true},{"t":"큰 홍수로 마을이 물에 잠긴 일","mis":"SO6-2-u3-X15"},{"t":"전쟁으로 살던 곳을 떠난 일","mis":"SO6-2-u3-X15"},{"t":"광산 개발로 산이 깎인 일","mis":"SO6-2-u3-X15"}],"explanation":["편지의 첫 부분을 읽어요.","최악의 가뭄이에요.","물이 매우 부족해요."],"asset":{"type":"passage","lines":["저는 아프리카 동쪽 나라에 살아요. 지금 최악의 가뭄을 겪고 있어요.","40년 만에 가장 건조한 기후가 나타나 물이 매우 부족해요.","어린이들도 6 km 이상 떨어진 곳에 가서 물을 구해 와요.","농작물이 제대로 자라지 못해 굶고 있는 사람이 많아요.","과도한 탄소 배출에 따른 기후변화의 영향이 크다고 해요.","우리 나라는 탄소 배출을 적게 하는데 왜 이런 일을 겪는 걸까요?"],"numbered":false,"title":"143쪽 아프리카에 사는 친구의 편지(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_basic#4','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',1,'mc','auto','144쪽처럼 지구촌 문제를 조사할 때 주의할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X17']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C8","difficulty":1,"kind":"mc","stem":"144쪽처럼 지구촌 문제를 조사할 때 주의할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"출처가 명확하고 믿을 만한 자료인지 확인한다","correct":true},{"t":"누가 썼는지 몰라도 재미있는 글이면 쓴다","mis":"SO6-2-u3-X17"},{"t":"한 가지 사례만 찾으면 충분하다","mis":"SO6-2-u3-X17"},{"t":"지역은 빼고 문제 상황만 쓴다","mis":"SO6-2-u3-X17"}],"explanation":["자료가 믿을 만해야 해요.","어디서 나온 자료인지 확인해요.","출처를 확인해요."],"asset":{"type":"passage","lines":["다큐멘터리 등의 영상을 찾아본다.","지구촌 문제와 관련 있는 책을 찾아본다.","관련 누리집에서 통계를 살펴본다.","신문 기사, 카드 뉴스 등을 살펴본다."],"title":"144쪽 지구촌 문제를 조사하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_basic#5','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',2,'mc','auto','편지 속 가뭄의 원인으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X26','SO6-2-u3-X24','SO6-2-u3-X15']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"mc","stem":"편지 속 가뭄의 원인으로 알맞은 것은 어느 것인가요?","options":[{"t":"과도한 탄소 배출에 따른 기후변화","correct":true},{"t":"친구 나라 사람들이 물을 너무 많이 써서","mis":"SO6-2-u3-X26"},{"t":"친구 나라에 인구가 너무 많아서","mis":"SO6-2-u3-X24"},{"t":"광산을 많이 개발해서","mis":"SO6-2-u3-X15"}],"explanation":["편지 끝부분을 읽어요.","기후변화의 영향이 크대요.","과도한 탄소 배출이 원인이에요."],"asset":{"type":"passage","lines":["저는 아프리카 동쪽 나라에 살아요. 지금 최악의 가뭄을 겪고 있어요.","40년 만에 가장 건조한 기후가 나타나 물이 매우 부족해요.","어린이들도 6 km 이상 떨어진 곳에 가서 물을 구해 와요.","농작물이 제대로 자라지 못해 굶고 있는 사람이 많아요.","과도한 탄소 배출에 따른 기후변화의 영향이 크다고 해요.","우리 나라는 탄소 배출을 적게 하는데 왜 이런 일을 겪는 걸까요?"],"numbered":false,"title":"143쪽 아프리카에 사는 친구의 편지(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_basic#6','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',2,'mc','auto','편지 속 친구가 「우리 나라는 탄소 배출을 적게 하는데 왜 이런 일을 겪는 걸까요?」라고 물었어요. 알맞은 답은 어느 것인가요?',ARRAY['SO6-2-u3-X26','SO6-2-u3-X16','SO6-2-u3-X15']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"mc","stem":"편지 속 친구가 「우리 나라는 탄소 배출을 적게 하는데 왜 이런 일을 겪는 걸까요?」라고 물었어요. 알맞은 답은 어느 것인가요?","options":[{"t":"탄소는 어느 나라에서 나오든 지구 전체의 기후를 바꾸므로, 다른 나라가 배출한 탄소도 이 나라에 피해를 줄 수 있기 때문이에요","correct":true},{"t":"탄소를 적게 내는 나라는 기후변화 피해를 입지 않아요","mis":"SO6-2-u3-X26"},{"t":"그 나라 안에서 생긴 문제이니 다른 나라와는 관계없어요","mis":"SO6-2-u3-X16"},{"t":"가뭄은 기후와 관계없는 일이에요","mis":"SO6-2-u3-X15"}],"explanation":["원인이 생긴 곳과 피해를 입는 곳을 견줘요.","탄소는 지구 전체의 기후를 바꿔요.","그래서 다른 나라에도 피해가 가요."],"asset":{"type":"passage","lines":["저는 아프리카 동쪽 나라에 살아요. 지금 최악의 가뭄을 겪고 있어요.","40년 만에 가장 건조한 기후가 나타나 물이 매우 부족해요.","어린이들도 6 km 이상 떨어진 곳에 가서 물을 구해 와요.","농작물이 제대로 자라지 못해 굶고 있는 사람이 많아요.","과도한 탄소 배출에 따른 기후변화의 영향이 크다고 해요.","우리 나라는 탄소 배출을 적게 하는데 왜 이런 일을 겪는 걸까요?"],"numbered":false,"title":"143쪽 아프리카에 사는 친구의 편지(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_basic#7','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',2,'blank','auto','145쪽 — 「조사한 지구촌 문제는 붙임쪽지에 지역, 문제 상황, (    )을/를 요약해 쓴다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u3-X17']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"blank","stem":"145쪽 — 「조사한 지구촌 문제는 붙임쪽지에 지역, 문제 상황, (    )을/를 요약해 쓴다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"문제 원인","correct":true},{"t":"인구수","mis":"SO6-2-u3-X17"},{"t":"느낀 점","mis":"SO6-2-u3-X17"},{"t":"나라의 수도","mis":"SO6-2-u3-X17"}],"explanation":["145쪽 붙임쪽지를 봐요.","어디서, 무엇이, 왜를 써요.","빈칸은 문제 원인이에요."],"asset":{"type":"passage","lines":["붙임쪽지 ㉮ 지역 — 우리나라, 유럽, 미국 등","　문제 상황 — 기록적인 폭염 · 미국 마이애미 솜브레로 지역의 산호초 폐사","　문제 원인 — 탄소 배출과 온실 효과에 따른 지구 온도 상승 등","붙임쪽지 ㉯ 지역 — 유럽","　문제 상황 — 꽃가루받이에 중요한 호박벌의 수 감소 · 60년 안에 70 % 이상 생존 위기","　문제 원인 — 지구 온난화, 인간의 활동에 따른 벌의 서식지 파괴 등"],"numbered":false,"title":"145쪽 세계지도에 붙인 붙임쪽지 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_basic#8','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',2,'mc','auto','145쪽 붙임쪽지 ㉯에 쓰인 문제 원인은 어느 것인가요?',ARRAY['SO6-2-u3-X17','SO6-2-u3-X15']::text[],true,'{"seq":8,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"mc","stem":"145쪽 붙임쪽지 ㉯에 쓰인 문제 원인은 어느 것인가요?","options":[{"t":"지구 온난화, 인간의 활동에 따른 벌의 서식지 파괴 등","correct":true},{"t":"탄소 배출과 온실 효과에 따른 지구 온도 상승 등","mis":"SO6-2-u3-X17"},{"t":"전쟁으로 살 곳을 잃은 사람들","mis":"SO6-2-u3-X15"},{"t":"출처를 알 수 없음","mis":"SO6-2-u3-X17"}],"explanation":["㉯는 유럽의 호박벌 이야기예요.","원인 칸을 읽어요.","온난화와 서식지 파괴예요."],"asset":{"type":"passage","lines":["붙임쪽지 ㉮ 지역 — 우리나라, 유럽, 미국 등","　문제 상황 — 기록적인 폭염 · 미국 마이애미 솜브레로 지역의 산호초 폐사","　문제 원인 — 탄소 배출과 온실 효과에 따른 지구 온도 상승 등","붙임쪽지 ㉯ 지역 — 유럽","　문제 상황 — 꽃가루받이에 중요한 호박벌의 수 감소 · 60년 안에 70 % 이상 생존 위기","　문제 원인 — 지구 온난화, 인간의 활동에 따른 벌의 서식지 파괴 등"],"numbered":false,"title":"145쪽 세계지도에 붙인 붙임쪽지 둘"},"variant_rule":{"alt":[{"stem":"145쪽 붙임쪽지 ㉮에 쓰인 문제 원인은 어느 것인가요?","options":[{"t":"탄소 배출과 온실 효과에 따른 지구 온도 상승 등","correct":true},{"t":"인간의 활동에 따른 벌의 서식지 파괴 등","mis":"SO6-2-u3-X17"},{"t":"정치·종교 차이에 따른 갈등","mis":"SO6-2-u3-X15"},{"t":"출처를 알 수 없음","mis":"SO6-2-u3-X17"}],"explanation":["㉮는 폭염과 산호초 이야기예요.","원인 칸을 읽어요.","탄소 배출과 온실 효과예요."],"asset":{"type":"passage","lines":["붙임쪽지 ㉮ 지역 — 우리나라, 유럽, 미국 등","　문제 상황 — 기록적인 폭염 · 미국 마이애미 솜브레로 지역의 산호초 폐사","　문제 원인 — 탄소 배출과 온실 효과에 따른 지구 온도 상승 등","붙임쪽지 ㉯ 지역 — 유럽","　문제 상황 — 꽃가루받이에 중요한 호박벌의 수 감소 · 60년 안에 70 % 이상 생존 위기","　문제 원인 — 지구 온난화, 인간의 활동에 따른 벌의 서식지 파괴 등"],"numbered":false,"title":"145쪽 세계지도에 붙인 붙임쪽지 둘"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_basic#9','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',2,'mc','auto','147쪽 자료에서 만드는 데 가장 많은 물이 드는 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16']::text[],true,'{"seq":9,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"mc","stem":"147쪽 자료에서 만드는 데 가장 많은 물이 드는 것은 어느 것인가요?","options":[{"t":"청바지 한 벌","correct":true},{"t":"면 티셔츠 한 벌","mis":"SO6-2-u3-X16"},{"t":"A4 용지 한 장","mis":"SO6-2-u3-X16"}],"explanation":["세 물건의 물의 양을 견줘요.","청바지 한 벌은 1만 2,000 L예요.","가장 많은 것은 청바지예요."],"asset":{"type":"passage","lines":["A4 용지 한 장 — 물 10 L","면 티셔츠 한 벌 — 물 2,700 L","청바지 한 벌 — 물 1만 2,000 L"],"title":"147쪽 각 물건을 만드는 데 사용하는 물의 양"},"variant_rule":{"alt":[{"stem":"147쪽 자료에서 면 티셔츠 한 벌을 만드는 데 드는 물의 양은 얼마인가요?","options":[{"t":"약 2,700 L","correct":true},{"t":"약 10 L","mis":"SO6-2-u3-X16"},{"t":"약 1만 2,000 L","mis":"SO6-2-u3-X16"}],"explanation":["면 티셔츠 줄을 읽어요.","2,700 L가 필요해요.","우리 옷 한 벌에도 많은 물이 들어요."],"asset":{"type":"passage","lines":["A4 용지 한 장 — 물 10 L","면 티셔츠 한 벌 — 물 2,700 L","청바지 한 벌 — 물 1만 2,000 L"],"title":"147쪽 각 물건을 만드는 데 사용하는 물의 양"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_basic#10','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_basic','lesson_basic','SO6-2-u3-C8',3,'mc','auto','147쪽 정리처럼 지구촌을 위협하는 문제를 조사하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X17']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"147쪽 정리처럼 지구촌을 위협하는 문제를 조사하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"문제 생각하기 → 조사 방법 정하기 → 문제 상황·원인 조사하기 → 내용 정리하기","correct":true},{"t":"내용 정리하기 → 문제 생각하기 → 조사 방법 정하기 → 문제 상황·원인 조사하기","mis":"SO6-2-u3-X17"},{"t":"조사 방법 정하기 → 내용 정리하기 → 문제 생각하기 → 문제 상황·원인 조사하기","mis":"SO6-2-u3-X17"},{"t":"문제 상황·원인 조사하기 → 문제 생각하기 → 내용 정리하기 → 조사 방법 정하기","mis":"SO6-2-u3-X17"}],"explanation":["먼저 무엇을 조사할지 정해요.","그다음 방법을 정하고 조사해요.","마지막에 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_challenge#1','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',2,'mc','auto','조사한 내용을 붙임쪽지에 써서 세계지도의 해당 나라에 붙이면 좋은 점은 무엇인가요?',ARRAY['SO6-2-u3-X23','SO6-2-u3-X17']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"mc","stem":"조사한 내용을 붙임쪽지에 써서 세계지도의 해당 나라에 붙이면 좋은 점은 무엇인가요?","options":[{"t":"지구촌 곳곳에 어떤 문제가 나타나는지 한눈에 파악할 수 있다","correct":true},{"t":"나라별 인구수를 외울 수 있다","mis":"SO6-2-u3-X23"},{"t":"지도가 예뻐진다","mis":"SO6-2-u3-X17"},{"t":"문제 원인을 쓰지 않아도 된다","mis":"SO6-2-u3-X17"}],"explanation":["145쪽 말풍선을 읽어요.","여러 문제를 지도에 모아요.","한눈에 파악할 수 있어요."],"asset":{"type":"passage","lines":["붙임쪽지 ㉮ 지역 — 우리나라, 유럽, 미국 등","　문제 상황 — 기록적인 폭염 · 미국 마이애미 솜브레로 지역의 산호초 폐사","　문제 원인 — 탄소 배출과 온실 효과에 따른 지구 온도 상승 등","붙임쪽지 ㉯ 지역 — 유럽","　문제 상황 — 꽃가루받이에 중요한 호박벌의 수 감소 · 60년 안에 70 % 이상 생존 위기","　문제 원인 — 지구 온난화, 인간의 활동에 따른 벌의 서식지 파괴 등"],"numbered":false,"title":"145쪽 세계지도에 붙인 붙임쪽지 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_challenge#2','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',2,'sa','auto','143쪽 말풍선 — 「여러 산업에서 사용하는 (    )은/는 탄소를 많이 배출해 기후변화를 일으키는 가장 큰 원인으로 꼽혀요.」 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C8","difficulty":2,"kind":"sa","stem":"143쪽 말풍선 — 「여러 산업에서 사용하는 (    )은/는 탄소를 많이 배출해 기후변화를 일으키는 가장 큰 원인으로 꼽혀요.」 빈칸에 알맞은 말을 쓰세요.","answer":["화석 연료","화석연료"],"explanation":["석유나 석탄을 묶는 말이에요.","태울 때 탄소가 많이 나와요.","빈칸은 화석 연료예요."],"mis":"SO6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_challenge#3','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',3,'mc','auto','편지에 나타난 문제를 우리가 함께 고민하고 해결해야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X26']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"편지에 나타난 문제를 우리가 함께 고민하고 해결해야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리가 배출하는 탄소가 다른 나라에 심각한 문제를 일으킬 수 있기 때문에","correct":true},{"t":"아프리카에서 일어난 일이라 우리와는 관계없기 때문에","mis":"SO6-2-u3-X16"},{"t":"탄소를 많이 내는 나라만 피해를 입기 때문에","mis":"SO6-2-u3-X26"},{"t":"가뭄은 그 나라 사람들이 물을 아끼지 않아 생긴 일이기 때문에","mis":"SO6-2-u3-X26"}],"explanation":["기후변화는 지구 전체의 일이에요.","우리가 낸 탄소도 영향을 줘요.","그래서 함께 고민해야 해요."],"asset":{"type":"passage","lines":["저는 아프리카 동쪽 나라에 살아요. 지금 최악의 가뭄을 겪고 있어요.","40년 만에 가장 건조한 기후가 나타나 물이 매우 부족해요.","어린이들도 6 km 이상 떨어진 곳에 가서 물을 구해 와요.","농작물이 제대로 자라지 못해 굶고 있는 사람이 많아요.","과도한 탄소 배출에 따른 기후변화의 영향이 크다고 해요.","우리 나라는 탄소 배출을 적게 하는데 왜 이런 일을 겪는 걸까요?"],"numbered":false,"title":"143쪽 아프리카에 사는 친구의 편지(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_challenge#4','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',3,'mc','auto','활동지 예시 — 「투발루는 9개 섬 가운데 2개 섬이 이미 물에 잠겼다.」 이 문제의 원인으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15','SO6-2-u3-X26']::text[],true,'{"seq":4,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"활동지 예시 — 「투발루는 9개 섬 가운데 2개 섬이 이미 물에 잠겼다.」 이 문제의 원인으로 알맞은 것은 어느 것인가요?","options":[{"t":"기후변화에 따른 해수면 상승","correct":true},{"t":"자원을 확보하기 위한 갈등","mis":"SO6-2-u3-X15"},{"t":"광산 개발로 산지가 깎임","mis":"SO6-2-u3-X15"},{"t":"투발루 사람들이 바다를 오염시킴","mis":"SO6-2-u3-X26"}],"explanation":["섬이 바다에 잠기고 있어요.","바닷물의 높이가 올라갔어요.","기후변화에 따른 해수면 상승이에요."],"variant_rule":{"alt":[{"stem":"활동지 예시 — 「석유가 매장된 카스피해를 두고 주변 국가들 사이에 갈등이 생겼다.」 이 문제의 원인으로 알맞은 것은 어느 것인가요?","options":[{"t":"자원을 확보하기 위한 갈등","correct":true},{"t":"기후변화에 따른 해수면 상승","mis":"SO6-2-u3-X15"},{"t":"열대 우림 벌채","mis":"SO6-2-u3-X15"},{"t":"인구 구조의 변화","mis":"SO6-2-u3-X15"}],"explanation":["석유는 자원이에요.","자원을 서로 가지려 해요.","자원을 확보하기 위한 갈등이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_challenge#5','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',3,'error','auto','모둠이 지구촌 문제 조사 계획을 말했어요. 알맞지 않은 계획을 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X17']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"error","stem":"모둠이 지구촌 문제 조사 계획을 말했어요. 알맞지 않은 계획을 말한 친구는 누구인가요?","options":[{"t":"하준 — 「인터넷에서 찾은 글이면 누가 썼는지 몰라도 그대로 쓰자.」","correct":true,"mis_target":"SO6-2-u3-X17"},{"t":"소윤 — 「다큐멘터리 영상과 관련 책을 함께 찾아보자.」","mis":"SO6-2-u3-X17"},{"t":"민재 — 「관련 누리집에서 통계도 살펴보자.」","mis":"SO6-2-u3-X17"}],"explanation":["조사 방법 넷은 모두 쓸 수 있어요.","하지만 출처를 꼭 확인해야 해요.","하준이의 계획이 알맞지 않아요."],"asset":{"type":"passage","lines":["다큐멘터리 등의 영상을 찾아본다.","지구촌 문제와 관련 있는 책을 찾아본다.","관련 누리집에서 통계를 살펴본다.","신문 기사, 카드 뉴스 등을 살펴본다."],"title":"144쪽 지구촌 문제를 조사하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_challenge#6','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',3,'mc','auto','147쪽 풍덩 사회 속으로를 읽고 할 수 있는 실천으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X16']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"147쪽 풍덩 사회 속으로를 읽고 할 수 있는 실천으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"충동적으로 불필요한 옷을 사는 대신 필요할 때 적절히 옷을 산다","correct":true},{"t":"싸고 예쁜 옷이 나올 때마다 새로 산다","mis":"SO6-2-u3-X21"},{"t":"옷은 지구촌 문제와 관계없으니 마음대로 버린다","mis":"SO6-2-u3-X16"},{"t":"물을 아끼려고 옷을 한 번만 입고 버린다","mis":"SO6-2-u3-X16"}],"explanation":["버리는 옷이 지구촌에 부담이 돼요.","옷 한 벌에도 많은 물이 들어요.","필요할 때만 사요."],"asset":{"type":"speech","turns":[{"who":"아이","text":"어머니, 옷이 새로 나왔나 봐요. 가격도 싸고 예뻐서 사고 싶어요!"},{"who":"뉴스","text":"버리는 옷이 많아지면서 지구촌에 부담이 되고 있습니다."},{"who":"아이","text":"이제 필요할 때만 옷을 사는 게 좋겠어요."},{"who":"어머니","text":"그래. 작은 일부터 실천해 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_challenge#7','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',3,'mc','auto','145쪽 붙임쪽지 ㉮처럼 「우리나라, 유럽, 미국 등」 여러 곳에 폭염이 나타났다는 것에서 알 수 있는 지구촌 문제의 특징은 무엇인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X26','SO6-2-u3-X17']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"145쪽 붙임쪽지 ㉮처럼 「우리나라, 유럽, 미국 등」 여러 곳에 폭염이 나타났다는 것에서 알 수 있는 지구촌 문제의 특징은 무엇인가요?","options":[{"t":"지구촌 문제는 한 지역에 그치지 않고 여러 나라에서 함께 나타날 수 있다","correct":true},{"t":"폭염은 한 나라에서만 나타난다","mis":"SO6-2-u3-X16"},{"t":"여러 나라에서 나타나면 원인이 저마다 전혀 다르다","mis":"SO6-2-u3-X26"},{"t":"지역은 조사하지 않아도 된다","mis":"SO6-2-u3-X17"}],"explanation":["지역 칸에 여러 나라가 쓰였어요.","같은 원인으로 여러 곳에 문제가 생겨요.","지구촌 문제는 우리 모두의 문제예요."],"asset":{"type":"passage","lines":["붙임쪽지 ㉮ 지역 — 우리나라, 유럽, 미국 등","　문제 상황 — 기록적인 폭염 · 미국 마이애미 솜브레로 지역의 산호초 폐사","　문제 원인 — 탄소 배출과 온실 효과에 따른 지구 온도 상승 등","붙임쪽지 ㉯ 지역 — 유럽","　문제 상황 — 꽃가루받이에 중요한 호박벌의 수 감소 · 60년 안에 70 % 이상 생존 위기","　문제 원인 — 지구 온난화, 인간의 활동에 따른 벌의 서식지 파괴 등"],"numbered":false,"title":"145쪽 세계지도에 붙인 붙임쪽지 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_challenge#8','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',4,'essay','teacher','143쪽 편지 내용을 붙임쪽지 세 칸(지역 · 문제 상황 · 문제 원인)으로 정리하고, 이 문제가 우리와도 관계있는 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u3-C8","difficulty":4,"kind":"essay","stem":"143쪽 편지 내용을 붙임쪽지 세 칸(지역 · 문제 상황 · 문제 원인)으로 정리하고, 이 문제가 우리와도 관계있는 까닭을 쓰세요.","answer_guide":{"answer":"예: 지역 — 아프리카 동쪽 나라. 문제 상황 — 40년 만에 가장 건조한 기후로 최악의 가뭄을 겪고, 물이 부족해 어린이들도 6 km 이상 떨어진 곳에서 물을 구해 오며 굶는 사람이 많다. 문제 원인 — 과도한 탄소 배출에 따른 기후변화. 우리가 배출하는 탄소도 지구 전체의 기후를 바꾸어 이 나라에 피해를 줄 수 있으므로 우리와 관계있다.","scoring_points":["지역·문제 상황·문제 원인을 바르게 썼는가","원인을 기후변화와 이어 썼는가","우리와 관계있는 까닭을 썼는가"]},"explanation":["세 칸을 채워요.","원인은 편지 끝에 있어요.","우리 탄소도 영향을 줘요."],"asset":{"type":"passage","lines":["저는 아프리카 동쪽 나라에 살아요. 지금 최악의 가뭄을 겪고 있어요.","40년 만에 가장 건조한 기후가 나타나 물이 매우 부족해요.","어린이들도 6 km 이상 떨어진 곳에 가서 물을 구해 와요.","농작물이 제대로 자라지 못해 굶고 있는 사람이 많아요.","과도한 탄소 배출에 따른 기후변화의 영향이 크다고 해요.","우리 나라는 탄소 배출을 적게 하는데 왜 이런 일을 겪는 걸까요?"],"numbered":false,"title":"143쪽 아프리카에 사는 친구의 편지(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_challenge#9','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',4,'mc','auto','편지와 붙임쪽지를 함께 보고 지구촌 문제의 특징을 가장 알맞게 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X26','SO6-2-u3-X16','SO6-2-u3-X17']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C8","difficulty":4,"kind":"mc","stem":"편지와 붙임쪽지를 함께 보고 지구촌 문제의 특징을 가장 알맞게 정리한 것은 어느 것인가요?","options":[{"t":"지구촌 문제는 한 국가 안에서 생기기도 하고 국가 사이에 생기기도 하며, 원인이 생긴 곳과 피해를 입는 곳이 다를 수 있다","correct":true},{"t":"지구촌 문제의 원인과 피해는 언제나 같은 나라 안에 있다","mis":"SO6-2-u3-X26"},{"t":"지구촌 문제는 문제가 생긴 나라 사람들만 고민하면 된다","mis":"SO6-2-u3-X16"},{"t":"지구촌 문제는 한두 가지 사례만 알면 충분하다","mis":"SO6-2-u3-X17"}],"explanation":["편지 속 나라는 탄소를 적게 내요.","그래도 기후변화 피해를 입어요.","원인과 피해의 자리가 다를 수 있어요."],"asset":{"type":"passage","lines":["저는 아프리카 동쪽 나라에 살아요. 지금 최악의 가뭄을 겪고 있어요.","40년 만에 가장 건조한 기후가 나타나 물이 매우 부족해요.","어린이들도 6 km 이상 떨어진 곳에 가서 물을 구해 와요.","농작물이 제대로 자라지 못해 굶고 있는 사람이 많아요.","과도한 탄소 배출에 따른 기후변화의 영향이 크다고 해요.","우리 나라는 탄소 배출을 적게 하는데 왜 이런 일을 겪는 걸까요?"],"numbered":false,"title":"143쪽 아프리카에 사는 친구의 편지(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L06_challenge#10','soc',6,2,'u3','L06','tb_g6_2_soc_u3_L06_challenge','lesson_challenge','SO6-2-u3-C8',4,'essay','teacher','지구촌을 위협하는 문제와 원인을 조사하며 느낀 점과 더 알고 싶은 점을 쓰고, 더 알고 싶은 점을 어떤 방법으로 조사할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C8","difficulty":4,"kind":"essay","stem":"지구촌을 위협하는 문제와 원인을 조사하며 느낀 점과 더 알고 싶은 점을 쓰고, 더 알고 싶은 점을 어떤 방법으로 조사할지 쓰세요.","answer_guide":{"answer":"예: 느낀 점 — 지구촌 문제는 한 국가 안에서 발생하기도 하고 국가 사이에 발생하기도 한다는 것을 알게 됐다. 더 알고 싶은 점 — 지구촌 문제가 더욱 심각해지면 어떤 일이 생길지 알고 싶다. 조사 방법 — 출처가 분명한 관련 누리집의 통계와 다큐멘터리 영상을 찾아보겠다.","scoring_points":["느낀 점을 지구촌 문제의 특징과 이어 썼는가","더 알고 싶은 점을 구체적으로 썼는가","믿을 만한 조사 방법을 썼는가"]},"explanation":["조사하며 알게 된 특징을 떠올려요.","궁금한 점을 하나 골라요.","출처가 분명한 방법을 정해요."],"asset":{"type":"passage","lines":["다큐멘터리 등의 영상을 찾아본다.","지구촌 문제와 관련 있는 책을 찾아본다.","관련 누리집에서 통계를 살펴본다.","신문 기사, 카드 뉴스 등을 살펴본다."],"title":"144쪽 지구촌 문제를 조사하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_basic#1','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C10',1,'sa','auto','꼭 기억해요 — 「개인이나 민간단체가 중심이 되어 공공의 이익을 지키려고 만든 (    )이/가 있습니다.」 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C10","difficulty":1,"kind":"sa","stem":"꼭 기억해요 — 「개인이나 민간단체가 중심이 되어 공공의 이익을 지키려고 만든 (    )이/가 있습니다.」 빈칸에 알맞은 말을 쓰세요.","answer":["비정부 기구","비정부기구"],"explanation":["나라들이 모여 만든 국제기구와 달라요.","개인이나 민간단체가 만들었어요.","빈칸은 비정부 기구예요."],"mis":"SO6-2-u3-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_basic#2','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',1,'ox','auto','꼭 기억해요 — 지구촌의 지속가능한 미래는 모든 사람의 노력 속에서 이루어집니다.',ARRAY['SO6-2-u3-X19']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C9","difficulty":1,"kind":"ox","stem":"꼭 기억해요 — 지구촌의 지속가능한 미래는 모든 사람의 노력 속에서 이루어집니다.","answer":"O","reason_options":[{"t":"오늘날의 모든 사람이 지구 환경을 개선하고 보존해 미래 세대에 물려주려는 노력 속에서 이루어지기 때문에","correct":true},{"t":"몇몇 나라의 정부만 노력하면 이루어지기 때문에","mis":"SO6-2-u3-X19"}],"mis":"SO6-2-u3-X19","explanation":["148쪽 본문이에요.","개인·기업·국가 모두 노력해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_basic#3','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C10',1,'mc','auto','150쪽에서 「국제 평화와 안전을 지키고자 정치, 경제, 사회, 문화 등에서 국제적인 협력을 해 나간다」고 소개한 곳은 어디인가요?',ARRAY['SO6-2-u3-X20']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C10","difficulty":1,"kind":"mc","stem":"150쪽에서 「국제 평화와 안전을 지키고자 정치, 경제, 사회, 문화 등에서 국제적인 협력을 해 나간다」고 소개한 곳은 어디인가요?","options":[{"t":"국제 연합","correct":true},{"t":"그린피스","mis":"SO6-2-u3-X20"},{"t":"국경 없는 의사회","mis":"SO6-2-u3-X20"},{"t":"세계 자연 기금","mis":"SO6-2-u3-X20"}],"explanation":["150쪽 국제기구 설명을 읽어요.","세계 여러 나라로 구성된 기구예요.","국제 연합이에요."],"asset":{"type":"passage","lines":["국제 연합 — 국제 평화와 안전을 지키고자 여러 분야에서 국제 협력","국제 연합 아동 기금 — 어려움을 겪는 어린이에게 의료·식량·교육 제공","국제 연합 난민 기구 — 난민 보호, 생활에 필요한 물품·의료·교육 제공","국경 없는 의사회 — 고통받는 사람들에게 차별 없이 의료 제공","세계 자연 기금 — 생물 다양성 보전, 기후변화에 대응하는 활동","그린피스 — 환경 연구, 해양 생태계 보호 활동"],"title":"150쪽 국제기구와 비정부 기구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_basic#4','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',1,'mc','auto','148쪽 말풍선에서 녹색 제품을 소비하는 까닭으로 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X18']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C9","difficulty":1,"kind":"mc","stem":"148쪽 말풍선에서 녹색 제품을 소비하는 까닭으로 든 것은 어느 것인가요?","options":[{"t":"물건을 생산할 때 지구의 자원이나 에너지를 적게 사용하여 오염 물질 배출을 최소화하기 때문에","correct":true},{"t":"색이 모두 초록색이라 보기 좋기 때문에","mis":"SO6-2-u3-X18"},{"t":"가장 값이 싸기 때문에","mis":"SO6-2-u3-X18"},{"t":"한 번 쓰고 버리기 편하기 때문에","mis":"SO6-2-u3-X18"}],"explanation":["말풍선의 답을 읽어요.","생산할 때 자원과 에너지를 아껴요.","오염 물질을 적게 내요."],"asset":{"type":"passage","lines":["① 쓰레기를 분리배출하고 재활용한다.","② 녹색 제품을 소비하고 일회용품 사용을 줄인다.","③ 물 적게 쓰기, 안 쓰는 전등 끄기 등으로 자원과 에너지를 아낀다.","④ 동식물이 살아가는 곳을 함부로 훼손하지 않고 보존한다."],"numbered":false,"title":"148쪽 개인의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_basic#5','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',2,'match','auto','148~149쪽의 노력과 그 노력을 하는 주체를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"match","stem":"148~149쪽의 노력과 그 노력을 하는 주체를 알맞게 이으세요.","pairs":[{"l":"쓰레기를 분리배출하고 재활용한다","r":"개인"},{"l":"라벨을 없애고 뚜껑을 줄인 생수병을 만든다","r":"기업"},{"l":"기후변화 협약에 가입하고 탄소를 줄일 목표를 세운다","r":"국가"}],"mis":"SO6-2-u3-X19","explanation":["누가 하는 일인지 떠올려요.","생활 속 실천은 개인, 제품은 기업이에요.","협약과 제도는 국가예요."],"asset":{"type":"passage","lines":["기업 ① 라벨을 없애고 플라스틱 뚜껑의 크기를 줄인 생수병","기업 ② 플라스틱을 재활용해 만든 운동화","국가 ③ 기후변화 협약에 가입하고 탄소 배출을 줄이려는 목표를 세운다.","국가 ④ 난민 보호 시설을 마련하고 난민이 사회에 적응하도록 돕는다."],"title":"149쪽 기업과 국가의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_basic#6','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C10',2,'mc','auto','150쪽에서 「전쟁이나 가난 등으로 어려움을 겪는 어린이에게 의료, 식량, 교육 등을 제공한다」고 소개한 국제기구는 어디인가요?',ARRAY['SO6-2-u3-X20']::text[],true,'{"seq":6,"concept":"SO6-2-u3-C10","difficulty":2,"kind":"mc","stem":"150쪽에서 「전쟁이나 가난 등으로 어려움을 겪는 어린이에게 의료, 식량, 교육 등을 제공한다」고 소개한 국제기구는 어디인가요?","options":[{"t":"국제 연합 아동 기금","correct":true},{"t":"국제 연합 난민 기구","mis":"SO6-2-u3-X20"},{"t":"그린피스","mis":"SO6-2-u3-X20"},{"t":"세계 자연 기금","mis":"SO6-2-u3-X20"}],"explanation":["어린이를 돕는 기구를 찾아요.","의료·식량·교육을 줘요.","국제 연합 아동 기금이에요."],"asset":{"type":"passage","lines":["국제 연합 — 국제 평화와 안전을 지키고자 여러 분야에서 국제 협력","국제 연합 아동 기금 — 어려움을 겪는 어린이에게 의료·식량·교육 제공","국제 연합 난민 기구 — 난민 보호, 생활에 필요한 물품·의료·교육 제공","국경 없는 의사회 — 고통받는 사람들에게 차별 없이 의료 제공","세계 자연 기금 — 생물 다양성 보전, 기후변화에 대응하는 활동","그린피스 — 환경 연구, 해양 생태계 보호 활동"],"title":"150쪽 국제기구와 비정부 기구"},"variant_rule":{"alt":[{"stem":"150쪽에서 「난민을 보호하고, 난민이 생활하는 데 필요한 물품, 의료, 교육 등을 제공한다」고 소개한 국제기구는 어디인가요?","options":[{"t":"국제 연합 난민 기구","correct":true},{"t":"국제 연합 아동 기금","mis":"SO6-2-u3-X20"},{"t":"국경 없는 의사회","mis":"SO6-2-u3-X20"},{"t":"그린피스","mis":"SO6-2-u3-X20"}],"explanation":["난민을 돕는 기구를 찾아요.","물품·의료·교육을 줘요.","국제 연합 난민 기구예요."],"asset":{"type":"passage","lines":["국제 연합 — 국제 평화와 안전을 지키고자 여러 분야에서 국제 협력","국제 연합 아동 기금 — 어려움을 겪는 어린이에게 의료·식량·교육 제공","국제 연합 난민 기구 — 난민 보호, 생활에 필요한 물품·의료·교육 제공","국경 없는 의사회 — 고통받는 사람들에게 차별 없이 의료 제공","세계 자연 기금 — 생물 다양성 보전, 기후변화에 대응하는 활동","그린피스 — 환경 연구, 해양 생태계 보호 활동"],"title":"150쪽 국제기구와 비정부 기구"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_basic#7','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',2,'mc','auto','148쪽 본문에서 지구촌의 지속가능한 미래가 이루어지는 방법으로 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X18','SO6-2-u3-X19']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"mc","stem":"148쪽 본문에서 지구촌의 지속가능한 미래가 이루어지는 방법으로 든 것은 어느 것인가요?","options":[{"t":"오늘날의 모든 사람이 지구 환경을 개선하고 보존하여 미래 세대에 물려주려는 노력","correct":true},{"t":"지금 세대가 편리하게 쓸 수 있도록 자원을 많이 개발하는 것","mis":"SO6-2-u3-X18"},{"t":"사람에게 필요한 것만 생각하고 동식물은 생각하지 않는 것","mis":"SO6-2-u3-X18"},{"t":"국가 한 곳만 노력하는 것","mis":"SO6-2-u3-X19"}],"explanation":["148쪽 첫 문장을 읽어요.","미래 세대를 생각해요.","모든 사람이 함께 노력해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_basic#8','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',2,'mc','auto','149쪽의 「플라스틱을 재활용해 만든 운동화」는 어느 주체의 어떤 노력인가요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X20']::text[],true,'{"seq":8,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"mc","stem":"149쪽의 「플라스틱을 재활용해 만든 운동화」는 어느 주체의 어떤 노력인가요?","options":[{"t":"기업 — 친환경 소재의 제품을 생산하는 기술을 개발한다","correct":true},{"t":"개인 — 쓰레기를 분리배출한다","mis":"SO6-2-u3-X19"},{"t":"국가 — 법과 제도를 마련한다","mis":"SO6-2-u3-X19"},{"t":"비정부 기구 — 차별 없이 의료를 제공한다","mis":"SO6-2-u3-X20"}],"explanation":["제품을 만드는 주체는 기업이에요.","버려진 플라스틱을 소재로 썼어요.","친환경 소재 기술이에요."],"asset":{"type":"passage","lines":["기업 ① 라벨을 없애고 플라스틱 뚜껑의 크기를 줄인 생수병","기업 ② 플라스틱을 재활용해 만든 운동화","국가 ③ 기후변화 협약에 가입하고 탄소 배출을 줄이려는 목표를 세운다.","국가 ④ 난민 보호 시설을 마련하고 난민이 사회에 적응하도록 돕는다."],"title":"149쪽 기업과 국가의 노력"},"variant_rule":{"alt":[{"stem":"149쪽의 「라벨을 없애고 플라스틱 뚜껑의 크기를 줄인 생수병」은 어느 주체의 어떤 노력인가요?","options":[{"t":"기업 — 자원을 적게 사용한 제품을 생산한다","correct":true},{"t":"개인 — 일회용품 사용을 줄인다","mis":"SO6-2-u3-X19"},{"t":"국가 — 국제 협약을 지킨다","mis":"SO6-2-u3-X19"},{"t":"국제기구 — 국제 협력을 해 나간다","mis":"SO6-2-u3-X20"}],"explanation":["제품을 만드는 주체는 기업이에요.","라벨과 뚜껑의 플라스틱을 줄였어요.","자원을 적게 쓴 제품이에요."],"asset":{"type":"passage","lines":["기업 ① 라벨을 없애고 플라스틱 뚜껑의 크기를 줄인 생수병","기업 ② 플라스틱을 재활용해 만든 운동화","국가 ③ 기후변화 협약에 가입하고 탄소 배출을 줄이려는 목표를 세운다.","국가 ④ 난민 보호 시설을 마련하고 난민이 사회에 적응하도록 돕는다."],"title":"149쪽 기업과 국가의 노력"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_basic#9','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C9',2,'ox','auto','난민 보호 시설을 마련하고 난민이 우리 사회에 적응하도록 돕는 것은 국가의 노력이에요.',ARRAY['SO6-2-u3-X19']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"ox","stem":"난민 보호 시설을 마련하고 난민이 우리 사회에 적응하도록 돕는 것은 국가의 노력이에요.","answer":"O","reason_options":[{"t":"국가는 법과 제도를 마련하고 다양한 정책을 펼치기 때문에","correct":true},{"t":"난민 보호는 개인이 혼자 하는 노력이기 때문에","mis":"SO6-2-u3-X19"}],"mis":"SO6-2-u3-X19","explanation":["149쪽 국가의 노력이에요.","시설과 제도를 마련해요.","그래서 O예요."],"asset":{"type":"passage","lines":["기업 ① 라벨을 없애고 플라스틱 뚜껑의 크기를 줄인 생수병","기업 ② 플라스틱을 재활용해 만든 운동화","국가 ③ 기후변화 협약에 가입하고 탄소 배출을 줄이려는 목표를 세운다.","국가 ④ 난민 보호 시설을 마련하고 난민이 사회에 적응하도록 돕는다."],"title":"149쪽 기업과 국가의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_basic#10','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_basic','lesson_basic','SO6-2-u3-C10',3,'mc','auto','국제기구와 비정부 기구의 차이를 알맞게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X20']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C10","difficulty":3,"kind":"mc","stem":"국제기구와 비정부 기구의 차이를 알맞게 말한 것은 어느 것인가요?","options":[{"t":"국제기구는 세계 여러 나라로 구성되고, 비정부 기구는 개인이나 민간단체가 중심이 되어 만든다","correct":true},{"t":"국제기구는 개인이 만들고, 비정부 기구는 나라들이 만든다","mis":"SO6-2-u3-X20"},{"t":"두 기구는 이름만 다르고 만든 주체는 같다","mis":"SO6-2-u3-X20"},{"t":"비정부 기구는 한 나라 안에서만 활동한다","mis":"SO6-2-u3-X20"}],"explanation":["150쪽 본문을 견줘요.","국제기구는 나라들이 모였어요.","비정부 기구는 민간이 중심이에요."],"asset":{"type":"passage","lines":["국제 연합 — 국제 평화와 안전을 지키고자 여러 분야에서 국제 협력","국제 연합 아동 기금 — 어려움을 겪는 어린이에게 의료·식량·교육 제공","국제 연합 난민 기구 — 난민 보호, 생활에 필요한 물품·의료·교육 제공","국경 없는 의사회 — 고통받는 사람들에게 차별 없이 의료 제공","세계 자연 기금 — 생물 다양성 보전, 기후변화에 대응하는 활동","그린피스 — 환경 연구, 해양 생태계 보호 활동"],"title":"150쪽 국제기구와 비정부 기구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_challenge#1','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C10',2,'mc','auto','150쪽에서 그린피스가 하는 일로 소개한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X20']::text[],true,'{"seq":1,"concept":"SO6-2-u3-C10","difficulty":2,"kind":"mc","stem":"150쪽에서 그린피스가 하는 일로 소개한 것은 어느 것인가요?","options":[{"t":"환경을 연구하고 해양 생태계를 보호하는 활동","correct":true},{"t":"전쟁 지역 어린이에게 교육을 제공하는 일","mis":"SO6-2-u3-X20"},{"t":"국제 평화와 안전을 위해 나라들이 협력하는 일","mis":"SO6-2-u3-X20"},{"t":"고통받는 사람들에게 차별 없이 의료를 제공하는 일","mis":"SO6-2-u3-X20"}],"explanation":["그린피스는 비정부 기구예요.","환경과 바다를 지켜요.","해양 생태계 보호예요."],"asset":{"type":"passage","lines":["국제 연합 — 국제 평화와 안전을 지키고자 여러 분야에서 국제 협력","국제 연합 아동 기금 — 어려움을 겪는 어린이에게 의료·식량·교육 제공","국제 연합 난민 기구 — 난민 보호, 생활에 필요한 물품·의료·교육 제공","국경 없는 의사회 — 고통받는 사람들에게 차별 없이 의료 제공","세계 자연 기금 — 생물 다양성 보전, 기후변화에 대응하는 활동","그린피스 — 환경 연구, 해양 생태계 보호 활동"],"title":"150쪽 국제기구와 비정부 기구"},"variant_rule":{"alt":[{"stem":"150쪽에서 국경 없는 의사회가 하는 일로 소개한 것은 어느 것인가요?","options":[{"t":"전쟁이나 질병, 자연재해 등으로 고통받는 사람들에게 차별 없이 의료를 제공하는 일","correct":true},{"t":"생물 다양성을 보전하는 일","mis":"SO6-2-u3-X20"},{"t":"해양 생태계를 보호하는 일","mis":"SO6-2-u3-X20"},{"t":"국제 평화와 안전을 지키는 일","mis":"SO6-2-u3-X20"}],"explanation":["이름에 「의사」가 있어요.","아픈 사람을 치료해요.","차별 없이 의료를 제공해요."],"asset":{"type":"passage","lines":["국제 연합 — 국제 평화와 안전을 지키고자 여러 분야에서 국제 협력","국제 연합 아동 기금 — 어려움을 겪는 어린이에게 의료·식량·교육 제공","국제 연합 난민 기구 — 난민 보호, 생활에 필요한 물품·의료·교육 제공","국경 없는 의사회 — 고통받는 사람들에게 차별 없이 의료 제공","세계 자연 기금 — 생물 다양성 보전, 기후변화에 대응하는 활동","그린피스 — 환경 연구, 해양 생태계 보호 활동"],"title":"150쪽 국제기구와 비정부 기구"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_challenge#2','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C9',2,'ox','auto','지구에 사는 다양한 동식물과 함께 살아가려면 인간에게 필요한 것을 가장 먼저 생각해야 해요.',ARRAY['SO6-2-u3-X18']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"ox","stem":"지구에 사는 다양한 동식물과 함께 살아가려면 인간에게 필요한 것을 가장 먼저 생각해야 해요.","answer":"X","reason_options":[{"t":"인간 위주로 생각하는 태도를 버리고 지구촌에 사는 모두를 생각하는 자세가 필요하기 때문에","correct":true},{"t":"지구는 사람만을 위한 곳이기 때문에","mis":"SO6-2-u3-X18"}],"mis":"SO6-2-u3-X18","explanation":["동식물이 사라지는 까닭을 떠올려요.","인간 위주의 개발 때문이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_challenge#3','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C9',3,'error','auto','지속가능한 미래를 위한 노력과 주체를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X19']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"error","stem":"지속가능한 미래를 위한 노력과 주체를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세아 — 「난민 보호 시설을 마련하는 것은 개인의 노력이야.」","correct":true,"mis_target":"SO6-2-u3-X19"},{"t":"준서 — 「친환경 소재로 제품을 만드는 것은 기업의 노력이야.」","mis":"SO6-2-u3-X19"},{"t":"다은 — 「안 쓰는 전등을 끄는 것은 개인의 노력이야.」","mis":"SO6-2-u3-X19"}],"explanation":["난민 보호 시설은 누가 마련할까요?","법·제도·시설은 국가가 맡아요.","세아가 주체를 바꾸어 말했어요."],"asset":{"type":"passage","lines":["기업 ① 라벨을 없애고 플라스틱 뚜껑의 크기를 줄인 생수병","기업 ② 플라스틱을 재활용해 만든 운동화","국가 ③ 기후변화 협약에 가입하고 탄소 배출을 줄이려는 목표를 세운다.","국가 ④ 난민 보호 시설을 마련하고 난민이 사회에 적응하도록 돕는다."],"title":"149쪽 기업과 국가의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_challenge#4','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C10',3,'mc','auto','「미얀마에서 박해를 피해 방글라데시로 이주한 약 100만 명의 로힝야족 난민을 위해 정착촌을 마련했다.」 150쪽에서 이 일을 한 곳은 어디인가요?',ARRAY['SO6-2-u3-X20']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C10","difficulty":3,"kind":"mc","stem":"「미얀마에서 박해를 피해 방글라데시로 이주한 약 100만 명의 로힝야족 난민을 위해 정착촌을 마련했다.」 150쪽에서 이 일을 한 곳은 어디인가요?","options":[{"t":"국제 연합 난민 기구","correct":true},{"t":"국제 연합 아동 기금","mis":"SO6-2-u3-X20"},{"t":"세계 자연 기금","mis":"SO6-2-u3-X20"},{"t":"그린피스","mis":"SO6-2-u3-X20"}],"explanation":["난민을 위한 일이에요.","정착촌을 마련했어요.","국제 연합 난민 기구예요."],"asset":{"type":"passage","lines":["국제 연합 — 국제 평화와 안전을 지키고자 여러 분야에서 국제 협력","국제 연합 아동 기금 — 어려움을 겪는 어린이에게 의료·식량·교육 제공","국제 연합 난민 기구 — 난민 보호, 생활에 필요한 물품·의료·교육 제공","국경 없는 의사회 — 고통받는 사람들에게 차별 없이 의료 제공","세계 자연 기금 — 생물 다양성 보전, 기후변화에 대응하는 활동","그린피스 — 환경 연구, 해양 생태계 보호 활동"],"title":"150쪽 국제기구와 비정부 기구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_challenge#5','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C10',3,'match','auto','150쪽 비정부 기구와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u3-C10","difficulty":3,"kind":"match","stem":"150쪽 비정부 기구와 하는 일을 알맞게 이으세요.","pairs":[{"l":"국경 없는 의사회","r":"고통받는 사람들에게 차별 없이 의료 제공"},{"l":"세계 자연 기금","r":"생물 다양성 보전, 기후변화 대응"},{"l":"그린피스","r":"환경 연구, 해양 생태계 보호"}],"mis":"SO6-2-u3-X20","explanation":["기구 이름을 떠올려요.","의사회는 의료, 자연 기금은 생물 다양성이에요.","그린피스는 바다를 지켜요."],"asset":{"type":"passage","lines":["국제 연합 — 국제 평화와 안전을 지키고자 여러 분야에서 국제 협력","국제 연합 아동 기금 — 어려움을 겪는 어린이에게 의료·식량·교육 제공","국제 연합 난민 기구 — 난민 보호, 생활에 필요한 물품·의료·교육 제공","국경 없는 의사회 — 고통받는 사람들에게 차별 없이 의료 제공","세계 자연 기금 — 생물 다양성 보전, 기후변화에 대응하는 활동","그린피스 — 환경 연구, 해양 생태계 보호 활동"],"title":"150쪽 국제기구와 비정부 기구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_challenge#6','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C9',3,'mc','auto','148쪽 세계 물의 날 캠페인(하루 세 번 양치컵 이용, 두 번 세숫대야 사용, 샤워 시간 2분 줄이기)과 같은 갈래의 개인 노력은 어느 것인가요?',ARRAY['SO6-2-u3-X19']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"mc","stem":"148쪽 세계 물의 날 캠페인(하루 세 번 양치컵 이용, 두 번 세숫대야 사용, 샤워 시간 2분 줄이기)과 같은 갈래의 개인 노력은 어느 것인가요?","options":[{"t":"안 쓰는 전등을 꺼 에너지를 아낀다","correct":true},{"t":"플라스틱을 재활용한 운동화를 만든다","mis":"SO6-2-u3-X19"},{"t":"기후변화 협약에 가입한다","mis":"SO6-2-u3-X19"},{"t":"난민 보호 시설을 마련한다","mis":"SO6-2-u3-X19"}],"explanation":["물 절약은 자원을 아끼는 일이에요.","전등 끄기는 에너지를 아끼는 일이에요.","둘 다 개인의 생활 속 노력이에요."],"asset":{"type":"passage","lines":["① 쓰레기를 분리배출하고 재활용한다.","② 녹색 제품을 소비하고 일회용품 사용을 줄인다.","③ 물 적게 쓰기, 안 쓰는 전등 끄기 등으로 자원과 에너지를 아낀다.","④ 동식물이 살아가는 곳을 함부로 훼손하지 않고 보존한다."],"numbered":false,"title":"148쪽 개인의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_challenge#7','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C9',3,'mc','auto','148쪽 사진처럼 바닷가 모래밭에 「쇠제비갈매기 서식지 보호를 위해 사륜 바이크 이용을 자제해 달라」는 팻말을 세웠어요. 이것은 어떤 노력과 관계있나요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X18']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"mc","stem":"148쪽 사진처럼 바닷가 모래밭에 「쇠제비갈매기 서식지 보호를 위해 사륜 바이크 이용을 자제해 달라」는 팻말을 세웠어요. 이것은 어떤 노력과 관계있나요?","options":[{"t":"동식물이 살아가는 곳을 함부로 훼손하지 않고 보존하는 노력","correct":true},{"t":"녹색 제품을 소비하는 노력","mis":"SO6-2-u3-X19"},{"t":"난민을 보호하는 노력","mis":"SO6-2-u3-X19"},{"t":"자원을 많이 개발하는 노력","mis":"SO6-2-u3-X18"}],"explanation":["팻말이 지키려는 것을 봐요.","새가 사는 곳이에요.","서식지를 보존하는 노력이에요."],"asset":{"type":"passage","lines":["① 쓰레기를 분리배출하고 재활용한다.","② 녹색 제품을 소비하고 일회용품 사용을 줄인다.","③ 물 적게 쓰기, 안 쓰는 전등 끄기 등으로 자원과 에너지를 아낀다.","④ 동식물이 살아가는 곳을 함부로 훼손하지 않고 보존한다."],"numbered":false,"title":"148쪽 개인의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_challenge#8','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C10',4,'essay','teacher','과정 중심 평가처럼 지구촌 문제를 풀려고 노력하는 비정부 기구를 계획해 보세요. 이름, 목적, 만든 까닭(세 문장 이상), 주된 활동(세 가지 이상)을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u3-C10","difficulty":4,"kind":"essay","stem":"과정 중심 평가처럼 지구촌 문제를 풀려고 노력하는 비정부 기구를 계획해 보세요. 이름, 목적, 만든 까닭(세 문장 이상), 주된 활동(세 가지 이상)을 쓰세요.","answer_guide":{"answer":"예: 이름 — 작은 실천 지구 지킴이 기구. 목적 — 생활 속에서 에너지 절약, 쓰레기 줄이기, 주변 생태계 깨끗하게 하기를 실천해 지구의 지속가능성을 높인다. 만든 까닭 — 지구를 지키는 일은 생활 속 작은 일부터 시작된다. 지금 지구는 에너지 문제, 쓰레기 문제, 기후변화로 고통받고 있다. 미래의 다음 세대도 지구에서 행복하게 살아야 한다. 주된 활동 — 생활 속 실천 릴레이, 우리 지역 하천 쓰레기 줍기 캠페인, 안 쓰는 전등 끄기 알리기.","scoring_points":["기구의 이름과 목적이 서로 이어지는가","만든 까닭을 세 문장 이상 썼는가","주된 활동을 세 가지 이상 구체적으로 썼는가"]},"explanation":["비정부 기구는 민간이 만들어요.","목적과 까닭을 이어 써요.","실천할 활동을 셋 이상 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_challenge#9','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C10',4,'mc','auto','151쪽 조사 예시 「그린피스는 바다에서 불법 어업 활동을 하거나 해양 생물을 무분별하게 잡아들이지 않도록 각 나라와 소통하며 의견을 제시하고 있다.」에서 지구촌 문제와 노력 주체를 알맞게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X20','SO6-2-u3-X19']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C10","difficulty":4,"kind":"mc","stem":"151쪽 조사 예시 「그린피스는 바다에서 불법 어업 활동을 하거나 해양 생물을 무분별하게 잡아들이지 않도록 각 나라와 소통하며 의견을 제시하고 있다.」에서 지구촌 문제와 노력 주체를 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"생태계 파괴 — 비정부 기구","correct":true},{"t":"난민 — 국제기구","mis":"SO6-2-u3-X20"},{"t":"기후변화 — 국가","mis":"SO6-2-u3-X19"},{"t":"자원과 에너지 고갈 — 개인","mis":"SO6-2-u3-X19"}],"explanation":["바다 생물을 지키는 일이에요.","그린피스는 민간이 만든 단체예요.","생태계 파괴 — 비정부 기구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L07_challenge#10','soc',6,2,'u3','L07','tb_g6_2_soc_u3_L07_challenge','lesson_challenge','SO6-2-u3-C9',4,'essay','teacher','149쪽 친구와 활동처럼 개인, 기업, 국가가 함께 참여하기를 바라는 문장을 만들고, 세 주체가 함께 노력해야 하는 까닭과 각 주체의 노력을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C9","difficulty":4,"kind":"essay","stem":"149쪽 친구와 활동처럼 개인, 기업, 국가가 함께 참여하기를 바라는 문장을 만들고, 세 주체가 함께 노력해야 하는 까닭과 각 주체의 노력을 하나씩 쓰세요.","answer_guide":{"answer":"예: 문장 — 지구촌을 위해 하나 된 우리, 함께 만들어 가는 미래. 지구촌 문제는 혼자만의 노력으로 풀 수 없어 모두가 힘을 모아야 한다. 개인은 쓰레기를 분리배출하고, 기업은 자원을 적게 사용한 제품을 만들며, 국가는 기후변화 협약에 가입해 탄소 배출을 줄이려는 목표를 세운다.","scoring_points":["함께 참여하기를 바라는 문장을 만들었는가","함께 노력해야 하는 까닭을 썼는가","세 주체의 노력을 알맞게 하나씩 썼는가"]},"explanation":["세 주체를 모두 떠올려요.","혼자만으로는 어려워요.","주체마다 알맞은 노력을 짝지어요."],"asset":{"type":"passage","lines":["기업 ① 라벨을 없애고 플라스틱 뚜껑의 크기를 줄인 생수병","기업 ② 플라스틱을 재활용해 만든 운동화","국가 ③ 기후변화 협약에 가입하고 탄소 배출을 줄이려는 목표를 세운다.","국가 ④ 난민 보호 시설을 마련하고 난민이 사회에 적응하도록 돕는다."],"title":"149쪽 기업과 국가의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_basic#1','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',1,'sa','auto','꼭 기억해요 — 지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"sa","stem":"꼭 기억해요 — 지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["세계시민","세계 시민"],"explanation":["152쪽 본문이에요.","지구촌이라는 공동체의 시민이에요.","세계시민이에요."],"mis":"SO6-2-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_basic#2','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',1,'mc','auto','152쪽에서 「더하기(+) 노력(더 자주 해야 할 것)」의 예로 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X18']::text[],true,'{"seq":2,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"mc","stem":"152쪽에서 「더하기(+) 노력(더 자주 해야 할 것)」의 예로 든 것은 어느 것인가요?","options":[{"t":"시장바구니 사용하기","correct":true},{"t":"플라스틱 덜 사용하기","mis":"SO6-2-u3-X21"},{"t":"안 쓰는 전등 끄기","mis":"SO6-2-u3-X21"},{"t":"일회용품 더 많이 쓰기","mis":"SO6-2-u3-X18"}],"explanation":["더 자주 해야 할 일을 찾아요.","나머지 둘은 줄이는 빼기 노력이에요.","시장바구니 사용하기예요."],"variant_rule":{"alt":[{"stem":"152쪽에서 「빼기(−) 노력(줄이거나 없애야 할 것)」의 예로 든 것은 어느 것인가요?","options":[{"t":"안 쓰는 전등 끄기","correct":true},{"t":"시장바구니 사용하기","mis":"SO6-2-u3-X21"},{"t":"다회용품 사용하기","mis":"SO6-2-u3-X21"},{"t":"일회용 컵 더 자주 쓰기","mis":"SO6-2-u3-X21"}],"explanation":["줄이거나 없애야 할 일을 찾아요.","쓰지 않는 전기를 줄여요.","안 쓰는 전등 끄기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_basic#3','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',1,'ox','auto','세계시민은 지구촌 문제가 우리 모두의 문제라는 생각을 가져요.',ARRAY['SO6-2-u3-X16']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"ox","stem":"세계시민은 지구촌 문제가 우리 모두의 문제라는 생각을 가져요.","answer":"O","reason_options":[{"t":"지구촌 문제는 나라를 가리지 않고 서로에게 영향을 주므로 함께 풀어야 하기 때문에","correct":true},{"t":"지구촌 문제는 문제가 생긴 나라 사람들만의 일이기 때문에","mis":"SO6-2-u3-X16"}],"mis":"SO6-2-u3-X16","explanation":["152쪽 본문이에요.","세계시민의 태도예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_basic#4','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',1,'ox','auto','153쪽 실천 인증 릴레이에서는 인증 사진과 함께 실천한 내용을 구체적으로 기록해요.',ARRAY['SO6-2-u3-X27']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"ox","stem":"153쪽 실천 인증 릴레이에서는 인증 사진과 함께 실천한 내용을 구체적으로 기록해요.","answer":"O","reason_options":[{"t":"무엇을 언제 어떻게 실천했는지 남겨야 서로 확인하고 이어 갈 수 있기 때문에","correct":true},{"t":"사진만 올리면 실천이 끝나기 때문에","mis":"SO6-2-u3-X27"}],"mis":"SO6-2-u3-X27","explanation":["릴레이 ②를 읽어요.","사진과 함께 기록해요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 실천하는 모습을 담아 인증 사진을 찍는다.","② 인증 사진과 함께 실천한 내용을 구체적으로 기록한다.","③ 다음 차례인 친구에게 알린다.","④ 다음 사람은 ①~③과 같은 방식으로 실천 활동에 참여한다."],"numbered":false,"title":"153쪽 실천 인증 릴레이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_basic#5','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',2,'mc','auto','155쪽 재미있게 확인해요의 「지구촌 문제는 관련 있는 나라들만의 노력으로 해결해야 합니다.」가 옳지 않은 까닭은 무엇인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X21']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"155쪽 재미있게 확인해요의 「지구촌 문제는 관련 있는 나라들만의 노력으로 해결해야 합니다.」가 옳지 않은 까닭은 무엇인가요?","options":[{"t":"지구촌 문제는 우리 모두의 문제라 세계 여러 나라가 협력해야 하기 때문에","correct":true},{"t":"지구촌 문제는 한 나라가 혼자 풀 수 있기 때문에","mis":"SO6-2-u3-X16"},{"t":"관련 없는 나라가 나서면 문제가 커지기 때문에","mis":"SO6-2-u3-X16"},{"t":"지구촌 문제는 저절로 풀리기 때문에","mis":"SO6-2-u3-X21"}],"explanation":["152쪽 첫 문장을 떠올려요.","여러 나라가 협력해야 해요.","모두의 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_basic#6','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',2,'mc','auto','실천할 일을 정할 때 고려해야 할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X27']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"실천할 일을 정할 때 고려해야 할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"일상생활에서 실천할 수 있는지, 지구촌 문제를 푸는 데 얼마나 효과가 있는지","correct":true},{"t":"가장 어렵고 돈이 많이 드는 일인지","mis":"SO6-2-u3-X21"},{"t":"한 번만 하면 되는 일인지","mis":"SO6-2-u3-X27"},{"t":"다른 사람만 하면 되는 일인지","mis":"SO6-2-u3-X21"}],"explanation":["직접 실천해야 하는 활동이에요.","실천할 수 있어야 해요.","효과도 살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_basic#7','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',2,'mc','auto','153쪽 계획에서 실천 기간과 실천 횟수를 정하라고 한 까닭은 무엇인가요?',ARRAY['SO6-2-u3-X27','SO6-2-u3-X21']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"153쪽 계획에서 실천 기간과 실천 횟수를 정하라고 한 까닭은 무엇인가요?","options":[{"t":"한 번의 실천으로 끝나지 않고 꾸준히 이어 가도록 하려고","correct":true},{"t":"한 번 인증하면 실천이 끝나기 때문에","mis":"SO6-2-u3-X27"},{"t":"기간이 짧을수록 효과가 크기 때문에","mis":"SO6-2-u3-X27"},{"t":"친구보다 먼저 끝내려고","mis":"SO6-2-u3-X21"}],"explanation":["153쪽 말풍선을 읽어요.","한 번으로 끝나지 않게 해요.","꾸준히 이어 가려는 거예요."],"asset":{"type":"passage","lines":["실천 기간 — ○○월 ○○일~○○월 ○○일 · 실천 횟수 — 1명당 3일간","실천 장소 — 집, 학교, 마을 등","인증 방법 — 실천하는 모습을 사진 또는 동영상으로 촬영하여 올리기","인증 순서 — 김○○ - 양○○ - 최○○ - 허○○","실천 계획 — 양치질이나 세수할 때 물을 잠그거나 받아서 쓰는 모습 촬영"],"title":"153쪽 실천 인증 릴레이 계획 예"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_basic#8','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',2,'mc','auto','154쪽 에코 제품 디자이너가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X18','SO6-2-u3-X23']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"154쪽 에코 제품 디자이너가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"자연에서 얻은 재료나 버려진 물건을 활용해 자연과 사람에게 해가 되지 않는 제품을 디자인한다","correct":true},{"t":"버리는 과정은 생각하지 않고 예쁜 제품만 디자인한다","mis":"SO6-2-u3-X18"},{"t":"플라스틱을 더 많이 쓰는 제품을 디자인한다","mis":"SO6-2-u3-X18"},{"t":"나라별 인구수를 조사한다","mis":"SO6-2-u3-X23"}],"explanation":["직업 소개를 읽어요.","재료와 버리는 과정까지 생각해요.","환경을 생각하는 디자인이에요."],"asset":{"type":"passage","lines":["자연에서 얻은 재료나 버려진 물건을 활용해","자연과 사람에게 해가 되지 않는 제품을 만들거나 디자인한다.","제품의 재료뿐만 아니라 다 사용한 후 버리는 과정까지 생각한다.","예 — 버려진 가구를 새로 디자인한 가구 · 다 쓴 페트병으로 만든 옷"],"title":"154쪽 별별 직업 속으로 — 에코 제품 디자이너"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_basic#9','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',2,'mc','auto','모둠에서 실천할 지구촌 문제를 정할 때 주의할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"모둠에서 실천할 지구촌 문제를 정할 때 주의할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"서로 관심 있는 주제가 다를 수 있음을 이해하고 서로의 의견을 존중한다","correct":true},{"t":"목소리가 큰 친구의 주제로 정한다","mis":"SO6-2-u3-X21"},{"t":"관심이 다른 친구의 주제는 듣지 않는다","mis":"SO6-2-u3-X21"},{"t":"주제는 정하지 않고 아무 일이나 한다","mis":"SO6-2-u3-X21"}],"explanation":["152쪽 활동 ①을 떠올려요.","내 주제와 모둠 주제가 다를 수 있어요.","서로의 의견을 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_basic#10','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_basic','lesson_basic','SO6-2-u3-C11',3,'mc','auto','활동지 평가표에서 세 기준 점수의 합계가 가장 높은 실천 방법은 무엇인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"mc","stem":"활동지 평가표에서 세 기준 점수의 합계가 가장 높은 실천 방법은 무엇인가요?","options":[{"t":"① 안 쓰는 전등 끄기(14점)","correct":true},{"t":"② 안 쓰는 가전제품의 플러그 뽑기(11점)","mis":"SO6-2-u3-X21"},{"t":"③ 급식에서 음식을 먹을 만큼만 받고 남기지 않기(12점)","mis":"SO6-2-u3-X21"},{"t":"세 방법의 합계가 모두 같다","mis":"SO6-2-u3-X21"}],"explanation":["방법마다 세 점수를 더해요.","①은 5+4+5=14, ②는 11, ③은 12예요.","합계가 가장 높은 것은 ①이에요."],"asset":{"type":"passage","lines":["① 안 쓰는 전등 끄기 · ② 안 쓰는 가전제품의 플러그 뽑기","③ 급식에서 음식을 먹을 만큼만 받고 남기지 않기","기준 ㉠ 누구나 실천할 수 있는 일인가? — ① 5 · ② 4 · ③ 4","기준 ㉡ 집이나 학교에서 자주 접하는 일인가? — ① 4 · ② 3 · ③ 4","기준 ㉢ 지구촌 문제 해결에 얼마나 도움이 되는가? — ① 5 · ② 4 · ③ 4"],"numbered":false,"title":"활동지 — 실천 방법 평가표(각 1~5점)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_challenge#1','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',2,'mc','auto','사람들이 친환경 소재의 물품을 구입하자 기업의 제품 생산 방식이 변했어요. 이것으로 알 수 있는 개인 노력의 의미는 무엇인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X19','SO6-2-u3-X27']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"사람들이 친환경 소재의 물품을 구입하자 기업의 제품 생산 방식이 변했어요. 이것으로 알 수 있는 개인 노력의 의미는 무엇인가요?","options":[{"t":"개인의 노력이 기업과 사회의 변화를 만들 수 있다","correct":true},{"t":"나 하나의 노력으로는 아무것도 바뀌지 않는다","mis":"SO6-2-u3-X21"},{"t":"기업만 노력하면 개인은 하지 않아도 된다","mis":"SO6-2-u3-X19"},{"t":"개인의 노력은 한 번이면 충분하다","mis":"SO6-2-u3-X27"}],"explanation":["개인이 물건을 고르는 방식이 바뀌었어요.","그러자 기업이 바뀌었어요.","작은 노력이 변화를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_challenge#2','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',2,'sa','auto','「플라스틱 덜 사용하기」는 더하기(+) 노력과 빼기(−) 노력 가운데 어느 것인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"sa","stem":"「플라스틱 덜 사용하기」는 더하기(+) 노력과 빼기(−) 노력 가운데 어느 것인가요? 두 글자로 쓰세요.","answer":["빼기"],"explanation":["줄이는 일인지 늘리는 일인지 봐요.","플라스틱을 덜 써요.","빼기 노력이에요."],"mis":"SO6-2-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_challenge#3','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',3,'error','auto','실천 인증 릴레이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X27','SO6-2-u3-X21']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"error","stem":"실천 인증 릴레이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「인증 사진을 한 번 올렸으니 이제 실천은 끝난 거야.」","correct":true,"mis_target":"SO6-2-u3-X27"},{"t":"가은 — 「사진과 함께 실천한 내용을 구체적으로 기록하자.」","mis":"SO6-2-u3-X27"},{"t":"시우 — 「다음 차례인 친구에게 꼭 알려 주자.」","mis":"SO6-2-u3-X21"}],"explanation":["기간과 횟수를 정해 실천해요.","한 번으로 끝나지 않게 해요.","윤호가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 실천하는 모습을 담아 인증 사진을 찍는다.","② 인증 사진과 함께 실천한 내용을 구체적으로 기록한다.","③ 다음 차례인 친구에게 알린다.","④ 다음 사람은 ①~③과 같은 방식으로 실천 활동에 참여한다."],"numbered":false,"title":"153쪽 실천 인증 릴레이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_challenge#4','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',3,'mc','auto','「세계시민으로서 우리의 노력은 나비의 날갯짓과 같다.」라는 문장에 담긴 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X27']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"mc","stem":"「세계시민으로서 우리의 노력은 나비의 날갯짓과 같다.」라는 문장에 담긴 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리의 작은 실천이 사회에 큰 변화를 가져올 수 있다","correct":true},{"t":"우리의 노력은 너무 작아 소용없다","mis":"SO6-2-u3-X21"},{"t":"나비처럼 한 번 날고 나면 끝이다","mis":"SO6-2-u3-X27"},{"t":"나비를 보호하는 일만 하면 된다","mis":"SO6-2-u3-X21"}],"explanation":["나비의 작은 날갯짓을 떠올려요.","작은 움직임이 큰 바람이 돼요.","작은 실천이 큰 변화를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_challenge#5','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',3,'mc','auto','153쪽 실천 인증 릴레이의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X27','SO6-2-u3-X21']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"mc","stem":"153쪽 실천 인증 릴레이의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"인증 사진 찍기 → 실천 내용 구체적으로 기록하기 → 다음 친구에게 알리기 → 다음 친구도 같은 방식으로 참여하기","correct":true},{"t":"다음 친구에게 알리기 → 인증 사진 찍기 → 기록하기 → 끝내기","mis":"SO6-2-u3-X27"},{"t":"기록하기 → 다음 친구에게 알리기 → 인증 사진 찍기 → 끝내기","mis":"SO6-2-u3-X21"},{"t":"인증 사진 찍기 → 끝내기","mis":"SO6-2-u3-X27"}],"explanation":["①부터 차례로 봐요.","사진, 기록, 알리기 순서예요.","다음 친구가 이어 가요."],"asset":{"type":"passage","lines":["① 실천하는 모습을 담아 인증 사진을 찍는다.","② 인증 사진과 함께 실천한 내용을 구체적으로 기록한다.","③ 다음 차례인 친구에게 알린다.","④ 다음 사람은 ①~③과 같은 방식으로 실천 활동에 참여한다."],"numbered":false,"title":"153쪽 실천 인증 릴레이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_challenge#6','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',3,'mc','auto','「급식 시간에 먹을 만큼만 음식을 받아 음식물 쓰레기 줄이기를 친구들과 함께 실천하고 싶다.」 이 실천은 어떤 갈래의 노력에 가까운가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X19']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"mc","stem":"「급식 시간에 먹을 만큼만 음식을 받아 음식물 쓰레기 줄이기를 친구들과 함께 실천하고 싶다.」 이 실천은 어떤 갈래의 노력에 가까운가요?","options":[{"t":"학급 전체가 함께 할 수 있는 일","correct":true},{"t":"나 혼자만 할 수 있는 일","mis":"SO6-2-u3-X21"},{"t":"국가만 할 수 있는 일","mis":"SO6-2-u3-X19"},{"t":"기업만 할 수 있는 일","mis":"SO6-2-u3-X19"}],"explanation":["152쪽 말풍선을 떠올려요.","친구들과 함께하는 실천이에요.","학급 전체가 할 수 있는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_challenge#7','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',3,'mc','auto','모둠에서 실천 방법을 평가할 기준으로 가장 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"mc","stem":"모둠에서 실천 방법을 평가할 기준으로 가장 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구들에게 가장 멋있어 보이는 일인가?","correct":true},{"t":"누구나 실천할 수 있는 일인가?","mis":"SO6-2-u3-X21"},{"t":"집이나 학교에서 자주 접하는 일인가?","mis":"SO6-2-u3-X21"},{"t":"지구촌 문제 해결에 얼마나 도움이 되는가?","mis":"SO6-2-u3-X21"}],"explanation":["활동지 평가표의 기준을 봐요.","실천 가능성과 효과를 따져요.","멋있어 보이는지는 기준이 아니에요."],"asset":{"type":"passage","lines":["① 안 쓰는 전등 끄기 · ② 안 쓰는 가전제품의 플러그 뽑기","③ 급식에서 음식을 먹을 만큼만 받고 남기지 않기","기준 ㉠ 누구나 실천할 수 있는 일인가? — ① 5 · ② 4 · ③ 4","기준 ㉡ 집이나 학교에서 자주 접하는 일인가? — ① 4 · ② 3 · ③ 4","기준 ㉢ 지구촌 문제 해결에 얼마나 도움이 되는가? — ① 5 · ② 4 · ③ 4"],"numbered":false,"title":"활동지 — 실천 방법 평가표(각 1~5점)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_challenge#8','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',4,'essay','teacher','나의 실천 인증 릴레이 계획을 세우세요. 지구촌 문제 하나를 고르고, 더하기(+) 노력과 빼기(−) 노력을 하나씩 정한 뒤 실천 기간·횟수·장소와 인증 방법을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u3-C11","difficulty":4,"kind":"essay","stem":"나의 실천 인증 릴레이 계획을 세우세요. 지구촌 문제 하나를 고르고, 더하기(+) 노력과 빼기(−) 노력을 하나씩 정한 뒤 실천 기간·횟수·장소와 인증 방법을 쓰세요.","answer_guide":{"answer":"예: 고른 문제 — 기후변화. 더하기 노력 — 다회용 컵 사용하기, 빼기 노력 — 안 쓰는 전등 끄기. 실천 기간과 횟수 — 일주일 동안 날마다, 장소 — 집과 학교. 인증 방법 — 실천하는 모습을 사진으로 찍고 언제 어디서 무엇을 했는지 기록해 다음 친구에게 알린다.","scoring_points":["지구촌 문제와 더하기·빼기 노력을 알맞게 정했는가","기간·횟수·장소를 구체적으로 정했는가","인증하고 이어 가는 방법을 썼는가"]},"explanation":["문제를 먼저 골라요.","더 할 일과 줄일 일을 나눠요.","한 번으로 끝나지 않게 계획해요."],"asset":{"type":"passage","lines":["실천 기간 — ○○월 ○○일~○○월 ○○일 · 실천 횟수 — 1명당 3일간","실천 장소 — 집, 학교, 마을 등","인증 방법 — 실천하는 모습을 사진 또는 동영상으로 촬영하여 올리기","인증 순서 — 김○○ - 양○○ - 최○○ - 허○○","실천 계획 — 양치질이나 세수할 때 물을 잠그거나 받아서 쓰는 모습 촬영"],"title":"153쪽 실천 인증 릴레이 계획 예"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_challenge#9','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',4,'mc','auto','활동지 평가표로 모둠의 실천 방법을 정했어요. 가장 알맞게 판단한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X27']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C11","difficulty":4,"kind":"mc","stem":"활동지 평가표로 모둠의 실천 방법을 정했어요. 가장 알맞게 판단한 것은 어느 것인가요?","options":[{"t":"합계가 가장 높은 ① 안 쓰는 전등 끄기를 모둠의 실천 방법으로 정하고, ②·③도 지구에 도움이 되는 일이니 함께 실천해 볼 수 있다","correct":true},{"t":"점수가 낮은 ②와 ③은 지구에 전혀 도움이 안 되니 하지 않는다","mis":"SO6-2-u3-X21"},{"t":"①을 하루만 실천하고 끝낸다","mis":"SO6-2-u3-X27"},{"t":"합계는 보지 않고 아무 기준 하나로만 정한다","mis":"SO6-2-u3-X21"}],"explanation":["합계로 1등을 정해요.","다른 방법도 쓸모없는 것은 아니에요.","꾸준히 함께 실천해요."],"asset":{"type":"passage","lines":["① 안 쓰는 전등 끄기 · ② 안 쓰는 가전제품의 플러그 뽑기","③ 급식에서 음식을 먹을 만큼만 받고 남기지 않기","기준 ㉠ 누구나 실천할 수 있는 일인가? — ① 5 · ② 4 · ③ 4","기준 ㉡ 집이나 학교에서 자주 접하는 일인가? — ① 4 · ② 3 · ③ 4","기준 ㉢ 지구촌 문제 해결에 얼마나 도움이 되는가? — ① 5 · ② 4 · ③ 4"],"numbered":false,"title":"활동지 — 실천 방법 평가표(각 1~5점)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L08_challenge#10','soc',6,2,'u3','L08','tb_g6_2_soc_u3_L08_challenge','lesson_challenge','SO6-2-u3-C11',4,'essay','teacher','「세계시민으로서 우리의 노력은 ○○이다.」를 완성하고 그렇게 쓴 까닭을 쓴 뒤, 그 생각을 내가 정한 실천 하나와 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C11","difficulty":4,"kind":"essay","stem":"「세계시민으로서 우리의 노력은 ○○이다.」를 완성하고 그렇게 쓴 까닭을 쓴 뒤, 그 생각을 내가 정한 실천 하나와 이어 쓰세요.","answer_guide":{"answer":"예: 세계시민으로서 우리의 노력은 흙과 같다. 흙이 모든 생명의 기초가 되듯이 우리의 작은 실천이 지구촌의 지속가능한 미래의 기초가 되기 때문이다. 그래서 나는 안 쓰는 전등 끄기를 날마다 실천해 에너지를 아끼겠다.","scoring_points":["문장을 알맞게 완성했는가","까닭을 세계시민의 뜻과 이어 썼는가","나의 실천과 이어 썼는가"]},"explanation":["세계시민의 뜻을 떠올려요.","비유와 까닭을 이어요.","내가 할 실천으로 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_basic#1','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',1,'sa','auto','「영화나 애니메이션 같은 영상물을 제작하기 위해 필요한 장면을 구성하며 이야기의 흐름을 작성한 것」을 무엇이라고 하나요?','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C12","difficulty":1,"kind":"sa","stem":"「영화나 애니메이션 같은 영상물을 제작하기 위해 필요한 장면을 구성하며 이야기의 흐름을 작성한 것」을 무엇이라고 하나요?","answer":["스토리보드"],"explanation":["장면별로 이야기의 흐름을 적어요.","그림책을 만들기 전에 써요.","스토리보드예요."],"mis":"SO6-2-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_basic#2','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',1,'mc','auto','157쪽 스토리보드에 장면마다 쓰는 칸으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C12","difficulty":1,"kind":"mc","stem":"157쪽 스토리보드에 장면마다 쓰는 칸으로 알맞은 것은 어느 것인가요?","options":[{"t":"그림 순서, 그림, 그림 설명·글·대사","correct":true},{"t":"나라 이름, 인구수, 면적","mis":"SO6-2-u3-X22"},{"t":"제목만","mis":"SO6-2-u3-X22"},{"t":"점수와 합계","mis":"SO6-2-u3-X22"}],"explanation":["157쪽 표의 칸을 봐요.","그림과 그 설명, 글, 대사를 써요.","장면마다 칸을 채워요."],"asset":{"type":"passage","lines":["장면 1 — 다양한 사람들 · 글 「지구촌 곳곳에 많은 사람이 살아가고 있어요.」","장면 2 — 빼곡한 도시 · 글 「어떤 지역은 인구가 많고」","장면 3 — 초원에서 유목하는 사람 · 글 「어떤 지역은 인구가 적어요.」","장면 4 — 병든 지구와 걱정하는 어린이 · 글 「하지만 지구가 아파해요.」","장면 5 — 분리배출하는 모습 · 대사 「우리 모두 분리배출을 실천해요!」","장면 6 — 캠페인 보드를 든 모습 · 대사 「지구야, 우리가 지켜 줄게!」"],"title":"157쪽 스토리보드 예(그림 설명 · 글 · 대사, 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_basic#3','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',1,'ox','auto','그림책 계획을 세울 때에는 독자를 정하고 독자의 수준에 맞는 내용을 구성해야 해요.',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C12","difficulty":1,"kind":"ox","stem":"그림책 계획을 세울 때에는 독자를 정하고 독자의 수준에 맞는 내용을 구성해야 해요.","answer":"O","reason_options":[{"t":"읽을 사람의 수준에 맞아야 내용을 잘 이해할 수 있기 때문에","correct":true},{"t":"독자가 누구든 같은 글이면 되기 때문에","mis":"SO6-2-u3-X22"}],"mis":"SO6-2-u3-X22","explanation":["계획서에 「대상」 칸이 있어요.","8~9세 어린이처럼 독자를 정해요.","그래서 O예요."],"asset":{"type":"passage","lines":["그림책 제목 — 지구와 함께 살아가는 우리","주제 — 지구촌 사람들과 함께하는 지속가능한 미래를 위한 노력","대상 — 8~9세 어린이","줄거리 — 지구촌에는 많은 사람이 살아가고 있다.","　지구촌을 위협하는 여러 가지 문제를 해결하고","　지구를 지키려고 많은 사람이 캠페인을 벌인다."],"numbered":false,"title":"156쪽 그림책 계획서 예"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_basic#4','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',1,'mc','auto','156쪽 「이렇게 해 봐요」에서 가장 먼저 할 일은 무엇인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C12","difficulty":1,"kind":"mc","stem":"156쪽 「이렇게 해 봐요」에서 가장 먼저 할 일은 무엇인가요?","options":[{"t":"이 단원에서 공부한 내용과 관련하여 주제를 정한다","correct":true},{"t":"그림책 발표회를 연다","mis":"SO6-2-u3-X22"},{"t":"스토리보드를 바로 그린다","mis":"SO6-2-u3-X22"},{"t":"역할을 나눈다","mis":"SO6-2-u3-X22"}],"explanation":["차례 1을 읽어요.","무엇에 대한 그림책인지부터 정해요.","주제를 정해요."],"asset":{"type":"passage","lines":["1 이 단원에서 공부한 내용과 관련하여 주제를 정한다.","2 그림책에 담을 내용을 친구들과 이야기하고 줄거리를 만든다.","3 각자 완성할 부분을 나누어 역할을 정하고 스토리보드를 만든다.","4 그림책 발표회를 열어 다른 모둠의 친구들과 공유한다."],"numbered":false,"title":"156쪽 생각을 펼쳐요 — 이렇게 해 봐요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_basic#5','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',2,'mc','auto','157쪽 장면 2와 장면 3이 담은 단원 내용은 무엇인가요?',ARRAY['SO6-2-u3-X22']::text[],true,'{"seq":5,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"mc","stem":"157쪽 장면 2와 장면 3이 담은 단원 내용은 무엇인가요?","options":[{"t":"세계의 인구 분포 — 인구가 많은 지역과 적은 지역이 있다","correct":true},{"t":"지구촌을 위협하는 문제","mis":"SO6-2-u3-X22"},{"t":"비정부 기구의 활동","mis":"SO6-2-u3-X22"},{"t":"실천 인증 릴레이","mis":"SO6-2-u3-X22"}],"explanation":["빼곡한 도시와 유목하는 초원이에요.","많은 곳과 적은 곳을 견줬어요.","세계의 인구 분포예요."],"asset":{"type":"passage","lines":["장면 1 — 다양한 사람들 · 글 「지구촌 곳곳에 많은 사람이 살아가고 있어요.」","장면 2 — 빼곡한 도시 · 글 「어떤 지역은 인구가 많고」","장면 3 — 초원에서 유목하는 사람 · 글 「어떤 지역은 인구가 적어요.」","장면 4 — 병든 지구와 걱정하는 어린이 · 글 「하지만 지구가 아파해요.」","장면 5 — 분리배출하는 모습 · 대사 「우리 모두 분리배출을 실천해요!」","장면 6 — 캠페인 보드를 든 모습 · 대사 「지구야, 우리가 지켜 줄게!」"],"title":"157쪽 스토리보드 예(그림 설명 · 글 · 대사, 줄임)"},"variant_rule":{"alt":[{"stem":"157쪽 장면 4~6이 담은 단원 내용은 무엇인가요?","options":[{"t":"지구촌의 문제와 지속가능한 미래를 위한 실천","correct":true},{"t":"세계의 인구 분포","mis":"SO6-2-u3-X22"},{"t":"인구 피라미드 읽기","mis":"SO6-2-u3-X22"},{"t":"나라별 인구수","mis":"SO6-2-u3-X22"}],"explanation":["병든 지구, 분리배출, 캠페인이 나와요.","문제와 실천을 담았어요.","지구촌의 문제와 지속가능한 미래예요."],"asset":{"type":"passage","lines":["장면 1 — 다양한 사람들 · 글 「지구촌 곳곳에 많은 사람이 살아가고 있어요.」","장면 2 — 빼곡한 도시 · 글 「어떤 지역은 인구가 많고」","장면 3 — 초원에서 유목하는 사람 · 글 「어떤 지역은 인구가 적어요.」","장면 4 — 병든 지구와 걱정하는 어린이 · 글 「하지만 지구가 아파해요.」","장면 5 — 분리배출하는 모습 · 대사 「우리 모두 분리배출을 실천해요!」","장면 6 — 캠페인 보드를 든 모습 · 대사 「지구야, 우리가 지켜 줄게!」"],"title":"157쪽 스토리보드 예(그림 설명 · 글 · 대사, 줄임)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_basic#6','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',2,'blank','auto','「스토리보드에는 줄거리와 (    ) 형식의 그림이 장면별로 들어갑니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"blank","stem":"「스토리보드에는 줄거리와 (    ) 형식의 그림이 장면별로 들어갑니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"스케치","correct":true},{"t":"통계표","mis":"SO6-2-u3-X22"},{"t":"완성된 표지","mis":"SO6-2-u3-X22"},{"t":"점수표","mis":"SO6-2-u3-X22"}],"explanation":["스토리보드의 뜻을 떠올려요.","장면을 대략 그려 보아요.","빈칸은 스케치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_basic#7','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',2,'mc','auto','8~9세 어린이가 읽을 그림책의 글로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"mc","stem":"8~9세 어린이가 읽을 그림책의 글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「어떤 지역은 인구가 많고, 어떤 지역은 인구가 적어요.」","correct":true},{"t":"「세계 인구 분포의 지역적 차이는 자연적·인문적 요인의 복합적 작용이다.」","mis":"SO6-2-u3-X22"},{"t":"「인구 밀도는 총인구를 면적으로 나눈 값으로 나타낸다.」","mis":"SO6-2-u3-X22"},{"t":"「아무 말이나 길게 써도 괜찮아요.」","mis":"SO6-2-u3-X22"}],"explanation":["독자는 8~9세 어린이예요.","쉬운 낱말과 짧은 문장이 좋아요.","157쪽 예시처럼 써요."],"asset":{"type":"passage","lines":["장면 1 — 다양한 사람들 · 글 「지구촌 곳곳에 많은 사람이 살아가고 있어요.」","장면 2 — 빼곡한 도시 · 글 「어떤 지역은 인구가 많고」","장면 3 — 초원에서 유목하는 사람 · 글 「어떤 지역은 인구가 적어요.」","장면 4 — 병든 지구와 걱정하는 어린이 · 글 「하지만 지구가 아파해요.」","장면 5 — 분리배출하는 모습 · 대사 「우리 모두 분리배출을 실천해요!」","장면 6 — 캠페인 보드를 든 모습 · 대사 「지구야, 우리가 지켜 줄게!」"],"title":"157쪽 스토리보드 예(그림 설명 · 글 · 대사, 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_basic#8','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',2,'mc','auto','다른 모둠의 그림책 발표를 들을 때 관심 있게 살펴봐야 할 점은 무엇인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"mc","stem":"다른 모둠의 그림책 발표를 들을 때 관심 있게 살펴봐야 할 점은 무엇인가요?","options":[{"t":"내용과 수준이 적절한지, 계획대로 스토리보드가 만들어졌는지","correct":true},{"t":"그림이 얼마나 화려한지만","mis":"SO6-2-u3-X22"},{"t":"누가 가장 빨리 끝냈는지","mis":"SO6-2-u3-X22"},{"t":"글자 수가 얼마나 많은지","mis":"SO6-2-u3-X22"}],"explanation":["발표회의 목적을 떠올려요.","독자에게 맞는지 봐요.","계획과 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_basic#9','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',2,'ox','auto','그림책 줄거리는 장면을 아무 순서로 늘어놓아도 괜찮아요.',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"ox","stem":"그림책 줄거리는 장면을 아무 순서로 늘어놓아도 괜찮아요.","answer":"X","reason_options":[{"t":"줄거리에 맞게 이야기의 흐름이 자연스럽게 드러나야 하기 때문에","correct":true},{"t":"그림책은 장면의 차례와 관계없기 때문에","mis":"SO6-2-u3-X22"}],"mis":"SO6-2-u3-X22","explanation":["줄거리는 이야기의 흐름이에요.","장면이 차례로 이어져야 해요.","그래서 X예요."],"asset":{"type":"passage","lines":["그림책 제목 — 지구와 함께 살아가는 우리","주제 — 지구촌 사람들과 함께하는 지속가능한 미래를 위한 노력","대상 — 8~9세 어린이","줄거리 — 지구촌에는 많은 사람이 살아가고 있다.","　지구촌을 위협하는 여러 가지 문제를 해결하고","　지구를 지키려고 많은 사람이 캠페인을 벌인다."],"numbered":false,"title":"156쪽 그림책 계획서 예"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_basic#10','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_basic','lesson_basic','SO6-2-u3-C12',3,'mc','auto','156쪽 계획서의 주제에 맞게 장면을 하나 더 넣는다면 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22','SO6-2-u3-X23']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"mc","stem":"156쪽 계획서의 주제에 맞게 장면을 하나 더 넣는다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그림: 안 쓰는 전등을 끄는 아이 / 글: 「지구를 위해 에너지를 아껴요.」","correct":true},{"t":"그림: 공룡이 달리는 모습 / 글: 「공룡은 빨라요.」","mis":"SO6-2-u3-X22"},{"t":"그림: 인구수 순위표 / 글: 「1위부터 10위까지 외워요.」","mis":"SO6-2-u3-X23"},{"t":"그림: 아무것도 없는 칸 / 글: 없음","mis":"SO6-2-u3-X22"}],"explanation":["주제는 지속가능한 미래를 위한 노력이에요.","생활 속 실천 장면이 어울려요.","전등 끄기 장면이 알맞아요."],"asset":{"type":"passage","lines":["그림책 제목 — 지구와 함께 살아가는 우리","주제 — 지구촌 사람들과 함께하는 지속가능한 미래를 위한 노력","대상 — 8~9세 어린이","줄거리 — 지구촌에는 많은 사람이 살아가고 있다.","　지구촌을 위협하는 여러 가지 문제를 해결하고","　지구를 지키려고 많은 사람이 캠페인을 벌인다."],"numbered":false,"title":"156쪽 그림책 계획서 예"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_challenge#1','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',2,'mc','auto','156쪽 「이렇게 해 봐요」 3에서 각자 완성할 부분을 나누어 역할을 정하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"mc","stem":"156쪽 「이렇게 해 봐요」 3에서 각자 완성할 부분을 나누어 역할을 정하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"모둠 친구들이 힘을 모아 스토리보드를 함께 완성하려고","correct":true},{"t":"한 사람만 일하려고","mis":"SO6-2-u3-X22"},{"t":"발표회를 하지 않으려고","mis":"SO6-2-u3-X22"},{"t":"줄거리를 만들지 않으려고","mis":"SO6-2-u3-X22"}],"explanation":["그림책은 모둠이 함께 만들어요.","부분을 나누어 맡아요.","함께 완성하려는 거예요."],"asset":{"type":"passage","lines":["1 이 단원에서 공부한 내용과 관련하여 주제를 정한다.","2 그림책에 담을 내용을 친구들과 이야기하고 줄거리를 만든다.","3 각자 완성할 부분을 나누어 역할을 정하고 스토리보드를 만든다.","4 그림책 발표회를 열어 다른 모둠의 친구들과 공유한다."],"numbered":false,"title":"156쪽 생각을 펼쳐요 — 이렇게 해 봐요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_challenge#2','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',2,'sa','auto','156쪽 계획서 예에서 그림책을 읽을 대상은 누구인가요?','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C12","difficulty":2,"kind":"sa","stem":"156쪽 계획서 예에서 그림책을 읽을 대상은 누구인가요?","answer":["8~9세 어린이","8~9세","8~9살 어린이","8~9살"],"explanation":["계획서의 「대상」 칸을 읽어요.","독자의 나이를 정했어요.","8~9세 어린이예요."],"asset":{"type":"passage","lines":["그림책 제목 — 지구와 함께 살아가는 우리","주제 — 지구촌 사람들과 함께하는 지속가능한 미래를 위한 노력","대상 — 8~9세 어린이","줄거리 — 지구촌에는 많은 사람이 살아가고 있다.","　지구촌을 위협하는 여러 가지 문제를 해결하고","　지구를 지키려고 많은 사람이 캠페인을 벌인다."],"numbered":false,"title":"156쪽 그림책 계획서 예"},"mis":"SO6-2-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_challenge#3','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',3,'mc','auto','단원에서 공부한 내용을 골고루 담은 그림책 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22','SO6-2-u3-X23']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"mc","stem":"단원에서 공부한 내용을 골고루 담은 그림책 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"세계의 인구 특징과 지속가능한 지구촌을 위한 노력이 함께 드러나는 줄거리","correct":true},{"t":"인구 피라미드 한 가지만 다룬 줄거리","mis":"SO6-2-u3-X22"},{"t":"단원과 관계없는 모험 이야기","mis":"SO6-2-u3-X22"},{"t":"나라별 인구수를 외우는 줄거리","mis":"SO6-2-u3-X23"}],"explanation":["단원에는 두 주제가 있어요.","인구 분포와 지구촌의 미래예요.","두 주제가 골고루 들어가야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_challenge#4','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',3,'error','auto','모둠 친구들이 그림책 계획을 말했어요. 알맞지 않은 계획을 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"error","stem":"모둠 친구들이 그림책 계획을 말했어요. 알맞지 않은 계획을 말한 친구는 누구인가요?","options":[{"t":"도하 — 「6~7세 동생들이 읽을 책이니 어려운 낱말과 긴 문장을 많이 쓰자.」","correct":true,"mis_target":"SO6-2-u3-X22"},{"t":"이서 — 「장면이 자연스럽게 이어지도록 줄거리를 먼저 만들자.」","mis":"SO6-2-u3-X22"},{"t":"로운 — 「인구가 많은 곳과 적은 곳, 지구를 지키는 실천을 모두 담자.」","mis":"SO6-2-u3-X22"}],"explanation":["독자가 6~7세예요.","독자의 수준에 맞아야 해요.","도하의 계획이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_challenge#5','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',3,'mc','auto','157쪽 장면 4의 글을 지구촌 문제가 더 분명히 드러나게 고친다면 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"mc","stem":"157쪽 장면 4의 글을 지구촌 문제가 더 분명히 드러나게 고친다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「숲이 사라지고 빙하가 녹아 지구가 아파해요.」","correct":true},{"t":"「지구는 언제나 건강해요.」","mis":"SO6-2-u3-X22"},{"t":"「아무 일도 일어나지 않아요.」","mis":"SO6-2-u3-X22"},{"t":"「인구 밀도는 명/km²로 나타내요.」","mis":"SO6-2-u3-X22"}],"explanation":["장면 4는 병든 지구예요.","교과서의 지구촌 문제를 떠올려요.","숲과 빙하 이야기가 알맞아요."],"asset":{"type":"passage","lines":["장면 1 — 다양한 사람들 · 글 「지구촌 곳곳에 많은 사람이 살아가고 있어요.」","장면 2 — 빼곡한 도시 · 글 「어떤 지역은 인구가 많고」","장면 3 — 초원에서 유목하는 사람 · 글 「어떤 지역은 인구가 적어요.」","장면 4 — 병든 지구와 걱정하는 어린이 · 글 「하지만 지구가 아파해요.」","장면 5 — 분리배출하는 모습 · 대사 「우리 모두 분리배출을 실천해요!」","장면 6 — 캠페인 보드를 든 모습 · 대사 「지구야, 우리가 지켜 줄게!」"],"title":"157쪽 스토리보드 예(그림 설명 · 글 · 대사, 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_challenge#6','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',3,'mc','auto','그림책 발표회에서 다른 모둠에게 할 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"mc","stem":"그림책 발표회에서 다른 모둠에게 할 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「독자의 나이에 맞는 쉬운 낱말을 골랐나요?」","correct":true},{"t":"「그림을 몇 분 만에 그렸나요?」","mis":"SO6-2-u3-X22"},{"t":"「글자를 얼마나 많이 썼나요?」","mis":"SO6-2-u3-X22"},{"t":"「색연필은 무슨 색이었나요?」","mis":"SO6-2-u3-X22"}],"explanation":["발표 들을 때 살펴볼 점을 떠올려요.","내용과 수준이 알맞은지 물어요.","독자 수준에 대한 질문이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_challenge#7','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',3,'mc','auto','157쪽 장면 5의 대사 「우리 모두 분리배출을 실천해요!」는 단원의 어떤 내용을 담았나요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C12","difficulty":3,"kind":"mc","stem":"157쪽 장면 5의 대사 「우리 모두 분리배출을 실천해요!」는 단원의 어떤 내용을 담았나요?","options":[{"t":"지속가능한 미래를 위해 개인이 생활 속에서 할 수 있는 노력","correct":true},{"t":"세계의 인구 분포","mis":"SO6-2-u3-X22"},{"t":"인구 구조와 인구 피라미드","mis":"SO6-2-u3-X22"},{"t":"나라별 인구 밀도","mis":"SO6-2-u3-X22"}],"explanation":["분리배출은 생활 속 실천이에요.","148쪽 개인의 노력이에요.","지속가능한 미래를 위한 노력이에요."],"asset":{"type":"passage","lines":["장면 1 — 다양한 사람들 · 글 「지구촌 곳곳에 많은 사람이 살아가고 있어요.」","장면 2 — 빼곡한 도시 · 글 「어떤 지역은 인구가 많고」","장면 3 — 초원에서 유목하는 사람 · 글 「어떤 지역은 인구가 적어요.」","장면 4 — 병든 지구와 걱정하는 어린이 · 글 「하지만 지구가 아파해요.」","장면 5 — 분리배출하는 모습 · 대사 「우리 모두 분리배출을 실천해요!」","장면 6 — 캠페인 보드를 든 모습 · 대사 「지구야, 우리가 지켜 줄게!」"],"title":"157쪽 스토리보드 예(그림 설명 · 글 · 대사, 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_challenge#8','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',4,'essay','teacher','156쪽처럼 그림책 계획서를 쓰세요. 그림책 제목, 주제, 대상(독자), 줄거리를 쓰고, 줄거리에 단원의 두 주제가 모두 드러나게 하세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u3-C12","difficulty":4,"kind":"essay","stem":"156쪽처럼 그림책 계획서를 쓰세요. 그림책 제목, 주제, 대상(독자), 줄거리를 쓰고, 줄거리에 단원의 두 주제가 모두 드러나게 하세요.","answer_guide":{"answer":"예: 제목 — 내 친구 지구. 주제 — 우리 모두 지구촌의 지속가능한 미래를 위해 생활 속 작은 일부터 실천하자. 대상 — 6~7세 어린이. 줄거리 — 지구촌에는 다양한 사람들이 흩어져 살고 있고, 사람이 많이 모여 사는 곳도 적게 사는 곳도 있다. 지구촌 사람들과 동식물, 자연이 함께 행복하게 살아가려면 생활 속 작은 실천으로 지속가능한 미래를 만들어 가야 한다.","scoring_points":["제목·주제·대상·줄거리를 모두 썼는가","줄거리에 인구 분포와 지속가능한 미래가 함께 드러나는가","독자의 수준을 생각했는가"]},"explanation":["계획서 네 칸을 채워요.","두 주제를 모두 담아요.","독자에게 맞게 써요."],"asset":{"type":"passage","lines":["그림책 제목 — 지구와 함께 살아가는 우리","주제 — 지구촌 사람들과 함께하는 지속가능한 미래를 위한 노력","대상 — 8~9세 어린이","줄거리 — 지구촌에는 많은 사람이 살아가고 있다.","　지구촌을 위협하는 여러 가지 문제를 해결하고","　지구를 지키려고 많은 사람이 캠페인을 벌인다."],"numbered":false,"title":"156쪽 그림책 계획서 예"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_challenge#9','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',4,'mc','auto','장면 카드 넷 — ㉠ 캠페인 보드를 든 아이들 ㉡ 다양한 사람들이 사는 지구촌 ㉢ 병들어 아파하는 지구 ㉣ 인구가 많은 도시와 적은 초원 — 을 이야기의 흐름에 맞게 늘어놓은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X22']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C12","difficulty":4,"kind":"mc","stem":"장면 카드 넷 — ㉠ 캠페인 보드를 든 아이들 ㉡ 다양한 사람들이 사는 지구촌 ㉢ 병들어 아파하는 지구 ㉣ 인구가 많은 도시와 적은 초원 — 을 이야기의 흐름에 맞게 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉢ → ㉠","correct":true},{"t":"㉠ → ㉢ → ㉣ → ㉡","mis":"SO6-2-u3-X22"},{"t":"㉢ → ㉠ → ㉡ → ㉣","mis":"SO6-2-u3-X22"},{"t":"㉣ → ㉠ → ㉡ → ㉢","mis":"SO6-2-u3-X22"}],"explanation":["157쪽 예처럼 지구촌 사람들로 시작해요.","인구 분포 다음에 지구의 문제가 와요.","마지막은 함께하는 실천이에요."],"asset":{"type":"passage","lines":["장면 1 — 다양한 사람들 · 글 「지구촌 곳곳에 많은 사람이 살아가고 있어요.」","장면 2 — 빼곡한 도시 · 글 「어떤 지역은 인구가 많고」","장면 3 — 초원에서 유목하는 사람 · 글 「어떤 지역은 인구가 적어요.」","장면 4 — 병든 지구와 걱정하는 어린이 · 글 「하지만 지구가 아파해요.」","장면 5 — 분리배출하는 모습 · 대사 「우리 모두 분리배출을 실천해요!」","장면 6 — 캠페인 보드를 든 모습 · 대사 「지구야, 우리가 지켜 줄게!」"],"title":"157쪽 스토리보드 예(그림 설명 · 글 · 대사, 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_L09_challenge#10','soc',6,2,'u3','L09','tb_g6_2_soc_u3_L09_challenge','lesson_challenge','SO6-2-u3-C12',4,'essay','teacher','스토리보드의 두 장면을 그림 설명과 글(또는 대사)로 쓰세요. 한 장면은 세계의 인구 분포를, 다른 한 장면은 지속가능한 미래를 위한 실천을 담으세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u3-C12","difficulty":4,"kind":"essay","stem":"스토리보드의 두 장면을 그림 설명과 글(또는 대사)로 쓰세요. 한 장면은 세계의 인구 분포를, 다른 한 장면은 지속가능한 미래를 위한 실천을 담으세요.","answer_guide":{"answer":"예: 장면 1 — 그림: 세계 인구 밀도를 표시한 세계지도 / 글: 나라마다 살고 있는 사람의 수는 달라요. 장면 2 — 그림: 사용하지 않는 전등을 끄는 아이 / 대사: 지구에 사는 모두를 위해 안 쓰는 전등을 끄자.","scoring_points":["인구 분포 장면을 알맞게 썼는가","실천 장면을 알맞게 썼는가","그림 설명과 글이 서로 어울리는가"]},"explanation":["한 장면은 1주제예요.","다른 장면은 2주제예요.","그림과 글이 맞아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#1','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C2',1,'mc','auto','단원 평가 1 — 다음 가운데 인구가 많이 사는 지역으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"mc","stem":"단원 평가 1 — 다음 가운데 인구가 많이 사는 지역으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"강수량이 매우 적은 지역","correct":true},{"t":"해안 지역","mis":"SO6-2-u3-X03"},{"t":"교통이 편리한 지역","mis":"SO6-2-u3-X03"},{"t":"토양이 비옥한 지역","mis":"SO6-2-u3-X03"},{"t":"산업이 발달한 지역","mis":"SO6-2-u3-X03"}],"explanation":["사람이 모여 사는 조건을 떠올려요.","물이 매우 적으면 살기 어려워요.","강수량이 매우 적은 지역이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#2','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C2',1,'sa','auto','단원 평가 4 — 대륙별 세계 인구(2023년) 자료의 ㉠에 들어갈 알맞은 대륙 이름을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"sa","stem":"단원 평가 4 — 대륙별 세계 인구(2023년) 자료의 ㉠에 들어갈 알맞은 대륙 이름을 쓰세요.","answer":["아시아"],"explanation":["㉠은 59.1 %로 가장 커요.","세계 인구가 가장 많은 대륙이에요.","㉠은 아시아예요."],"asset":{"type":"passage","lines":["㉠ 59.1 % · 18.3 % · 9.2 % · 8.1 % · 4.7 % · 0.6 %","원 가운데 — 약 81억 명"],"numbered":false,"title":"단원 평가 4 — 대륙별 세계 인구(2023년, 국제 연합, 2024)"},"mis":"SO6-2-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#3','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C4',1,'sa','auto','단원 평가 7 — 「세계 여러 나라의 (    )은/는 다르게 나타납니다. 인구수가 많고, 면적이 작을수록 (    )은/는 높게 나타납니다.」 빈칸에 공통으로 들어갈 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"sa","stem":"단원 평가 7 — 「세계 여러 나라의 (    )은/는 다르게 나타납니다. 인구수가 많고, 면적이 작을수록 (    )은/는 높게 나타납니다.」 빈칸에 공통으로 들어갈 말을 쓰세요.","answer":["인구 밀도","인구밀도"],"explanation":["인구수와 면적을 함께 봐요.","면적이 작고 사람이 많으면 높아요.","공통 낱말은 인구 밀도예요."],"mis":"SO6-2-u3-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#4','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C5',1,'sa','auto','139쪽 재미있게 확인해요 ❷ — 「이것으로 인구 구조를 한눈에 파악할 수 있습니다.」 정답을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"sa","stem":"139쪽 재미있게 확인해요 ❷ — 「이것으로 인구 구조를 한눈에 파악할 수 있습니다.」 정답을 쓰세요.","answer":["인구 피라미드","인구피라미드"],"explanation":["연령별·성별 인구를 나타낸 그래프예요.","136쪽에서 두 나라를 견줬어요.","인구 피라미드예요."],"asset":{"type":"passage","lines":["❶ 인구가 가장 많은 대륙입니다.","❷ 이것으로 인구 구조를 한눈에 파악할 수 있습니다.","❸ 일정한 면적(1 km²) 안에 사는 인구수로, 인구가 모여 있는 정도를 나타냅니다.","❹ 세계에서 세 번째로 인구수가 많고, 이민 오는 사람이 많은 나라입니다.","❺ 세계에서 인구수가 가장 많은 나라입니다.","암호 표 — 아시아=육지 면적이 · 인도=있습니다. · 오세아니아=기후가 · 인구 밀도=북반구에","　유소년층=문화 시설이 · 아랍 에미리트=많습니다. · 인구 구조=중위도에","　미국=살고 · 인구 피라미드=넓은 · 일본=온화한"],"numbered":false,"title":"139쪽 재미있게 확인해요 — 문제의 정답에서 암호 찾기"},"mis":"SO6-2-u3-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#5','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C7',1,'sa','auto','단원 평가 11 — 과학 기술과 교통·통신의 발달로 지구가 하나의 마을처럼 가까워진 것을 무엇이라고 하나요?','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"sa","stem":"단원 평가 11 — 과학 기술과 교통·통신의 발달로 지구가 하나의 마을처럼 가까워진 것을 무엇이라고 하나요?","answer":["지구촌"],"explanation":["141쪽 본문이에요.","지구가 한 마을처럼 가까워졌어요.","지구촌이에요."],"mis":"SO6-2-u3-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#6','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C10',1,'sa','auto','단원 평가 17 — 「국제 평화와 안전을 지키고자 정치, 경제, 사회, 문화 등에서 국제적인 협력을 해 나가는 국제기구」는 무엇인가요?','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u3-C10","difficulty":1,"kind":"sa","stem":"단원 평가 17 — 「국제 평화와 안전을 지키고자 정치, 경제, 사회, 문화 등에서 국제적인 협력을 해 나가는 국제기구」는 무엇인가요?","answer":["국제 연합","국제연합","국제 연합(UN)"],"explanation":["150쪽 첫 번째 국제기구예요.","뉴욕에 본부가 있어요.","국제 연합이에요."],"mis":"SO6-2-u3-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#7','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C11',1,'ox','auto','155쪽 설명 5 — 세계시민으로서 지구촌 문제가 우리 모두의 문제라는 생각을 가집니다.',ARRAY['SO6-2-u3-X16']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"ox","stem":"155쪽 설명 5 — 세계시민으로서 지구촌 문제가 우리 모두의 문제라는 생각을 가집니다.","answer":"O","reason_options":[{"t":"지구촌 문제는 서로에게 영향을 주므로 모두가 관심을 두고 함께 풀어야 하기 때문에","correct":true},{"t":"지구촌 문제는 문제가 생긴 나라만의 일이기 때문에","mis":"SO6-2-u3-X16"}],"mis":"SO6-2-u3-X16","explanation":["세계시민의 태도예요.","옳은 설명이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["1 지구가 하나의 마을처럼 가까워진 것을 지구촌이라고 합니다. — 출발 시각 11:00","2 지구촌 문제는 관련 있는 나라들만의 노력으로 해결해야 합니다. — 편명 AZ","3 지구촌의 지속가능한 미래를 위해 에너지 사용량을 늘립니다. — 도착지 카이로","4 그린피스는 환경 보호 등의 활동을 진행하는 비정부 기구입니다. — 진행 탑승","5 세계시민으로서 지구촌 문제가 우리 모두의 문제라는 생각을 가집니다. — 편명 HC"],"numbered":false,"title":"155쪽 재미있게 확인해요 — 설명과 단서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#8','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C2',1,'mc','auto','120~121쪽 두영이를 찾아라 — 네 번째 사람의 말로 볼 때 두영이는 어느 대륙에서 활동하고 있나요?',ARRAY['SO6-2-u3-X07']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"mc","stem":"120~121쪽 두영이를 찾아라 — 네 번째 사람의 말로 볼 때 두영이는 어느 대륙에서 활동하고 있나요?","options":[{"t":"아시아","correct":true},{"t":"아프리카","mis":"SO6-2-u3-X07"},{"t":"남아메리카","mis":"SO6-2-u3-X07"},{"t":"오세아니아","mis":"SO6-2-u3-X07"}],"explanation":["「세계에서 인구가 가장 많은 대륙」이래요.","100명 마을에서 59명이 사는 대륙이에요.","아시아예요."],"asset":{"type":"passage","lines":["① 아프리카, 삽을 든 사람 — 「아직 어린 학생인데도 지구촌 문제에","　관심이 많았어요. 저와 같은 물건을 들고 있어요.」","② 남아메리카 — 「두영이는 저와 같은 티셔츠를 입고 있어요.」","③ 오스트레일리아, 전등 끄기 활동 — 「두영이도 저와 같은 모자를 쓰고 있어요.」","④ 북아메리카 — 「두영이에게 장갑을 선물했는데 지금 저와 같은 장갑을","　사용하고 있을 거예요. 세계에서 인구가 가장 많은 대륙에서 활동하고 있대요.」"],"numbered":false,"title":"120~121쪽 두영이를 찾아라 — 네 사람의 말(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#9','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C2',2,'mc','auto','단원 평가 3 — 「이 지역은 강수량이 많고 비옥한 평야가 있어 농사에 유리합니다.」가 설명하는 지역의 기호는 어느 것인가요?',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"mc","stem":"단원 평가 3 — 「이 지역은 강수량이 많고 비옥한 평야가 있어 농사에 유리합니다.」가 설명하는 지역의 기호는 어느 것인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"SO6-2-u3-X03"},{"t":"㉡","mis":"SO6-2-u3-X03"},{"t":"㉣","mis":"SO6-2-u3-X03"},{"t":"㉤","mis":"SO6-2-u3-X03"}],"explanation":["농사에 유리한 평야를 찾아요.","남부 아시아(인도)는 비옥한 평야가 있어요.","㉢이에요."],"asset":{"type":"passage","lines":["㉠ 서부 유럽 · ㉡ 사하라 사막 · ㉢ 남부 아시아(인도)","㉣ 시베리아 북동쪽 · ㉤ 아마존 열대 우림","자료 — 「이 지역은 강수량이 많고 비옥한 평야가 있어 농사에 유리합니다.」"],"numbered":false,"title":"단원 평가 3 — 세계의 인구 분포 지도의 다섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#10','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C3',2,'mc','auto','단원 평가 5 — 나라별 인구수 지도에서 알 수 있는 사실로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X07','SO6-2-u3-X06','SO6-2-u3-X04']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"단원 평가 5 — 나라별 인구수 지도에서 알 수 있는 사실로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"오세아니아에 있는 나라들은 인구수가 많다","correct":true},{"t":"나라마다 인구수가 다르다","mis":"SO6-2-u3-X07"},{"t":"인도는 미국보다 인구수가 많다","mis":"SO6-2-u3-X07"},{"t":"나라의 면적이 크다고 인구가 많은 것은 아니다","mis":"SO6-2-u3-X06"},{"t":"중위도에 위치한 나라들의 인구수가 많은 편이다","mis":"SO6-2-u3-X04"}],"explanation":["오세아니아에는 1억 명 넘는 나라가 없어요.","나머지는 지도에서 알 수 있어요.","알맞지 않은 것은 오세아니아예요."],"asset":{"type":"passage","lines":["아시아 — 인도, 중국, 인도네시아, 파키스탄, 방글라데시, 일본, 필리핀, 베트남","유럽 — 러시아","북아메리카 — 미국, 멕시코","남아메리카 — 브라질","아프리카 — 나이지리아, 에티오피아, 이집트, 콩고 민주 공화국","오세아니아 — 없음"],"title":"129쪽 지도 — 인구수가 1억 명 이상인 나라(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#11','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C4',2,'mc','auto','단원 평가 8 — 방글라데시의 인구 밀도가 높은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X10','SO6-2-u3-X07']::text[],false,'{"seq":11,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"mc","stem":"단원 평가 8 — 방글라데시의 인구 밀도가 높은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"벼농사가 발달했기 때문이다","correct":true},{"t":"나라의 면적이 매우 넓기 때문이다","mis":"SO6-2-u3-X06"},{"t":"냉대 기후가 넓게 나타나기 때문이다","mis":"SO6-2-u3-X10"},{"t":"국토 대부분이 산지 지형이기 때문이다","mis":"SO6-2-u3-X10"},{"t":"일자리를 찾아 이민 오는 사람이 많기 때문이다","mis":"SO6-2-u3-X07"}],"explanation":["국토 대부분이 평야예요.","기후가 온화해 벼농사가 발달했어요.","그래서 인구 밀도가 매우 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#12','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C5',2,'mc','auto','단원 평가 10 — 다음 인구 피라미드에 관한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X11','SO6-2-u3-X25']::text[],false,'{"seq":12,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"mc","stem":"단원 평가 10 — 다음 인구 피라미드에 관한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"외국인 근로자를 많이 받아들인 나라의 인구 피라미드다","correct":true},{"t":"노년층의 비율이 매우 높게 나타난다","mis":"SO6-2-u3-X11"},{"t":"유소년층의 비율이 매우 높게 나타난다","mis":"SO6-2-u3-X11"},{"t":"일본, 독일의 인구 피라미드와 모양이 비슷하다","mis":"SO6-2-u3-X25"},{"t":"출생률과 사망률이 모두 높은 나라의 인구 피라미드다","mis":"SO6-2-u3-X25"}],"explanation":["청장년층, 특히 남자가 유난히 많아요.","일하러 온 사람들 때문이에요.","외국인 근로자를 받아들인 나라예요."],"asset":{"type":"passage","lines":["청장년층, 그 가운데서도 남자 쪽 막대가 유난히 길다.","유소년층과 노년층 막대는 짧다."],"title":"단원 평가 10 — 어느 나라의 인구 피라미드(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#13','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C7',2,'mc','auto','단원 평가 12 — 신문 기사에 나타난 문제 상황의 원인은 무엇인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":13,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"mc","stem":"단원 평가 12 — 신문 기사에 나타난 문제 상황의 원인은 무엇인가요?","options":[{"t":"기후변화","correct":true},{"t":"난민 발생","mis":"SO6-2-u3-X15"},{"t":"에너지 부족","mis":"SO6-2-u3-X15"},{"t":"생태계 파괴","mis":"SO6-2-u3-X15"},{"t":"동식물 서식지 파괴","mis":"SO6-2-u3-X15"}],"explanation":["극심한 더위와 가뭄이 이어져요.","지구의 기후가 바뀌고 있어요.","원인은 기후변화예요."],"asset":{"type":"passage","lines":["전례 없던 「가뭄」 맞은 유럽","지난 몇 년 동안 유럽에서 극심한 더위와 가뭄이 발생하고 있다는 연구 결과가 나왔다.","심해지고 있는 가뭄으로 농업과 임업에 치명적인 결과가 나타날 것으로 우려된다."],"title":"단원 평가 12 — 신문 기사(2021년, 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#14','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C9',2,'match','auto','단원 평가 16 — 지속가능한 미래를 위해 각 주체가 하는 노력을 찾아 바르게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"match","stem":"단원 평가 16 — 지속가능한 미래를 위해 각 주체가 하는 노력을 찾아 바르게 이으세요.","pairs":[{"l":"개인","r":"㉢ 양치나 세수를 할 때 물을 받아 사용한다"},{"l":"기업","r":"㉠ 탄소 배출을 줄일 수 있는 제품을 개발한다"},{"l":"국가","r":"㉡ 생태계를 보호하기 위한 법을 만든다"}],"mis":"SO6-2-u3-X19","explanation":["생활 속 실천은 개인이에요.","제품을 만드는 것은 기업이에요.","법을 만드는 것은 국가예요."],"asset":{"type":"passage","lines":["㉠ 탄소 배출을 줄일 수 있는 제품을 개발한다.","㉡ 생태계를 보호하기 위한 법을 만든다.","㉢ 양치나 세수를 할 때 물을 받아 사용한다."],"numbered":false,"title":"단원 평가 16 — 노력 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#15','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C11',2,'mc','auto','단원 평가 20 — 지속가능한 미래를 위해 우리가 할 수 있는 일을 보기에서 모두 골라 알맞게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X16']::text[],false,'{"seq":15,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"단원 평가 20 — 지속가능한 미래를 위해 우리가 할 수 있는 일을 보기에서 모두 골라 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"㉠, ㉣","correct":true},{"t":"㉠, ㉡","mis":"SO6-2-u3-X21"},{"t":"㉠, ㉢","mis":"SO6-2-u3-X16"},{"t":"㉡, ㉢","mis":"SO6-2-u3-X21"},{"t":"㉡, ㉣","mis":"SO6-2-u3-X21"}],"explanation":["일회용품은 줄여야 해요.","지구촌 문제는 모두의 문제예요.","알맞은 것은 ㉠과 ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 생활 속에서 전기 절약을 실천한다.","㉡ 다회용기보다는 일회용품을 더 자주 사용한다.","㉢ 지구촌 문제는 어려움을 겪는 해당 나라만의 문제라고 여긴다.","㉣ 지속가능한 미래를 위해 협력하고 책임 있게 행동하는 세계시민의 마음가짐을 가진다."],"numbered":false,"title":"단원 평가 20 — 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#16','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C2',2,'mc','auto','120~121쪽 두영이를 찾아라 — 네 사람의 실마리로 찾은 두영이의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X07']::text[],false,'{"seq":16,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"mc","stem":"120~121쪽 두영이를 찾아라 — 네 사람의 실마리로 찾은 두영이의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"삽을 들고 같은 티셔츠·모자·장갑 차림으로 아시아의 몽골에서 나무를 심는 모습","correct":true},{"t":"북아메리카에서 플래카드를 든 모습","mis":"SO6-2-u3-X07"},{"t":"오스트레일리아에서 전등을 끄는 모습","mis":"SO6-2-u3-X07"},{"t":"아프리카에서 물을 길어 오는 모습","mis":"SO6-2-u3-X07"}],"explanation":["네 사람과 같은 물건과 옷을 찾아요.","인구가 가장 많은 대륙에 있어요.","몽골에서 나무를 심고 있어요."],"asset":{"type":"passage","lines":["① 아프리카, 삽을 든 사람 — 「아직 어린 학생인데도 지구촌 문제에","　관심이 많았어요. 저와 같은 물건을 들고 있어요.」","② 남아메리카 — 「두영이는 저와 같은 티셔츠를 입고 있어요.」","③ 오스트레일리아, 전등 끄기 활동 — 「두영이도 저와 같은 모자를 쓰고 있어요.」","④ 북아메리카 — 「두영이에게 장갑을 선물했는데 지금 저와 같은 장갑을","　사용하고 있을 거예요. 세계에서 인구가 가장 많은 대륙에서 활동하고 있대요.」"],"numbered":false,"title":"120~121쪽 두영이를 찾아라 — 네 사람의 말(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#17','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C3',3,'essay','teacher','단원 평가 6 — 리비아(인구수 약 731만 명 · 면적 약 176만 km² · 국토에 사하라 사막)의 인구수가 적은 까닭을 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"essay","stem":"단원 평가 6 — 리비아(인구수 약 731만 명 · 면적 약 176만 km² · 국토에 사하라 사막)의 인구수가 적은 까닭을 쓰세요.","answer_guide":{"answer":"예: 국토 대부분이 건조한 기후가 나타나는 사막으로 이루어져 있어 사람이 살기에 알맞은 곳이 좁기 때문에 면적에 비해 인구가 매우 적다.","scoring_points":["국토 대부분이 사막임을 썼는가","건조한 기후를 썼는가","면적에 비해 인구가 적다는 점을 썼는가"]},"explanation":["리비아의 자연환경을 떠올려요.","사막이 넓어요.","면적에 비해 사람이 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#18','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C2',3,'mc','auto','139쪽 재미있게 확인해요 — 문제 ❶~❺의 정답으로 암호 표에서 찾아 완성한 문장은 어느 것인가요?',ARRAY['SO6-2-u3-X04','SO6-2-u3-X02']::text[],false,'{"seq":18,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"mc","stem":"139쪽 재미있게 확인해요 — 문제 ❶~❺의 정답으로 암호 표에서 찾아 완성한 문장은 어느 것인가요?","options":[{"t":"「세계 인구의 약 90 %는 육지 면적이 넓은 북반구에 살고 있습니다.」","correct":true},{"t":"「세계 인구의 약 90 %는 기후가 온화한 중위도에 살고 있습니다.」","mis":"SO6-2-u3-X04"},{"t":"「세계 인구의 약 90 %는 문화 시설이 많은 남반구에 살고 있습니다.」","mis":"SO6-2-u3-X04"},{"t":"「세계 인구의 약 90 %는 고르게 퍼져 살고 있습니다.」","mis":"SO6-2-u3-X02"}],"explanation":["❶ 아시아 ❷ 인구 피라미드 ❸ 인구 밀도예요.","❹ 미국 ❺ 인도예요.","육지 면적이·넓은·북반구에·살고·있습니다."],"asset":{"type":"passage","lines":["❶ 인구가 가장 많은 대륙입니다.","❷ 이것으로 인구 구조를 한눈에 파악할 수 있습니다.","❸ 일정한 면적(1 km²) 안에 사는 인구수로, 인구가 모여 있는 정도를 나타냅니다.","❹ 세계에서 세 번째로 인구수가 많고, 이민 오는 사람이 많은 나라입니다.","❺ 세계에서 인구수가 가장 많은 나라입니다.","암호 표 — 아시아=육지 면적이 · 인도=있습니다. · 오세아니아=기후가 · 인구 밀도=북반구에","　유소년층=문화 시설이 · 아랍 에미리트=많습니다. · 인구 구조=중위도에","　미국=살고 · 인구 피라미드=넓은 · 일본=온화한"],"numbered":false,"title":"139쪽 재미있게 확인해요 — 문제의 정답에서 암호 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#19','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C4',3,'mc','auto','캐나다처럼 면적이 매우 넓은 나라의 인구 밀도가 낮게 나타나는 까닭을 인구수와 면적으로 가장 알맞게 설명한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X09']::text[],false,'{"seq":19,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"mc","stem":"캐나다처럼 면적이 매우 넓은 나라의 인구 밀도가 낮게 나타나는 까닭을 인구수와 면적으로 가장 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"면적에 비해 인구수가 적어서 1 km² 안에 사는 사람 수가 적기 때문에","correct":true},{"t":"면적이 넓으면 인구 밀도를 잴 수 없기 때문에","mis":"SO6-2-u3-X09"},{"t":"인구수가 매우 많기 때문에","mis":"SO6-2-u3-X09"},{"t":"인구 밀도는 면적과 관계없기 때문에","mis":"SO6-2-u3-X09"}],"explanation":["인구 밀도는 인구수를 면적으로 견준 거예요.","넓은 땅에 사람이 적어요.","그래서 인구 밀도가 낮아요."],"asset":{"type":"passage","lines":["방글라데시 — 약 1,317명/km²","　국토 대부분이 평야 · 기후가 온화 · 벼농사 발달","캐나다 — 약 4명/km²","　냉대 기후가 넓어 농사지을 땅이 국토 면적에 비해 적다."],"numbered":false,"title":"133쪽 인구 밀도가 매우 높은 나라와 매우 낮은 나라(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#20','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C6',3,'mc','auto','나이지리아와 일본의 인구수는 앞으로 어떻게 변할지 알맞게 예상한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X08']::text[],false,'{"seq":20,"concept":"SO6-2-u3-C6","difficulty":3,"kind":"mc","stem":"나이지리아와 일본의 인구수는 앞으로 어떻게 변할지 알맞게 예상한 것은 어느 것인가요?","options":[{"t":"나이지리아의 인구수는 점점 늘고, 일본의 인구수는 점점 줄어들 것이다","correct":true},{"t":"나이지리아의 인구수는 줄고, 일본의 인구수는 늘 것이다","mis":"SO6-2-u3-X12"},{"t":"두 나라 모두 그대로일 것이다","mis":"SO6-2-u3-X08"},{"t":"두 나라 모두 빠르게 늘 것이다","mis":"SO6-2-u3-X12"}],"explanation":["나이지리아는 출생률이 높아요.","일본은 출생률이 낮고 노년층이 많아요.","나이지리아는 늘고 일본은 줄어요."],"asset":{"type":"passage","lines":["인구 피라미드 — 가로축 왼쪽은 남자, 오른쪽은 여자 인구 비율, 세로축은 나이","나이지리아 — 유소년층 비율 높다 · 노년층 비율 낮다","　출생률 높다 · 사망률 높다 · 평균 수명 짧다","일본 — 유소년층 비율 낮다 · 노년층 비율 높다","　출생률 낮다 · 사망률 낮다 · 평균 수명 길다"],"numbered":false,"title":"136쪽 할 수 있어요 — 두 나라의 인구 구조 비교(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#21','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C8',3,'mc','auto','141쪽 열대 우림 기사와 143쪽 편지에 공통으로 담긴 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X26','SO6-2-u3-X15']::text[],false,'{"seq":21,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"141쪽 열대 우림 기사와 143쪽 편지에 공통으로 담긴 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지구촌 문제는 한 나라에 그치지 않고 지구 전체에 영향을 주므로 함께 관심을 기울여야 한다","correct":true},{"t":"지구촌 문제는 문제가 생긴 나라만 해결하면 된다","mis":"SO6-2-u3-X16"},{"t":"지구촌 문제의 원인과 피해는 늘 같은 나라 안에 있다","mis":"SO6-2-u3-X26"},{"t":"지구촌 문제는 사람의 활동과 관계없다","mis":"SO6-2-u3-X15"}],"explanation":["열대 우림은 지구의 기후에 영향을 줘요.","탄소는 다른 나라에도 피해를 줘요.","함께 관심을 기울여야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#22','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C9',3,'mc','auto','「생태계를 보호하기 위한 법을 만든다」, 「난민 보호 시설을 마련한다」와 같은 노력을 하는 주체는 어느 것인가요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X20']::text[],false,'{"seq":22,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"mc","stem":"「생태계를 보호하기 위한 법을 만든다」, 「난민 보호 시설을 마련한다」와 같은 노력을 하는 주체는 어느 것인가요?","options":[{"t":"국가","correct":true},{"t":"개인","mis":"SO6-2-u3-X19"},{"t":"기업","mis":"SO6-2-u3-X19"},{"t":"비정부 기구","mis":"SO6-2-u3-X20"}],"explanation":["법과 제도를 만드는 주체예요.","시설도 마련해요.","국가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#23','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C2',4,'essay','teacher','120~121쪽 두영이를 찾아라 — 네 사람의 말을 실마리로 두영이를 찾는 과정을 쓰고, 두영이가 있는 대륙을 124쪽 100명 마을 자료로 뒷받침하세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-2-u3-C2","difficulty":4,"kind":"essay","stem":"120~121쪽 두영이를 찾아라 — 네 사람의 말을 실마리로 두영이를 찾는 과정을 쓰고, 두영이가 있는 대륙을 124쪽 100명 마을 자료로 뒷받침하세요.","answer_guide":{"answer":"예: 첫 번째 사람과 같은 삽을 들고, 두 번째 사람과 같은 티셔츠를 입고, 세 번째 사람과 같은 모자를 쓰고, 네 번째 사람이 선물한 장갑을 낀 사람을 찾는다. 네 번째 사람이 두영이가 세계에서 인구가 가장 많은 대륙에서 활동한다고 했는데, 100명 마을에서 아시아에 59명이 살아 가장 많으므로 두영이는 아시아(몽골)에서 나무를 심고 있다.","scoring_points":["실마리 넷을 모두 썼는가","인구가 가장 많은 대륙을 자료로 뒷받침했는가","두영이의 자리와 하는 일을 썼는가"]},"explanation":["물건과 옷을 하나씩 맞춰요.","대륙은 자료로 확인해요.","찾은 자리와 하는 일을 써요."],"asset":{"type":"passage","lines":["① 아프리카, 삽을 든 사람 — 「아직 어린 학생인데도 지구촌 문제에","　관심이 많았어요. 저와 같은 물건을 들고 있어요.」","② 남아메리카 — 「두영이는 저와 같은 티셔츠를 입고 있어요.」","③ 오스트레일리아, 전등 끄기 활동 — 「두영이도 저와 같은 모자를 쓰고 있어요.」","④ 북아메리카 — 「두영이에게 장갑을 선물했는데 지금 저와 같은 장갑을","　사용하고 있을 거예요. 세계에서 인구가 가장 많은 대륙에서 활동하고 있대요.」"],"numbered":false,"title":"120~121쪽 두영이를 찾아라 — 네 사람의 말(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#24','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C4',4,'essay','teacher','카드 모으기 놀이처럼 낱말 카드 「인구 밀도」와 「인구 피라미드」로 낼 문제를 하나씩 만들고 정답을 쓰세요. 문제에는 교과서에서 배운 뜻이나 예가 들어가야 해요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u3-C4","difficulty":4,"kind":"essay","stem":"카드 모으기 놀이처럼 낱말 카드 「인구 밀도」와 「인구 피라미드」로 낼 문제를 하나씩 만들고 정답을 쓰세요. 문제에는 교과서에서 배운 뜻이나 예가 들어가야 해요.","answer_guide":{"answer":"예: 「인구 밀도」 — 문제: 일정한 면적(1 km²) 안에 사는 인구수로, 방글라데시는 높고 캐나다는 낮은 것은 무엇인가요? 정답: 인구 밀도. 「인구 피라미드」 — 문제: 연령별, 성별 인구를 나타낸 그래프로, 인구 구조를 한눈에 파악할 수 있는 것은 무엇인가요? 정답: 인구 피라미드.","scoring_points":["「인구 밀도」 문제가 뜻이나 예를 담았는가","「인구 피라미드」 문제가 뜻이나 예를 담았는가","두 문제의 정답이 카드 낱말과 같은가"]},"explanation":["카드 낱말이 정답이 되게 해요.","뜻이나 교과서의 예를 넣어요.","정답을 함께 써요."],"asset":{"type":"passage","lines":["1 모둠원마다 카드 6장에 단원의 주요 낱말을 쓰고 뒤집어 쌓는다.","2 한 장씩 들고 돌아다니다 다른 모둠 친구와 가위바위보를 한다.","3 진 사람이 자기 카드 낱말과 관련 있는 문제를 내고 상대방이 맞힌다.","4 맞히면 친구의 카드를 갖고, 못 맞히면 다른 친구를 만나러 간다.","5 정한 시간이 끝나고 카드를 가장 많이 모은 모둠이 이긴다."],"numbered":false,"title":"160~161쪽 교실 놀이 — 카드 모으기 놀이(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_a#25','soc',6,2,'u3','','tb_g6_2_soc_u3_review_a','unit_review','SO6-2-u3-C2',4,'mc','auto','「지구촌 사람들」 단원의 내용을 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X02','SO6-2-u3-X24','SO6-2-u3-X23']::text[],false,'{"seq":25,"concept":"SO6-2-u3-C2","difficulty":4,"kind":"mc","stem":"「지구촌 사람들」 단원의 내용을 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"세계의 인구는 환경의 영향을 받아 특정 지역에 모여 있고, 지구촌 문제는 모두의 문제라 여러 주체가 함께 노력해야 한다","correct":true},{"t":"세계의 인구는 고르게 퍼져 있고, 지구촌 문제는 문제가 생긴 나라만 풀면 된다","mis":"SO6-2-u3-X02"},{"t":"인구가 많은 나라는 좋은 나라이고, 지구촌 문제는 국가만 노력하면 된다","mis":"SO6-2-u3-X24"},{"t":"나라별 인구수를 외우는 것이 단원의 목표이다","mis":"SO6-2-u3-X23"}],"explanation":["1주제와 2주제를 함께 떠올려요.","인구는 모여 있고 문제는 모두의 것이에요.","첫 번째가 바른 정리예요."],"asset":{"type":"passage","lines":["인구 분포 — 자연환경과 인문환경이 영향을 줌 · 특정한 지역에 모여 있음","인구수 — 많은 나라: 인도, 중국, 미국 등 · 적은 나라: 리비아, 투발루 등","인구 밀도 — 높은 나라: 방글라데시, 르완다, 인도 등 · 낮은 나라: 몽골, 오스트레일리아, 캐나다 등","지구촌 문제 — 자원과 에너지 고갈 · 생태계 파괴 · 기후변화 · 난민","노력 — 개인 · 기업 · 국가 · 국제기구 · 비정부 기구 → 세계시민"],"title":"158~159쪽 생각 그물(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#1','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C2',1,'mc','auto','단원 평가 2 — 세계의 인구 분포 지도를 읽고 알 수 있는 사실로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X04','SO6-2-u3-X02']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"mc","stem":"단원 평가 2 — 세계의 인구 분포 지도를 읽고 알 수 있는 사실로 알맞은 것은 어느 것인가요?","options":[{"t":"인구가 가장 많은 대륙은 아시아이다","correct":true},{"t":"고위도 지역에 인구가 많이 분포한다","mis":"SO6-2-u3-X04"},{"t":"세계의 인구는 지구상에 고르게 분포한다","mis":"SO6-2-u3-X02"},{"t":"세계 인구의 대부분은 남반구에 살고 있다","mis":"SO6-2-u3-X04"},{"t":"같은 나라 안에서는 인구가 고르게 분포한다","mis":"SO6-2-u3-X02"}],"explanation":["지도의 점을 살펴요.","아시아에 점이 가장 빽빽해요.","나머지는 모두 거꾸로 말했어요."],"asset":{"type":"passage","lines":["점 1개 — 100만 명","점이 빽빽한 곳 — 동아시아, 남부 아시아, 서부 유럽","점이 드문 곳 — 사막, 열대 우림, 극지방","말풍선 — 세계 인구의 약 90 %가 북반구에 살아요.","가 지역 — 북아메리카 북서쪽 끝의 알래스카"],"numbered":false,"title":"126~127쪽 세계의 인구 분포 지도(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#2','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C3',1,'mc','auto','생각 그물에서 인구수가 많은 나라로 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X07','SO6-2-u3-X06','SO6-2-u3-X09']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C3","difficulty":1,"kind":"mc","stem":"생각 그물에서 인구수가 많은 나라로 든 것은 어느 것인가요?","options":[{"t":"인도, 중국, 미국","correct":true},{"t":"리비아, 투발루","mis":"SO6-2-u3-X07"},{"t":"몽골, 캐나다, 오스트레일리아","mis":"SO6-2-u3-X06"},{"t":"방글라데시, 르완다","mis":"SO6-2-u3-X09"}],"explanation":["생각 그물의 인구수 칸을 봐요.","10억 명이 넘는 나라도 있어요.","인도·중국·미국이에요."],"asset":{"type":"passage","lines":["인구 분포 — 자연환경과 인문환경이 영향을 줌 · 특정한 지역에 모여 있음","인구수 — 많은 나라: 인도, 중국, 미국 등 · 적은 나라: 리비아, 투발루 등","인구 밀도 — 높은 나라: 방글라데시, 르완다, 인도 등 · 낮은 나라: 몽골, 오스트레일리아, 캐나다 등","지구촌 문제 — 자원과 에너지 고갈 · 생태계 파괴 · 기후변화 · 난민","노력 — 개인 · 기업 · 국가 · 국제기구 · 비정부 기구 → 세계시민"],"title":"158~159쪽 생각 그물(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#3','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C4',1,'mc','auto','생각 그물에서 인구 밀도가 높은 나라로 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X10']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"mc","stem":"생각 그물에서 인구 밀도가 높은 나라로 든 것은 어느 것인가요?","options":[{"t":"방글라데시","correct":true},{"t":"몽골","mis":"SO6-2-u3-X10"},{"t":"캐나다","mis":"SO6-2-u3-X10"},{"t":"오스트레일리아","mis":"SO6-2-u3-X10"}],"explanation":["생각 그물의 인구 밀도 칸을 봐요.","평야와 벼농사의 나라예요.","방글라데시예요."],"asset":{"type":"passage","lines":["인구 분포 — 자연환경과 인문환경이 영향을 줌 · 특정한 지역에 모여 있음","인구수 — 많은 나라: 인도, 중국, 미국 등 · 적은 나라: 리비아, 투발루 등","인구 밀도 — 높은 나라: 방글라데시, 르완다, 인도 등 · 낮은 나라: 몽골, 오스트레일리아, 캐나다 등","지구촌 문제 — 자원과 에너지 고갈 · 생태계 파괴 · 기후변화 · 난민","노력 — 개인 · 기업 · 국가 · 국제기구 · 비정부 기구 → 세계시민"],"title":"158~159쪽 생각 그물(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#4','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C5',1,'blank','auto','생각 그물 — 「출생률과 사망률이 낮고 평균 수명이 긴 나라는 (    )의 비율이 높음.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X11']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"blank","stem":"생각 그물 — 「출생률과 사망률이 낮고 평균 수명이 긴 나라는 (    )의 비율이 높음.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"노년층","correct":true},{"t":"유소년층","mis":"SO6-2-u3-X12"},{"t":"청장년층만","mis":"SO6-2-u3-X11"}],"explanation":["아기가 적게 태어나요.","오래 살아요.","노년층의 비율이 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#5','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C7',1,'mc','auto','생각 그물의 지구촌 문제 네 가지를 바르게 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":5,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"mc","stem":"생각 그물의 지구촌 문제 네 가지를 바르게 든 것은 어느 것인가요?","options":[{"t":"자원과 에너지 고갈, 생태계 파괴, 기후변화, 난민","correct":true},{"t":"인구 밀도, 인구 구조, 인구수, 인구 분포","mis":"SO6-2-u3-X15"},{"t":"지구촌, 세계시민, 국제기구, 비정부 기구","mis":"SO6-2-u3-X15"},{"t":"기후변화, 난민, 인구 피라미드, 스토리보드","mis":"SO6-2-u3-X15"}],"explanation":["142쪽 사진 넷을 떠올려요.","광산·숲·빙하·보트예요.","네 문제를 모두 골라요."],"asset":{"type":"passage","lines":["인구 분포 — 자연환경과 인문환경이 영향을 줌 · 특정한 지역에 모여 있음","인구수 — 많은 나라: 인도, 중국, 미국 등 · 적은 나라: 리비아, 투발루 등","인구 밀도 — 높은 나라: 방글라데시, 르완다, 인도 등 · 낮은 나라: 몽골, 오스트레일리아, 캐나다 등","지구촌 문제 — 자원과 에너지 고갈 · 생태계 파괴 · 기후변화 · 난민","노력 — 개인 · 기업 · 국가 · 국제기구 · 비정부 기구 → 세계시민"],"title":"158~159쪽 생각 그물(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#6','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C10',1,'mc','auto','단원 평가 18 — 「굶주림과 병에 시달리는 어린이들을 돕기 위해 만들어졌습니다. 질병 예방, 교육, 어린이 보호 등 어린이의 권리 향상을 위한 다양한 활동을 합니다.」에 해당하는 국제기구는 어느 것인가요?',ARRAY['SO6-2-u3-X20']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C10","difficulty":1,"kind":"mc","stem":"단원 평가 18 — 「굶주림과 병에 시달리는 어린이들을 돕기 위해 만들어졌습니다. 질병 예방, 교육, 어린이 보호 등 어린이의 권리 향상을 위한 다양한 활동을 합니다.」에 해당하는 국제기구는 어느 것인가요?","options":[{"t":"국제 연합 아동 기금","correct":true},{"t":"그린피스","mis":"SO6-2-u3-X20"},{"t":"국제 연합","mis":"SO6-2-u3-X20"},{"t":"국경 없는 의사회","mis":"SO6-2-u3-X20"},{"t":"국제 연합 난민 기구","mis":"SO6-2-u3-X20"}],"explanation":["어린이를 돕는 기구예요.","국제 연합 산하 기구예요.","국제 연합 아동 기금이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#7','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C11',1,'sa','auto','생각 그물 — 「(    ): 지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람」 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"sa","stem":"생각 그물 — 「(    ): 지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람」 빈칸에 알맞은 말을 쓰세요.","answer":["세계시민","세계 시민"],"explanation":["152쪽 꼭 기억해요예요.","지구촌이라는 공동체의 시민이에요.","세계시민이에요."],"mis":"SO6-2-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#8','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C7',1,'mc','auto','120~121쪽 두영이를 찾아라 — 두영이가 쓴 모자는 세 번째 사람이 참여한 어떤 활동과 관계있나요?',ARRAY['SO6-2-u3-X15','SO6-2-u3-X18']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"mc","stem":"120~121쪽 두영이를 찾아라 — 두영이가 쓴 모자는 세 번째 사람이 참여한 어떤 활동과 관계있나요?","options":[{"t":"에너지 문제 해결을 위해 1시간 동안 전등을 끄는 활동","correct":true},{"t":"나무를 베어 집을 짓는 활동","mis":"SO6-2-u3-X15"},{"t":"광산에서 구리를 캐는 활동","mis":"SO6-2-u3-X15"},{"t":"전기를 더 많이 쓰는 활동","mis":"SO6-2-u3-X18"}],"explanation":["세 번째 사람의 말을 읽어요.","1시간 동안 전등을 꺼요.","에너지를 아끼는 활동이에요."],"asset":{"type":"passage","lines":["① 아프리카, 삽을 든 사람 — 「아직 어린 학생인데도 지구촌 문제에","　관심이 많았어요. 저와 같은 물건을 들고 있어요.」","② 남아메리카 — 「두영이는 저와 같은 티셔츠를 입고 있어요.」","③ 오스트레일리아, 전등 끄기 활동 — 「두영이도 저와 같은 모자를 쓰고 있어요.」","④ 북아메리카 — 「두영이에게 장갑을 선물했는데 지금 저와 같은 장갑을","　사용하고 있을 거예요. 세계에서 인구가 가장 많은 대륙에서 활동하고 있대요.」"],"numbered":false,"title":"120~121쪽 두영이를 찾아라 — 네 사람의 말(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#9','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C1',2,'mc','auto','세계의 인구 분포에 영향을 주는 인문환경으로만 묶인 것은 어느 것인가요?',ARRAY['SO6-2-u3-X01']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C1","difficulty":2,"kind":"mc","stem":"세계의 인구 분포에 영향을 주는 인문환경으로만 묶인 것은 어느 것인가요?","options":[{"t":"산업, 교통, 문화","correct":true},{"t":"기온, 강수량, 지형","mis":"SO6-2-u3-X01"},{"t":"기온, 산업, 지형","mis":"SO6-2-u3-X01"},{"t":"강수량, 교통, 문화","mis":"SO6-2-u3-X01"}],"explanation":["사람이 만든 환경을 골라요.","기온·강수량·지형은 자연환경이에요.","산업·교통·문화예요."],"asset":{"type":"passage","lines":["인구 분포 — 자연환경과 인문환경이 영향을 줌 · 특정한 지역에 모여 있음","인구수 — 많은 나라: 인도, 중국, 미국 등 · 적은 나라: 리비아, 투발루 등","인구 밀도 — 높은 나라: 방글라데시, 르완다, 인도 등 · 낮은 나라: 몽골, 오스트레일리아, 캐나다 등","지구촌 문제 — 자원과 에너지 고갈 · 생태계 파괴 · 기후변화 · 난민","노력 — 개인 · 기업 · 국가 · 국제기구 · 비정부 기구 → 세계시민"],"title":"158~159쪽 생각 그물(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#10','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C3',2,'mc','auto','129쪽 지도에서 인구수가 1억 명 이상인 나라가 가장 많은 대륙은 어디인가요?',ARRAY['SO6-2-u3-X07']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"129쪽 지도에서 인구수가 1억 명 이상인 나라가 가장 많은 대륙은 어디인가요?","options":[{"t":"아시아","correct":true},{"t":"아프리카","mis":"SO6-2-u3-X07"},{"t":"북아메리카","mis":"SO6-2-u3-X07"},{"t":"유럽","mis":"SO6-2-u3-X07"}],"explanation":["대륙별로 나라 수를 세어요.","아시아는 여덟 나라예요.","가장 많은 대륙은 아시아예요."],"asset":{"type":"passage","lines":["아시아 — 인도, 중국, 인도네시아, 파키스탄, 방글라데시, 일본, 필리핀, 베트남","유럽 — 러시아","북아메리카 — 미국, 멕시코","남아메리카 — 브라질","아프리카 — 나이지리아, 에티오피아, 이집트, 콩고 민주 공화국","오세아니아 — 없음"],"title":"129쪽 지도 — 인구수가 1억 명 이상인 나라(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#11','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C4',2,'mc','auto','133쪽 스스로 활동으로 알게 된 우리나라 인구 밀도의 특징은 무엇인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X06']::text[],false,'{"seq":11,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"mc","stem":"133쪽 스스로 활동으로 알게 된 우리나라 인구 밀도의 특징은 무엇인가요?","options":[{"t":"면적이 비슷한 나라들보다 인구 밀도가 매우 높은 편이다","correct":true},{"t":"면적이 비슷한 나라들과 인구 밀도가 같다","mis":"SO6-2-u3-X09"},{"t":"면적이 비슷한 나라들보다 인구 밀도가 매우 낮다","mis":"SO6-2-u3-X09"},{"t":"면적이 넓어서 인구 밀도가 높다","mis":"SO6-2-u3-X06"}],"explanation":["네 나라의 수를 견줘요.","우리나라는 약 515명/km²예요.","매우 높은 편이에요."],"asset":{"type":"passage","lines":["우리나라 — 약 515명/km²(남한 통계)","아이슬란드 — 약 4명/km²","과테말라 — 약 169명/km²","헝가리 — 약 107명/km²"],"title":"133쪽 우리나라와 면적이 비슷한 나라의 인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#12','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C6',2,'mc','auto','과정 중심 평가 — 출생률이 높아 유소년층 인구가 계속 늘어날 니제르에 수출하면 좋을 물건으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":12,"concept":"SO6-2-u3-C6","difficulty":2,"kind":"mc","stem":"과정 중심 평가 — 출생률이 높아 유소년층 인구가 계속 늘어날 니제르에 수출하면 좋을 물건으로 알맞은 것은 어느 것인가요?","options":[{"t":"학용품","correct":true},{"t":"보행 보조기","mis":"SO6-2-u3-X13"},{"t":"노인 복지 시설 용품","mis":"SO6-2-u3-X13"},{"t":"요양원 침대","mis":"SO6-2-u3-X13"}],"explanation":["니제르는 유소년층이 많아요.","어린이에게 필요한 물건을 골라요.","학용품이에요."],"asset":{"type":"passage","lines":["⑴ 출생률과 사망률이 낮고 평균 수명이 길며, 유소년층 비율이 낮고 노년층 비율이 높다.","⑵ 세계 각지에서 외국인 근로자를 대거 받아들여 청장년층 인구가 많다.","⑶ 출생률과 사망률이 높고 평균 수명이 짧으며, 유소년층 비율이 높고 노년층 비율이 낮다."],"title":"과정 중심 평가 — 니제르·독일·카타르 인구 피라미드의 특징"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#13','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C7',2,'mc','auto','단원 평가 14 — 대화에 나타난 지구촌 문제와 관련하여 바르게 이야기하고 있는 사람은 누구인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":13,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"mc","stem":"단원 평가 14 — 대화에 나타난 지구촌 문제와 관련하여 바르게 이야기하고 있는 사람은 누구인가요?","options":[{"t":"주현 — 「이들을 돕기 위해 국제 연합 난민 기구가 활동하고 있어.」","correct":true},{"t":"민경 — 「지구의 온도가 점점 올라가고 있다고 해.」","mis":"SO6-2-u3-X15"},{"t":"기현 — 「무분별한 개발로 생태계가 파괴되고 있어.」","mis":"SO6-2-u3-X15"},{"t":"찬혁 — 「석유, 석탄 등의 화석 연료 사용을 줄여야 해.」","mis":"SO6-2-u3-X15"},{"t":"은경 — 「플라스틱 쓰레기로 해양 동물들의 삶이 위협받고 있대.」","mis":"SO6-2-u3-X15"}],"explanation":["전쟁 때문에 고향을 떠난 사람들 이야기예요.","난민 문제예요.","난민을 돕는 기구를 말한 주현이에요."],"asset":{"type":"speech","turns":[{"who":"나연","text":"이 나라에서 벌어진 전쟁 때문에 이곳 사람들이 고향을 떠난 지 벌써 1년째라고 해요."},{"who":"어머니","text":"가족과 헤어져 살던 곳을 떠나는 사람들이 매년 늘고 있다고 하니 걱정이구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#14','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C9',2,'mc','auto','생각 그물에서 기업의 노력으로 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X20']::text[],false,'{"seq":14,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"mc","stem":"생각 그물에서 기업의 노력으로 정리한 것은 어느 것인가요?","options":[{"t":"자원을 적게 사용한 제품 생산, 친환경 제품을 생산하는 기술 개발","correct":true},{"t":"기후변화 협약에 가입, 난민 보호 시설 마련","mis":"SO6-2-u3-X19"},{"t":"동식물이 살아가는 곳을 훼손하지 않고 보존하기","mis":"SO6-2-u3-X19"},{"t":"국제 평화와 안전을 위한 국제 협력","mis":"SO6-2-u3-X20"}],"explanation":["기업은 제품을 만들어요.","자원을 적게 쓰고 친환경으로 만들어요.","첫 번째가 기업의 노력이에요."],"asset":{"type":"passage","lines":["인구 분포 — 자연환경과 인문환경이 영향을 줌 · 특정한 지역에 모여 있음","인구수 — 많은 나라: 인도, 중국, 미국 등 · 적은 나라: 리비아, 투발루 등","인구 밀도 — 높은 나라: 방글라데시, 르완다, 인도 등 · 낮은 나라: 몽골, 오스트레일리아, 캐나다 등","지구촌 문제 — 자원과 에너지 고갈 · 생태계 파괴 · 기후변화 · 난민","노력 — 개인 · 기업 · 국가 · 국제기구 · 비정부 기구 → 세계시민"],"title":"158~159쪽 생각 그물(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#15','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C11',2,'mc','auto','155쪽 재미있게 확인해요의 설명 다섯 가운데 옳은 설명을 모두 고른 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X18']::text[],false,'{"seq":15,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"155쪽 재미있게 확인해요의 설명 다섯 가운데 옳은 설명을 모두 고른 것은 어느 것인가요?","options":[{"t":"1, 4, 5","correct":true},{"t":"1, 2, 3","mis":"SO6-2-u3-X16"},{"t":"2, 3, 4","mis":"SO6-2-u3-X18"},{"t":"3, 4, 5","mis":"SO6-2-u3-X18"}],"explanation":["설명을 하나씩 판단해요.","2는 모두의 문제라 틀리고, 3은 에너지를 아껴야 해서 틀려요.","옳은 설명은 1, 4, 5예요."],"asset":{"type":"passage","lines":["1 지구가 하나의 마을처럼 가까워진 것을 지구촌이라고 합니다. — 출발 시각 11:00","2 지구촌 문제는 관련 있는 나라들만의 노력으로 해결해야 합니다. — 편명 AZ","3 지구촌의 지속가능한 미래를 위해 에너지 사용량을 늘립니다. — 도착지 카이로","4 그린피스는 환경 보호 등의 활동을 진행하는 비정부 기구입니다. — 진행 탑승","5 세계시민으로서 지구촌 문제가 우리 모두의 문제라는 생각을 가집니다. — 편명 HC"],"numbered":false,"title":"155쪽 재미있게 확인해요 — 설명과 단서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#16','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C2',2,'mc','auto','1차시 단원 도입에서 중요 단어 「인구, 분포」로 만든 탐구 질문으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X02','SO6-2-u3-X15','SO6-2-u3-X22']::text[],false,'{"seq":16,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"mc","stem":"1차시 단원 도입에서 중요 단어 「인구, 분포」로 만든 탐구 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「세계의 인구는 어디에 분포해 있을까요?」","correct":true},{"t":"「세계에서 가장 높은 산은 어디일까요?」","mis":"SO6-2-u3-X02"},{"t":"「지구촌 문제는 왜 생길까요?」","mis":"SO6-2-u3-X15"},{"t":"「그림책은 어떻게 만들까요?」","mis":"SO6-2-u3-X22"}],"explanation":["중요 단어가 들어간 질문이어야 해요.","인구와 분포가 함께 들어가요.","첫 번째 질문이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#17','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C5',3,'essay','teacher','단원 평가 9 — 135쪽 연령별 세계 인구 구조 그래프를 읽고, 세계 인구 구조의 변화 모습을 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"SO6-2-u3-C5","difficulty":3,"kind":"essay","stem":"단원 평가 9 — 135쪽 연령별 세계 인구 구조 그래프를 읽고, 세계 인구 구조의 변화 모습을 쓰세요.","answer_guide":{"answer":"예: 1960년부터 2020년까지 유소년층의 인구 비율은 37.4 %에서 25.8 %로 줄어들고, 노년층의 인구 비율은 5.0 %에서 9.3 %로 늘어나고 있다.","scoring_points":["유소년층 비율이 줄어든다고 썼는가","노년층 비율이 늘어난다고 썼는가","그래프의 수를 근거로 들었는가"]},"explanation":["유소년층의 변화를 봐요.","노년층의 변화를 봐요.","수를 들어 써요."],"asset":{"type":"passage","lines":["차례 — 유소년층(0~14세) · 청장년층(15~64세) · 노년층(65세 이상)","1960년 — 37.4 % · 57.6 % · 5.0 %","1980년 — 35.5 % · 58.7 % · 5.8 %","2000년 — 30.4 % · 62.8 % · 6.8 %","2020년 — 25.8 % · 64.9 % · 9.3 %"],"numbered":false,"title":"135쪽 연령별 세계 인구 구조의 변화(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#18','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C3',3,'mc','auto','139쪽 재미있게 확인해요 ❹의 정답과 암호 표에서 찾은 암호를 알맞게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X07']::text[],false,'{"seq":18,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"139쪽 재미있게 확인해요 ❹의 정답과 암호 표에서 찾은 암호를 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"미국 — 살고","correct":true},{"t":"인도 — 있습니다.","mis":"SO6-2-u3-X07"},{"t":"일본 — 온화한","mis":"SO6-2-u3-X07"},{"t":"아랍 에미리트 — 많습니다.","mis":"SO6-2-u3-X07"}],"explanation":["세 번째로 인구가 많고 이민이 많은 나라예요.","정답은 미국이에요.","미국의 암호는 「살고」예요."],"asset":{"type":"passage","lines":["❶ 인구가 가장 많은 대륙입니다.","❷ 이것으로 인구 구조를 한눈에 파악할 수 있습니다.","❸ 일정한 면적(1 km²) 안에 사는 인구수로, 인구가 모여 있는 정도를 나타냅니다.","❹ 세계에서 세 번째로 인구수가 많고, 이민 오는 사람이 많은 나라입니다.","❺ 세계에서 인구수가 가장 많은 나라입니다.","암호 표 — 아시아=육지 면적이 · 인도=있습니다. · 오세아니아=기후가 · 인구 밀도=북반구에","　유소년층=문화 시설이 · 아랍 에미리트=많습니다. · 인구 구조=중위도에","　미국=살고 · 인구 피라미드=넓은 · 일본=온화한"],"numbered":false,"title":"139쪽 재미있게 확인해요 — 문제의 정답에서 암호 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#19','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C4',3,'mc','auto','면적에 비해 인구수가 매우 적은 리비아의 인구 밀도는 어떠할지 예상한 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X06','SO6-2-u3-X10','SO6-2-u3-X09']::text[],false,'{"seq":19,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"mc","stem":"면적에 비해 인구수가 매우 적은 리비아의 인구 밀도는 어떠할지 예상한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"면적에 비해 인구수가 적으므로 인구 밀도가 낮을 것이다","correct":true},{"t":"면적이 넓으므로 인구 밀도가 높을 것이다","mis":"SO6-2-u3-X06"},{"t":"사막이 넓으므로 인구 밀도가 방글라데시보다 높을 것이다","mis":"SO6-2-u3-X10"},{"t":"인구 밀도는 예상할 수 없다","mis":"SO6-2-u3-X09"}],"explanation":["130쪽 리비아 설명을 떠올려요.","면적에 비해 인구수가 매우 적어요.","인구 밀도가 낮을 거예요."],"asset":{"type":"passage","lines":["① 인도 — 약 14억 3,807만 명 · 세계에서 인구수가 가장 많다.","　강수량이 많고 토양이 비옥해 농업 발달 · 출생률이 높아 증가 전망","② 미국 — 약 3억 4,348만 명 · 세계에서 세 번째로 많다.","　기후가 온화하고 다양한 산업 발달 · 일자리를 찾아 이민 오는 사람이 많다.","③ 투발루 — 9,816명 · 남태평양의 작은 섬나라","　기후변화로 바다에 잠길 위험 · 주민들이 다른 나라로 이주할 계획","④ 리비아 — 약 731만 명 · 국토 대부분이 건조한 기후의 사막","　그래서 국토의 면적에 비해 인구수가 매우 적다."],"numbered":false,"title":"130쪽 네 나라의 인구(2023년 기준, 국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#20','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C6',3,'mc','auto','사우디아라비아와 아랍 에미리트의 청장년층 인구 가운데 남성이 여성보다 많은 점으로 예상할 수 있는 것은 무엇인가요?',ARRAY['SO6-2-u3-X25','SO6-2-u3-X13','SO6-2-u3-X09']::text[],false,'{"seq":20,"concept":"SO6-2-u3-C6","difficulty":3,"kind":"mc","stem":"사우디아라비아와 아랍 에미리트의 청장년층 인구 가운데 남성이 여성보다 많은 점으로 예상할 수 있는 것은 무엇인가요?","options":[{"t":"건설, 운송 등 남성 중심의 일자리가 많을 것이다","correct":true},{"t":"아기가 많이 태어날 것이다","mis":"SO6-2-u3-X25"},{"t":"노인을 위한 시설이 가장 많이 필요할 것이다","mis":"SO6-2-u3-X13"},{"t":"인구 밀도가 매우 낮아질 것이다","mis":"SO6-2-u3-X09"}],"explanation":["일하러 온 사람들이 많아요.","남성 근로자가 많아요.","그런 일자리가 많을 거예요."],"asset":{"type":"passage","lines":["석유 자원이 풍부한 사우디아라비아, 아랍 에미리트, 쿠웨이트, 카타르 등은","경제성장 과정에서 인도, 파키스탄, 필리핀 등에서 근로자를 받아들였다.","그래서 전체 인구에서 외국인 근로자가 차지하는 비중이 높고","생산 활동에 참여할 수 있는 청장년층 인구가 많다."],"title":"138쪽 풍덩 사회 속으로 — 독특한 인구 구조를 가진 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#21','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C8',3,'mc','auto','「탄소 배출과 온실 효과에 따른 지구 온도 상승」은 붙임쪽지의 어느 칸에 써야 할까요?',ARRAY['SO6-2-u3-X17']::text[],false,'{"seq":21,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"「탄소 배출과 온실 효과에 따른 지구 온도 상승」은 붙임쪽지의 어느 칸에 써야 할까요?","options":[{"t":"문제 원인","correct":true},{"t":"지역","mis":"SO6-2-u3-X17"},{"t":"문제 상황","mis":"SO6-2-u3-X17"},{"t":"느낀 점","mis":"SO6-2-u3-X17"}],"explanation":["왜 생겼는지를 말해요.","온도가 오른 까닭이에요.","문제 원인 칸에 써요."],"asset":{"type":"passage","lines":["붙임쪽지 ㉮ 지역 — 우리나라, 유럽, 미국 등","　문제 상황 — 기록적인 폭염 · 미국 마이애미 솜브레로 지역의 산호초 폐사","　문제 원인 — 탄소 배출과 온실 효과에 따른 지구 온도 상승 등","붙임쪽지 ㉯ 지역 — 유럽","　문제 상황 — 꽃가루받이에 중요한 호박벌의 수 감소 · 60년 안에 70 % 이상 생존 위기","　문제 원인 — 지구 온난화, 인간의 활동에 따른 벌의 서식지 파괴 등"],"numbered":false,"title":"145쪽 세계지도에 붙인 붙임쪽지 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#22','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C10',3,'mc','auto','비정부 기구끼리만 바르게 묶은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X20']::text[],false,'{"seq":22,"concept":"SO6-2-u3-C10","difficulty":3,"kind":"mc","stem":"비정부 기구끼리만 바르게 묶은 것은 어느 것인가요?","options":[{"t":"국경 없는 의사회, 세계 자연 기금, 그린피스","correct":true},{"t":"국제 연합, 국제 연합 아동 기금, 그린피스","mis":"SO6-2-u3-X20"},{"t":"국제 연합 난민 기구, 국경 없는 의사회, 세계 자연 기금","mis":"SO6-2-u3-X20"},{"t":"국제 연합, 국제 연합 아동 기금, 국제 연합 난민 기구","mis":"SO6-2-u3-X20"}],"explanation":["나라들이 만든 기구를 빼요.","이름에 「국제 연합」이 붙은 것은 국제기구예요.","민간이 만든 셋을 골라요."],"asset":{"type":"passage","lines":["국제 연합 — 국제 평화와 안전을 지키고자 여러 분야에서 국제 협력","국제 연합 아동 기금 — 어려움을 겪는 어린이에게 의료·식량·교육 제공","국제 연합 난민 기구 — 난민 보호, 생활에 필요한 물품·의료·교육 제공","국경 없는 의사회 — 고통받는 사람들에게 차별 없이 의료 제공","세계 자연 기금 — 생물 다양성 보전, 기후변화에 대응하는 활동","그린피스 — 환경 연구, 해양 생태계 보호 활동"],"title":"150쪽 국제기구와 비정부 기구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#23','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C5',4,'essay','teacher','세계의 인구 사진전 기획 위원이 되었다고 생각하고, 인구수·인구 밀도·인구 구조 가운데 한 주제를 골라 전시할 나라 두 곳과 각 나라의 사진 장면, 안내 글을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-2-u3-C5","difficulty":4,"kind":"essay","stem":"세계의 인구 사진전 기획 위원이 되었다고 생각하고, 인구수·인구 밀도·인구 구조 가운데 한 주제를 골라 전시할 나라 두 곳과 각 나라의 사진 장면, 안내 글을 쓰세요.","answer_guide":{"answer":"예: 주제 — 인구 구조. 나이지리아 — 사진: 학교에 가는 많은 어린이들 / 안내 글: 출생률이 높아 유소년층의 비율이 높은 나라예요. 일본 — 사진: 노인 복지 센터에서 활동하는 어르신들 / 안내 글: 평균 수명이 길어 노년층의 비율이 높은 나라예요.","scoring_points":["한 주제를 정하고 알맞은 나라 두 곳을 골랐는가","사진 장면이 인구 특징을 보여 주는가","안내 글에 까닭을 편견 없이 썼는가"]},"explanation":["주제를 하나 골라요.","교과서의 나라를 떠올려요.","특징과 까닭을 안내 글에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#24','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C6',4,'essay','teacher','135쪽 그래프처럼 세계 인구에서 노년층 비율이 계속 늘어난다면 우리 생활에서 어떤 시설이나 일이 더 필요해질지 두 가지 쓰고, 그 까닭을 인구 구조와 이어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u3-C6","difficulty":4,"kind":"essay","stem":"135쪽 그래프처럼 세계 인구에서 노년층 비율이 계속 늘어난다면 우리 생활에서 어떤 시설이나 일이 더 필요해질지 두 가지 쓰고, 그 까닭을 인구 구조와 이어 쓰세요.","answer_guide":{"answer":"예: 요양원이나 노인 복지 센터 같은 노인을 위한 시설이 더 필요해질 것이다. 노인을 돌보는 일을 하는 사람도 더 필요해질 것이다. 노년층의 비율이 늘어나면 노인이 필요로 하는 시설과 도움이 늘어나기 때문이다.","scoring_points":["필요해질 시설이나 일을 두 가지 썼는가","노년층 비율 증가와 이어 까닭을 썼는가","그래프의 변화를 근거로 삼았는가"]},"explanation":["노년층 비율이 늘고 있어요.","노인에게 필요한 것을 떠올려요.","까닭을 인구 구조와 이어요."],"asset":{"type":"passage","lines":["차례 — 유소년층(0~14세) · 청장년층(15~64세) · 노년층(65세 이상)","1960년 — 37.4 % · 57.6 % · 5.0 %","1980년 — 35.5 % · 58.7 % · 5.8 %","2000년 — 30.4 % · 62.8 % · 6.8 %","2020년 — 25.8 % · 64.9 % · 9.3 %"],"numbered":false,"title":"135쪽 연령별 세계 인구 구조의 변화(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_b#25','soc',6,2,'u3','','tb_g6_2_soc_u3_review_b','unit_review','SO6-2-u3-C8',4,'mc','auto','지구촌 문제와 실천을 가장 바르게 이은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X16','SO6-2-u3-X26','SO6-2-u3-X17']::text[],false,'{"seq":25,"concept":"SO6-2-u3-C8","difficulty":4,"kind":"mc","stem":"지구촌 문제와 실천을 가장 바르게 이은 것은 어느 것인가요?","options":[{"t":"면 티셔츠 한 벌에 물 약 2,700 L가 드니 필요할 때만 옷을 사서 오래 입는다","correct":true},{"t":"옷은 지구촌 문제와 관계없으니 마음대로 사고 버린다","mis":"SO6-2-u3-X16"},{"t":"편지 속 가뭄은 그 나라만의 일이니 우리는 할 일이 없다","mis":"SO6-2-u3-X26"},{"t":"조사할 때 출처는 확인하지 않아도 된다","mis":"SO6-2-u3-X17"}],"explanation":["147쪽 물의 양을 떠올려요.","우리 소비도 지구에 영향을 줘요.","필요할 때만 사는 실천이 알맞아요."],"asset":{"type":"passage","lines":["A4 용지 한 장 — 물 10 L","면 티셔츠 한 벌 — 물 2,700 L","청바지 한 벌 — 물 1만 2,000 L"],"title":"147쪽 각 물건을 만드는 데 사용하는 물의 양"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#1','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C2',1,'sa','auto','생각 그물 — 「세계의 인구는 특정한 (    )에 모여 있음.」 빈칸에 알맞은 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"sa","stem":"생각 그물 — 「세계의 인구는 특정한 (    )에 모여 있음.」 빈칸에 알맞은 말을 두 글자로 쓰세요.","answer":["지역"],"explanation":["고르게 퍼져 있지 않아요.","어느 곳에 모여 있어요.","빈칸은 지역이에요."],"asset":{"type":"passage","lines":["인구 분포 — 자연환경과 인문환경이 영향을 줌 · 특정한 지역에 모여 있음","인구수 — 많은 나라: 인도, 중국, 미국 등 · 적은 나라: 리비아, 투발루 등","인구 밀도 — 높은 나라: 방글라데시, 르완다, 인도 등 · 낮은 나라: 몽골, 오스트레일리아, 캐나다 등","지구촌 문제 — 자원과 에너지 고갈 · 생태계 파괴 · 기후변화 · 난민","노력 — 개인 · 기업 · 국가 · 국제기구 · 비정부 기구 → 세계시민"],"title":"158~159쪽 생각 그물(줄임)"},"mis":"SO6-2-u3-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#2','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C3',1,'sa','auto','카드 모으기 놀이 문제 — 「세계에서 인구수가 가장 많은 나라로, 강수량이 많고 토양이 비옥해 농업이 발달한 나라는 어디인가요?」','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u3-C3","difficulty":1,"kind":"sa","stem":"카드 모으기 놀이 문제 — 「세계에서 인구수가 가장 많은 나라로, 강수량이 많고 토양이 비옥해 농업이 발달한 나라는 어디인가요?」","answer":["인도"],"explanation":["130쪽 네 나라를 떠올려요.","약 14억 3,807만 명이에요.","답은 인도예요."],"mis":"SO6-2-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#3','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C4',1,'mc','auto','생각 그물에서 인구 밀도가 낮은 나라로 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X10']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"mc","stem":"생각 그물에서 인구 밀도가 낮은 나라로 든 것은 어느 것인가요?","options":[{"t":"몽골","correct":true},{"t":"방글라데시","mis":"SO6-2-u3-X10"},{"t":"르완다","mis":"SO6-2-u3-X10"},{"t":"인도","mis":"SO6-2-u3-X10"}],"explanation":["생각 그물의 인구 밀도 칸을 봐요.","낮은 나라 셋 가운데 하나예요.","몽골이에요."],"asset":{"type":"passage","lines":["인구 분포 — 자연환경과 인문환경이 영향을 줌 · 특정한 지역에 모여 있음","인구수 — 많은 나라: 인도, 중국, 미국 등 · 적은 나라: 리비아, 투발루 등","인구 밀도 — 높은 나라: 방글라데시, 르완다, 인도 등 · 낮은 나라: 몽골, 오스트레일리아, 캐나다 등","지구촌 문제 — 자원과 에너지 고갈 · 생태계 파괴 · 기후변화 · 난민","노력 — 개인 · 기업 · 국가 · 국제기구 · 비정부 기구 → 세계시민"],"title":"158~159쪽 생각 그물(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#4','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C5',1,'blank','auto','생각 그물 — 「출생률과 사망률이 높고 평균 수명이 짧은 나라는 (    )의 비율이 높음.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u3-X12','SO6-2-u3-X11']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"blank","stem":"생각 그물 — 「출생률과 사망률이 높고 평균 수명이 짧은 나라는 (    )의 비율이 높음.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"유소년층","correct":true},{"t":"노년층","mis":"SO6-2-u3-X12"},{"t":"청장년층만","mis":"SO6-2-u3-X11"}],"explanation":["아기가 많이 태어나요.","평균 수명이 짧아요.","유소년층의 비율이 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#5','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C7',1,'sa','auto','카드 모으기 놀이 문제 — 「정치, 종교, 인종 등의 갈등으로 나라와 고향을 잃은 사람을 무엇이라고 하나요?」','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"sa","stem":"카드 모으기 놀이 문제 — 「정치, 종교, 인종 등의 갈등으로 나라와 고향을 잃은 사람을 무엇이라고 하나요?」","answer":["난민"],"explanation":["142쪽 본문이에요.","살던 곳을 떠난 사람들이에요.","난민이에요."],"mis":"SO6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#6','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C10',1,'sa','auto','카드 모으기 놀이 문제 — 「환경을 연구하고 해양 생태계를 보호하는 활동을 하는 비정부 기구의 이름을 한 곳 말하세요.」','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u3-C10","difficulty":1,"kind":"sa","stem":"카드 모으기 놀이 문제 — 「환경을 연구하고 해양 생태계를 보호하는 활동을 하는 비정부 기구의 이름을 한 곳 말하세요.」","answer":["그린피스"],"explanation":["150쪽 비정부 기구 셋을 떠올려요.","바다를 지키는 활동을 해요.","그린피스예요."],"mis":"SO6-2-u3-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#7','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C9',1,'ox','auto','155쪽 설명 3 — 지구촌의 지속가능한 미래를 위해 에너지 사용량을 늘립니다.',ARRAY['SO6-2-u3-X18']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C9","difficulty":1,"kind":"ox","stem":"155쪽 설명 3 — 지구촌의 지속가능한 미래를 위해 에너지 사용량을 늘립니다.","answer":"X","reason_options":[{"t":"지속가능한 미래를 위해서는 자원과 에너지를 아껴야 하기 때문에","correct":true},{"t":"에너지를 많이 쓸수록 지구 환경이 좋아지기 때문에","mis":"SO6-2-u3-X18"}],"mis":"SO6-2-u3-X18","explanation":["148쪽 개인의 노력을 떠올려요.","안 쓰는 전등을 꺼 에너지를 아껴요.","그래서 X예요."],"asset":{"type":"passage","lines":["1 지구가 하나의 마을처럼 가까워진 것을 지구촌이라고 합니다. — 출발 시각 11:00","2 지구촌 문제는 관련 있는 나라들만의 노력으로 해결해야 합니다. — 편명 AZ","3 지구촌의 지속가능한 미래를 위해 에너지 사용량을 늘립니다. — 도착지 카이로","4 그린피스는 환경 보호 등의 활동을 진행하는 비정부 기구입니다. — 진행 탑승","5 세계시민으로서 지구촌 문제가 우리 모두의 문제라는 생각을 가집니다. — 편명 HC"],"numbered":false,"title":"155쪽 재미있게 확인해요 — 설명과 단서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#8','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C1',1,'sa','auto','카드 모으기 놀이 문제 — 「세계의 인구 분포에 영향을 주는 요인 중 하나로, 기온, 강수량, 지형 등을 무엇이라고 하나요?」','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u3-C1","difficulty":1,"kind":"sa","stem":"카드 모으기 놀이 문제 — 「세계의 인구 분포에 영향을 주는 요인 중 하나로, 기온, 강수량, 지형 등을 무엇이라고 하나요?」","answer":["자연환경","자연 환경"],"explanation":["자연이 만든 환경이에요.","산업·교통·문화는 인문환경이에요.","자연환경이에요."],"mis":"SO6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#9','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C2',2,'ox','auto','100명 마을의 아프리카 18명과 2023년 원그래프의 아프리카 18.3 %는 비슷한 사실을 보여 줘요.',ARRAY['SO6-2-u3-X05']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"ox","stem":"100명 마을의 아프리카 18명과 2023년 원그래프의 아프리카 18.3 %는 비슷한 사실을 보여 줘요.","answer":"O","reason_options":[{"t":"100명 가운데 18명은 전체의 약 18 %로, 세계 인구에서 아프리카가 차지하는 몫을 나타내기 때문에","correct":true},{"t":"사람 수와 비율은 전혀 다른 대륙을 가리키기 때문에","mis":"SO6-2-u3-X05"}],"mis":"SO6-2-u3-X05","explanation":["100명 마을은 비율을 사람 수로 바꾼 거예요.","18명은 약 18 %예요.","그래서 O예요."],"asset":{"type":"passage","lines":["아시아 59명 · 아프리카 18명 · 유럽 9명","남아메리카 8명 · 북아메리카 5명 · 오세아니아 1명"],"title":"124쪽 세계가 100명이 사는 마을이라면(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#10','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C3',2,'mc','auto','나라의 인구수 변화에 영향을 주는 요인을 모두 바르게 든 것은 어느 것인가요?',ARRAY['SO6-2-u3-X08','SO6-2-u3-X06']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"나라의 인구수 변화에 영향을 주는 요인을 모두 바르게 든 것은 어느 것인가요?","options":[{"t":"출생, 사망, 인구의 이동, 환경의 변화","correct":true},{"t":"출생과 사망만","mis":"SO6-2-u3-X08"},{"t":"나라의 면적만","mis":"SO6-2-u3-X06"},{"t":"나라의 국기와 수도","mis":"SO6-2-u3-X08"}],"explanation":["131쪽 꼭 기억해요를 떠올려요.","태어나고, 사망하고, 옮기고, 환경이 바뀌어요.","네 가지 모두예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#11','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C4',2,'mc','auto','카드 모으기 놀이에서 낱말 카드 「인구 밀도」로 낼 문제로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X08','SO6-2-u3-X11','SO6-2-u3-X07']::text[],false,'{"seq":11,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"mc","stem":"카드 모으기 놀이에서 낱말 카드 「인구 밀도」로 낼 문제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「일정한 면적(1 km²) 안에 사는 인구수로, 인구가 모여 있는 정도를 나타내는 것은 무엇인가요?」","correct":true},{"t":"「나라의 전체 인구가 늘어나는 비율은 무엇인가요?」","mis":"SO6-2-u3-X08"},{"t":"「연령별, 성별 인구를 나타낸 그래프는 무엇인가요?」","mis":"SO6-2-u3-X11"},{"t":"「인구가 가장 많은 대륙은 어디인가요?」","mis":"SO6-2-u3-X07"}],"explanation":["카드 낱말이 정답이 되어야 해요.","인구 밀도의 뜻을 물어요.","첫 번째 문제가 알맞아요."],"asset":{"type":"passage","lines":["1 모둠원마다 카드 6장에 단원의 주요 낱말을 쓰고 뒤집어 쌓는다.","2 한 장씩 들고 돌아다니다 다른 모둠 친구와 가위바위보를 한다.","3 진 사람이 자기 카드 낱말과 관련 있는 문제를 내고 상대방이 맞힌다.","4 맞히면 친구의 카드를 갖고, 못 맞히면 다른 친구를 만나러 간다.","5 정한 시간이 끝나고 카드를 가장 많이 모은 모둠이 이긴다."],"numbered":false,"title":"160~161쪽 교실 놀이 — 카드 모으기 놀이(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#12','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C6',2,'mc','auto','137쪽 기사 제목의 「젊은 시장」은 무엇을 뜻하나요?',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":12,"concept":"SO6-2-u3-C6","difficulty":2,"kind":"mc","stem":"137쪽 기사 제목의 「젊은 시장」은 무엇을 뜻하나요?","options":[{"t":"유행에 민감하고 소비 성향이 높은 젊은 인구의 비율이 높아 앞으로 더 커질 시장","correct":true},{"t":"노년층이 많아 요양원이 필요한 시장","mis":"SO6-2-u3-X13"},{"t":"인구가 줄어 작아지는 시장","mis":"SO6-2-u3-X13"},{"t":"젊은 사람만 물건을 팔 수 있는 시장","mis":"SO6-2-u3-X13"}],"explanation":["인도네시아 인구의 54.4 %가 1980~1990년대생이에요.","젊은 소비자가 많아요.","시장이 더 커질 거예요."],"asset":{"type":"passage","lines":["높은 경제성장을 이어 오고 있는 인도네시아는","전체 인구의 54.4 %가 1980~1990년대생이다.","이들은 유행에 민감하고 소비 성향이 높아 시장 규모가 더 커질 것이다.","여러 나라 기업들이 화장품, 스마트폰 등에 투자를 늘리고 있다."],"title":"137쪽 세계가 주목하는 「젊은 시장」 인도네시아(2024년 기사를 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#13','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C7',2,'sa','auto','단원 평가 13 — 강준의 말 ㉡에 들어갈 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"sa","stem":"단원 평가 13 — 강준의 말 ㉡에 들어갈 알맞은 말을 쓰세요.","answer":["생태계"],"explanation":["무분별한 개발 때문이에요.","동식물의 살 곳이 사라져요.","㉡은 생태계예요."],"asset":{"type":"speech","turns":[{"who":"지아","text":"나는 이번 여름에 폭염을 겪으면서 ( ㉠ ) 문제에 관심을 두게 됐어."},{"who":"강준","text":"무분별한 개발로 ( ㉡ )이/가 파괴되고 동식물의 살 곳이 사라지고 있는 것도 문제라고 생각해."}]},"mis":"SO6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#14','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C9',2,'mc','auto','생각 그물에서 국가의 노력으로 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X20']::text[],false,'{"seq":14,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"mc","stem":"생각 그물에서 국가의 노력으로 정리한 것은 어느 것인가요?","options":[{"t":"기후변화 협약에 가입, 난민 보호 시설 마련","correct":true},{"t":"자원을 적게 사용한 제품 생산","mis":"SO6-2-u3-X19"},{"t":"쓰레기를 분리배출하고 재활용하기","mis":"SO6-2-u3-X19"},{"t":"차별 없이 의료 제공하기","mis":"SO6-2-u3-X20"}],"explanation":["국가는 법·제도·협약을 맡아요.","난민 보호 시설도 마련해요.","첫 번째가 국가의 노력이에요."],"asset":{"type":"passage","lines":["인구 분포 — 자연환경과 인문환경이 영향을 줌 · 특정한 지역에 모여 있음","인구수 — 많은 나라: 인도, 중국, 미국 등 · 적은 나라: 리비아, 투발루 등","인구 밀도 — 높은 나라: 방글라데시, 르완다, 인도 등 · 낮은 나라: 몽골, 오스트레일리아, 캐나다 등","지구촌 문제 — 자원과 에너지 고갈 · 생태계 파괴 · 기후변화 · 난민","노력 — 개인 · 기업 · 국가 · 국제기구 · 비정부 기구 → 세계시민"],"title":"158~159쪽 생각 그물(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#15','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C11',2,'sa','auto','155쪽 재미있게 확인해요 — 옳은 설명의 단서(출발 시각 11:00 · 진행 탑승 · 편명 HC)를 모두 만족하는 비행기의 탑승구 번호를 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"sa","stem":"155쪽 재미있게 확인해요 — 옳은 설명의 단서(출발 시각 11:00 · 진행 탑승 · 편명 HC)를 모두 만족하는 비행기의 탑승구 번호를 숫자로 쓰세요.","answer":["9"],"explanation":["편명이 HC인 비행기를 먼저 찾아요.","그중 11:00에 출발하고 탑승 중인 것은 HC01이에요.","탑승구는 9번이에요."],"asset":{"type":"passage","lines":["AZ01 · 11:00 · 카이로 · 탑승구 11 · 탑승","PE09 · 12:00 · 뉴욕 · 탑승구 2 · 준비","HC01 · 11:00 · 제네바 · 탑승구 9 · 탑승","PE20 · 11:00 · 다카 · 탑승구 16 · 탑승","HC03 · 12:00 · 나이로비 · 탑승구 22 · 탑승","HC15 · 11:00 · 도쿄 · 탑승구 8 · 완료"],"title":"155쪽 출발 안내판(편명 · 출발 시각 · 도착지 · 탑승구 · 진행)"},"mis":"SO6-2-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#16','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C9',2,'blank','auto','1차시 공부할 내용 — 「(    ) 미래를 위한 노력 살펴보기」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-2-u3-X18']::text[],false,'{"seq":16,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"blank","stem":"1차시 공부할 내용 — 「(    ) 미래를 위한 노력 살펴보기」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"지속가능한","correct":true},{"t":"편리한","mis":"SO6-2-u3-X18"},{"t":"인간만을 위한","mis":"SO6-2-u3-X18"}],"explanation":["2주제의 이름을 떠올려요.","미래 세대에 물려주는 미래예요.","지속가능한 미래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#17','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C9',3,'essay','teacher','단원 평가 15 — 지속가능한 미래를 만들기 위해 기업이 할 수 있는 노력을 두 가지 이상 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"SO6-2-u3-C9","difficulty":3,"kind":"essay","stem":"단원 평가 15 — 지속가능한 미래를 만들기 위해 기업이 할 수 있는 노력을 두 가지 이상 쓰세요.","answer_guide":{"answer":"예: 자원을 적게 사용한 제품을 생산한다. 친환경 소재의 제품을 생산하는 기술을 개발한다. 탄소 배출을 줄일 수 있는 제품을 개발한다.","scoring_points":["기업의 노력을 하나 썼는가","기업의 노력을 또 하나 썼는가","개인·국가의 노력과 헷갈리지 않았는가"]},"explanation":["149쪽 기업의 노력을 떠올려요.","생수병과 운동화가 예예요.","제품과 기술 이야기를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#18','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C2',3,'mc','auto','100명 마을의 「오세아니아 1명」과 2023년 원그래프의 「오세아니아 0.6 %」를 함께 볼 때 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X05','SO6-2-u3-X06']::text[],false,'{"seq":18,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"mc","stem":"100명 마을의 「오세아니아 1명」과 2023년 원그래프의 「오세아니아 0.6 %」를 함께 볼 때 알맞은 것은 어느 것인가요?","options":[{"t":"두 자료 모두 오세아니아의 인구가 세계에서 매우 적다는 것을 보여 준다","correct":true},{"t":"두 자료가 서로 반대되는 사실을 보여 준다","mis":"SO6-2-u3-X05"},{"t":"오세아니아는 면적이 넓어 인구가 가장 많다","mis":"SO6-2-u3-X06"},{"t":"오세아니아의 인구는 계속 줄어들었다","mis":"SO6-2-u3-X05"}],"explanation":["1명은 100명 가운데 1 %쯤이에요.","0.6 %도 매우 작은 몫이에요.","두 자료 모두 매우 적다고 말해요."],"asset":{"type":"passage","lines":["1950년(약 25억 명) — 아시아 54.9 % · 유럽 22.0 % · 아프리카 9.1 %","　북아메리카 6.8 % · 남아메리카 6.7 % · 오세아니아 0.5 %","2023년(약 81억 명) — 아시아 59.1 % · 아프리카 18.3 % · 유럽 9.2 %","　남아메리카 8.1 % · 북아메리카 4.7 % · 오세아니아 0.6 %","원의 크기는 세계의 인구수를 나타낸다."],"numbered":false,"title":"128쪽 대륙별 세계 인구의 변화(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#19','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C3',3,'mc','auto','세계 여러 나라의 인구 특징을 탐구할 때 지녀야 할 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X24','SO6-2-u3-X23']::text[],false,'{"seq":19,"concept":"SO6-2-u3-C3","difficulty":3,"kind":"mc","stem":"세계 여러 나라의 인구 특징을 탐구할 때 지녀야 할 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"인구 특징을 자연환경·인문환경과 이어 이해하고, 특정 국가에 편견을 가지지 않는다","correct":true},{"t":"인구가 적은 나라는 뒤떨어진 나라라고 생각한다","mis":"SO6-2-u3-X24"},{"t":"인구 밀도가 높은 나라는 살기 나쁜 나라라고 생각한다","mis":"SO6-2-u3-X24"},{"t":"정확한 순위를 외우는 것이 가장 중요하다고 생각한다","mis":"SO6-2-u3-X23"}],"explanation":["인구 특징은 환경에서 생긴 모습이에요.","좋고 나쁨을 따지지 않아요.","편견 없이 탐구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#20','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C6',3,'mc','auto','과정 중심 평가 — 사망률이 낮고 평균 수명이 길어 노년층 인구가 계속 늘어날 독일에 수출하면 좋을 물건으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X13']::text[],false,'{"seq":20,"concept":"SO6-2-u3-C6","difficulty":3,"kind":"mc","stem":"과정 중심 평가 — 사망률이 낮고 평균 수명이 길어 노년층 인구가 계속 늘어날 독일에 수출하면 좋을 물건으로 알맞은 것은 어느 것인가요?","options":[{"t":"보행 보조기","correct":true},{"t":"학용품","mis":"SO6-2-u3-X13"},{"t":"어린이 장난감","mis":"SO6-2-u3-X13"},{"t":"유치원 책상","mis":"SO6-2-u3-X13"}],"explanation":["독일은 노년층이 많아요.","노인에게 필요한 물건을 골라요.","보행 보조기예요."],"asset":{"type":"passage","lines":["⑴ 출생률과 사망률이 낮고 평균 수명이 길며, 유소년층 비율이 낮고 노년층 비율이 높다.","⑵ 세계 각지에서 외국인 근로자를 대거 받아들여 청장년층 인구가 많다.","⑶ 출생률과 사망률이 높고 평균 수명이 짧으며, 유소년층 비율이 높고 노년층 비율이 낮다."],"title":"과정 중심 평가 — 니제르·독일·카타르 인구 피라미드의 특징"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#21','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C8',3,'mc','auto','활동지 예시 — 「영국과 프랑스에서 겨울인데도 눈이 내리지 않고 때아닌 홍수로 일부 지역이 물에 잠겼다.」 이 문제의 원인으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15','SO6-2-u3-X26']::text[],false,'{"seq":21,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"mc","stem":"활동지 예시 — 「영국과 프랑스에서 겨울인데도 눈이 내리지 않고 때아닌 홍수로 일부 지역이 물에 잠겼다.」 이 문제의 원인으로 알맞은 것은 어느 것인가요?","options":[{"t":"지구의 기온이 상승하면서 나타난 기후변화","correct":true},{"t":"자원을 확보하기 위한 갈등","mis":"SO6-2-u3-X15"},{"t":"광산 개발로 산지가 깎임","mis":"SO6-2-u3-X15"},{"t":"두 나라 안에서만 생긴 일이라 원인이 없음","mis":"SO6-2-u3-X26"}],"explanation":["눈 대신 비가 와 홍수가 났어요.","지구의 기온이 올랐어요.","기후변화가 원인이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#22','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C11',3,'mc','auto','활동지 평가표에서 기준 ㉡(집이나 학교에서 자주 접하는 일인가?)만 본다면 가장 높은 점수를 받은 방법을 모두 고른 것은 어느 것인가요?',ARRAY['SO6-2-u3-X21']::text[],false,'{"seq":22,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"mc","stem":"활동지 평가표에서 기준 ㉡(집이나 학교에서 자주 접하는 일인가?)만 본다면 가장 높은 점수를 받은 방법을 모두 고른 것은 어느 것인가요?","options":[{"t":"①과 ③","correct":true},{"t":"②만","mis":"SO6-2-u3-X21"},{"t":"①만","mis":"SO6-2-u3-X21"},{"t":"②와 ③","mis":"SO6-2-u3-X21"}],"explanation":["기준 ㉡ 줄을 읽어요.","①은 4, ②는 3, ③은 4예요.","①과 ③이 가장 높아요."],"asset":{"type":"passage","lines":["① 안 쓰는 전등 끄기 · ② 안 쓰는 가전제품의 플러그 뽑기","③ 급식에서 음식을 먹을 만큼만 받고 남기지 않기","기준 ㉠ 누구나 실천할 수 있는 일인가? — ① 5 · ② 4 · ③ 4","기준 ㉡ 집이나 학교에서 자주 접하는 일인가? — ① 4 · ② 3 · ③ 4","기준 ㉢ 지구촌 문제 해결에 얼마나 도움이 되는가? — ① 5 · ② 4 · ③ 4"],"numbered":false,"title":"활동지 — 실천 방법 평가표(각 1~5점)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#23','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C7',4,'essay','teacher','공익 광고 기획자가 되었다고 생각하고, 지구촌 문제 하나를 골라 광고에 담을 문제 상황과 원인, 그리고 함께 참여하자는 메시지를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-2-u3-C7","difficulty":4,"kind":"essay","stem":"공익 광고 기획자가 되었다고 생각하고, 지구촌 문제 하나를 골라 광고에 담을 문제 상황과 원인, 그리고 함께 참여하자는 메시지를 쓰세요.","answer_guide":{"answer":"예: 문제 — 생태계 파괴. 문제 상황 — 농사, 목축, 각종 산업 때문에 열대 우림이 크게 줄어 동식물이 살 곳을 잃고 있다. 원인 — 인간의 무분별한 개발. 메시지 — 「숲이 사라지면 우리의 미래도 사라져요. 동식물의 집을 함께 지켜요!」","scoring_points":["지구촌 문제와 문제 상황을 썼는가","원인을 교과서 내용으로 썼는가","함께 참여하자는 메시지를 썼는가"]},"explanation":["네 문제 가운데 하나를 골라요.","상황과 원인을 짝지어요.","함께하자는 말로 끝내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#24','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C9',4,'essay','teacher','지구촌 문제 하나를 골라, 그 문제를 줄이기 위한 개인·기업·국가·국제기구(또는 비정부 기구)의 노력을 하나씩 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u3-C9","difficulty":4,"kind":"essay","stem":"지구촌 문제 하나를 골라, 그 문제를 줄이기 위한 개인·기업·국가·국제기구(또는 비정부 기구)의 노력을 하나씩 쓰세요.","answer_guide":{"answer":"예: 기후변화 — 개인: 안 쓰는 전등을 끄고 에너지를 아낀다. 기업: 탄소 배출을 줄일 수 있는 제품을 개발한다. 국가: 기후변화 협약에 가입하고 탄소 배출을 줄이려는 목표를 세운다. 비정부 기구: 세계 자연 기금이 기후변화에 대응하는 활동을 한다.","scoring_points":["지구촌 문제를 하나 골랐는가","네 주체의 노력을 알맞게 하나씩 썼는가","노력이 고른 문제를 줄이는 데 이어지는가"]},"explanation":["문제를 먼저 골라요.","주체마다 알맞은 노력을 짝지어요.","고른 문제와 이어지게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_c#25','soc',6,2,'u3','','tb_g6_2_soc_u3_review_c','unit_review','SO6-2-u3-C11',4,'essay','teacher','실천 인증 릴레이를 마쳤다고 생각하고, 내가 한 실천과 느낀 점을 쓴 뒤 릴레이가 끝난 뒤에도 실천을 이어 갈 계획을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u3-C11","difficulty":4,"kind":"essay","stem":"실천 인증 릴레이를 마쳤다고 생각하고, 내가 한 실천과 느낀 점을 쓴 뒤 릴레이가 끝난 뒤에도 실천을 이어 갈 계획을 쓰세요.","answer_guide":{"answer":"예: 나는 일주일 동안 양치할 때 컵에 물을 받아 쓰는 모습을 사진으로 찍어 기록하고 다음 친구에게 알렸다. 작은 실천이지만 우리 반 모두가 하니 아낀 물이 많을 것 같아 뿌듯했다. 릴레이가 끝난 뒤에도 날마다 물을 받아 쓰고, 가족에게도 함께하자고 권하겠다.","scoring_points":["내가 한 실천을 구체적으로 썼는가","느낀 점을 썼는가","릴레이가 끝난 뒤에도 이어 갈 계획을 썼는가"]},"explanation":["무엇을 실천했는지 써요.","실천하며 느낀 점을 써요.","한 번으로 끝내지 않을 계획을 써요."],"asset":{"type":"passage","lines":["① 실천하는 모습을 담아 인증 사진을 찍는다.","② 인증 사진과 함께 실천한 내용을 구체적으로 기록한다.","③ 다음 차례인 친구에게 알린다.","④ 다음 사람은 ①~③과 같은 방식으로 실천 활동에 참여한다."],"numbered":false,"title":"153쪽 실천 인증 릴레이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#1','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C2',1,'ox','auto','「세계 인구의 약 90 %는 육지 면적이 넓은 북반구에 살고 있습니다.」',ARRAY['SO6-2-u3-X04']::text[],false,'{"seq":1,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"ox","stem":"「세계 인구의 약 90 %는 육지 면적이 넓은 북반구에 살고 있습니다.」","answer":"O","reason_options":[{"t":"세계 인구의 대부분이 육지가 많은 북반구에 분포하기 때문에","correct":true},{"t":"세계 인구의 대부분은 남반구의 고위도에 살기 때문에","mis":"SO6-2-u3-X04"}],"mis":"SO6-2-u3-X04","explanation":["127쪽 말풍선을 떠올려요.","139쪽 암호 문장이기도 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#2','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C3',1,'ox','auto','생각 그물 — 대체로 아시아에 있는 나라들이 인구수가 많고, 오세아니아에 있는 나라들이 인구수가 적어요.',ARRAY['SO6-2-u3-X07']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C3","difficulty":1,"kind":"ox","stem":"생각 그물 — 대체로 아시아에 있는 나라들이 인구수가 많고, 오세아니아에 있는 나라들이 인구수가 적어요.","answer":"O","reason_options":[{"t":"129쪽 지도에서 1억 명 넘는 나라는 아시아에 많고 오세아니아에는 없기 때문에","correct":true},{"t":"오세아니아는 면적이 넓어 인구수가 가장 많기 때문에","mis":"SO6-2-u3-X07"}],"mis":"SO6-2-u3-X07","explanation":["대륙별로 견줘요.","오세아니아에는 1억 명 넘는 나라가 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#3','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C4',1,'ox','auto','세계 여러 나라의 인구 밀도는 면적과 인구수에 따라 다르게 나타나요.',ARRAY['SO6-2-u3-X09']::text[],false,'{"seq":3,"concept":"SO6-2-u3-C4","difficulty":1,"kind":"ox","stem":"세계 여러 나라의 인구 밀도는 면적과 인구수에 따라 다르게 나타나요.","answer":"O","reason_options":[{"t":"1 km² 안에 사는 사람 수는 면적과 인구수에 따라 달라지기 때문에","correct":true},{"t":"인구 밀도는 면적만으로 정해지기 때문에","mis":"SO6-2-u3-X09"}],"mis":"SO6-2-u3-X09","explanation":["인구 밀도의 뜻을 떠올려요.","면적과 인구수를 함께 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#4','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C5',1,'ox','auto','인구 구조는 출생률, 사망률 등에 따라 다르게 나타나요.',ARRAY['SO6-2-u3-X12']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C5","difficulty":1,"kind":"ox","stem":"인구 구조는 출생률, 사망률 등에 따라 다르게 나타나요.","answer":"O","reason_options":[{"t":"아기가 많이 태어나는지, 오래 사는지에 따라 연령층의 비율이 달라지기 때문에","correct":true},{"t":"인구 구조는 나라마다 모두 같기 때문에","mis":"SO6-2-u3-X12"}],"mis":"SO6-2-u3-X12","explanation":["137쪽 꼭 기억해요예요.","나이지리아와 일본이 달랐어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#5','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C7',1,'sa','auto','단원 평가 13 — 지아의 말 ㉠에 들어갈 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u3-C7","difficulty":1,"kind":"sa","stem":"단원 평가 13 — 지아의 말 ㉠에 들어갈 알맞은 말을 쓰세요.","answer":["기후변화","기후 변화"],"explanation":["폭염은 이상 기후예요.","지구의 온도가 오르고 있어요.","㉠은 기후변화예요."],"asset":{"type":"speech","turns":[{"who":"지아","text":"나는 이번 여름에 폭염을 겪으면서 ( ㉠ ) 문제에 관심을 두게 됐어."},{"who":"강준","text":"무분별한 개발로 ( ㉡ )이/가 파괴되고 동식물의 살 곳이 사라지고 있는 것도 문제라고 생각해."}]},"mis":"SO6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#6','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C10',1,'sa','auto','카드 모으기 놀이 — 「지구촌 문제를 해결하려고 세계 여러 나라가 모여 만든 것으로 국제 연합 등이 있어.」 이 문제의 정답 낱말을 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u3-C10","difficulty":1,"kind":"sa","stem":"카드 모으기 놀이 — 「지구촌 문제를 해결하려고 세계 여러 나라가 모여 만든 것으로 국제 연합 등이 있어.」 이 문제의 정답 낱말을 쓰세요.","answer":["국제기구","국제 기구"],"explanation":["나라들이 모여 만들었어요.","국제 연합이 대표적이에요.","국제기구예요."],"asset":{"type":"passage","lines":["1 모둠원마다 카드 6장에 단원의 주요 낱말을 쓰고 뒤집어 쌓는다.","2 한 장씩 들고 돌아다니다 다른 모둠 친구와 가위바위보를 한다.","3 진 사람이 자기 카드 낱말과 관련 있는 문제를 내고 상대방이 맞힌다.","4 맞히면 친구의 카드를 갖고, 못 맞히면 다른 친구를 만나러 간다.","5 정한 시간이 끝나고 카드를 가장 많이 모은 모둠이 이긴다."],"numbered":false,"title":"160~161쪽 교실 놀이 — 카드 모으기 놀이(줄임)"},"mis":"SO6-2-u3-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#7','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C11',1,'ox','auto','155쪽 설명 2 — 지구촌 문제는 관련 있는 나라들만의 노력으로 해결해야 합니다.',ARRAY['SO6-2-u3-X16']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C11","difficulty":1,"kind":"ox","stem":"155쪽 설명 2 — 지구촌 문제는 관련 있는 나라들만의 노력으로 해결해야 합니다.","answer":"X","reason_options":[{"t":"지구촌 문제는 우리 모두의 문제라 세계 여러 나라가 협력해야 하기 때문에","correct":true},{"t":"관련 없는 나라는 지구촌 문제에서 피해를 입지 않기 때문에","mis":"SO6-2-u3-X16"}],"mis":"SO6-2-u3-X16","explanation":["152쪽 첫 문장을 떠올려요.","여러 나라가 협력해야 해요.","그래서 X예요."],"asset":{"type":"passage","lines":["1 지구가 하나의 마을처럼 가까워진 것을 지구촌이라고 합니다. — 출발 시각 11:00","2 지구촌 문제는 관련 있는 나라들만의 노력으로 해결해야 합니다. — 편명 AZ","3 지구촌의 지속가능한 미래를 위해 에너지 사용량을 늘립니다. — 도착지 카이로","4 그린피스는 환경 보호 등의 활동을 진행하는 비정부 기구입니다. — 진행 탑승","5 세계시민으로서 지구촌 문제가 우리 모두의 문제라는 생각을 가집니다. — 편명 HC"],"numbered":false,"title":"155쪽 재미있게 확인해요 — 설명과 단서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#8','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C2',1,'mc','auto','120~121쪽 두영이를 찾아라 — 두영이를 찾는 실마리로 네 사람이 말하지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X02']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"mc","stem":"120~121쪽 두영이를 찾아라 — 두영이를 찾는 실마리로 네 사람이 말하지 않은 것은 어느 것인가요?","options":[{"t":"두영이의 신발","correct":true},{"t":"두영이가 든 물건(삽)","mis":"SO6-2-u3-X02"},{"t":"두영이가 입은 티셔츠","mis":"SO6-2-u3-X02"},{"t":"두영이가 낀 장갑","mis":"SO6-2-u3-X02"}],"explanation":["네 사람의 말을 하나씩 봐요.","삽·티셔츠·모자·장갑이 나와요.","신발은 실마리가 아니에요."],"asset":{"type":"passage","lines":["① 아프리카, 삽을 든 사람 — 「아직 어린 학생인데도 지구촌 문제에","　관심이 많았어요. 저와 같은 물건을 들고 있어요.」","② 남아메리카 — 「두영이는 저와 같은 티셔츠를 입고 있어요.」","③ 오스트레일리아, 전등 끄기 활동 — 「두영이도 저와 같은 모자를 쓰고 있어요.」","④ 북아메리카 — 「두영이에게 장갑을 선물했는데 지금 저와 같은 장갑을","　사용하고 있을 거예요. 세계에서 인구가 가장 많은 대륙에서 활동하고 있대요.」"],"numbered":false,"title":"120~121쪽 두영이를 찾아라 — 네 사람의 말(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#9','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C2',2,'mc','auto','인구가 적게 분포하는 지역의 공통점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X03','SO6-2-u3-X06']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"mc","stem":"인구가 적게 분포하는 지역의 공통점으로 알맞은 것은 어느 것인가요?","options":[{"t":"사막, 열대 우림, 극지방처럼 사람들이 생활하기 어려운 곳이다","correct":true},{"t":"산업이 발달해 일자리가 풍부한 곳이다","mis":"SO6-2-u3-X03"},{"t":"기후가 온화한 평야 지역이다","mis":"SO6-2-u3-X03"},{"t":"땅이 좁은 곳이다","mis":"SO6-2-u3-X06"}],"explanation":["점이 드문 곳을 떠올려요.","모두 살기 어려운 환경이에요.","생활하기 어려운 곳이에요."],"asset":{"type":"passage","lines":["점 1개 — 100만 명","점이 빽빽한 곳 — 동아시아, 남부 아시아, 서부 유럽","점이 드문 곳 — 사막, 열대 우림, 극지방","말풍선 — 세계 인구의 약 90 %가 북반구에 살아요.","가 지역 — 북아메리카 북서쪽 끝의 알래스카"],"numbered":false,"title":"126~127쪽 세계의 인구 분포 지도(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#10','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C3',2,'mc','auto','카드 모으기 놀이에서 낱말 카드 「이민」으로 낼 문제로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X09','SO6-2-u3-X11','SO6-2-u3-X08']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C3","difficulty":2,"kind":"mc","stem":"카드 모으기 놀이에서 낱말 카드 「이민」으로 낼 문제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「자기 나라를 떠나 다른 나라로 이주하는 일을 무엇이라고 하나요?」","correct":true},{"t":"「일정한 면적 안에 사는 인구수를 무엇이라고 하나요?」","mis":"SO6-2-u3-X09"},{"t":"「연령, 성 등을 기준으로 한 인구의 짜임새를 무엇이라고 하나요?」","mis":"SO6-2-u3-X11"},{"t":"「인구가 증가하는 비율을 무엇이라고 하나요?」","mis":"SO6-2-u3-X08"}],"explanation":["카드 낱말이 정답이 되어야 해요.","이민의 뜻을 묻는 문제예요.","첫 번째 문제가 알맞아요."],"asset":{"type":"passage","lines":["1 모둠원마다 카드 6장에 단원의 주요 낱말을 쓰고 뒤집어 쌓는다.","2 한 장씩 들고 돌아다니다 다른 모둠 친구와 가위바위보를 한다.","3 진 사람이 자기 카드 낱말과 관련 있는 문제를 내고 상대방이 맞힌다.","4 맞히면 친구의 카드를 갖고, 못 맞히면 다른 친구를 만나러 간다.","5 정한 시간이 끝나고 카드를 가장 많이 모은 모둠이 이긴다."],"numbered":false,"title":"160~161쪽 교실 놀이 — 카드 모으기 놀이(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#11','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C4',2,'ox','auto','캐나다는 면적이 넓어서 인구 밀도도 매우 높아요.',ARRAY['SO6-2-u3-X06']::text[],false,'{"seq":11,"concept":"SO6-2-u3-C4","difficulty":2,"kind":"ox","stem":"캐나다는 면적이 넓어서 인구 밀도도 매우 높아요.","answer":"X","reason_options":[{"t":"캐나다는 냉대 기후가 넓어 면적에 비해 인구수가 적으므로 인구 밀도가 약 4명/km²로 매우 낮기 때문에","correct":true},{"t":"면적이 넓으면 인구 밀도도 언제나 높기 때문에","mis":"SO6-2-u3-X06"}],"mis":"SO6-2-u3-X06","explanation":["캐나다의 인구 밀도를 떠올려요.","약 4명/km²예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#12','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C5',2,'mc','auto','135쪽 그래프에서 청장년층 비율이 가장 높게 나타난 해는 언제인가요?',ARRAY['SO6-2-u3-X12']::text[],false,'{"seq":12,"concept":"SO6-2-u3-C5","difficulty":2,"kind":"mc","stem":"135쪽 그래프에서 청장년층 비율이 가장 높게 나타난 해는 언제인가요?","options":[{"t":"2020년","correct":true},{"t":"1960년","mis":"SO6-2-u3-X12"},{"t":"1980년","mis":"SO6-2-u3-X12"},{"t":"2000년","mis":"SO6-2-u3-X12"}],"explanation":["청장년층 수를 견줘요.","2020년이 64.9 %로 가장 높아요.","답은 2020년이에요."],"asset":{"type":"passage","lines":["차례 — 유소년층(0~14세) · 청장년층(15~64세) · 노년층(65세 이상)","1960년 — 37.4 % · 57.6 % · 5.0 %","1980년 — 35.5 % · 58.7 % · 5.8 %","2000년 — 30.4 % · 62.8 % · 6.8 %","2020년 — 25.8 % · 64.9 % · 9.3 %"],"numbered":false,"title":"135쪽 연령별 세계 인구 구조의 변화(국제 연합, 2024)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#13','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C7',2,'mc','auto','카드 모으기 놀이에서 낱말 카드 「난민」으로 낼 문제로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X15','SO6-2-u3-X14']::text[],false,'{"seq":13,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"mc","stem":"카드 모으기 놀이에서 낱말 카드 「난민」으로 낼 문제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「전쟁, 재난 등의 문제로 살던 곳을 떠난 사람들을 무엇이라고 하나요?」","correct":true},{"t":"「석유나 석탄 같은 연료를 무엇이라고 하나요?」","mis":"SO6-2-u3-X15"},{"t":"「지구가 하나의 마을처럼 가까워진 것을 무엇이라고 하나요?」","mis":"SO6-2-u3-X14"},{"t":"「돈이나 물자 등이 다하여 없어지는 것을 무엇이라고 하나요?」","mis":"SO6-2-u3-X15"}],"explanation":["카드 낱말이 정답이 되어야 해요.","난민의 뜻을 물어요.","첫 번째 문제가 알맞아요."],"asset":{"type":"passage","lines":["1 모둠원마다 카드 6장에 단원의 주요 낱말을 쓰고 뒤집어 쌓는다.","2 한 장씩 들고 돌아다니다 다른 모둠 친구와 가위바위보를 한다.","3 진 사람이 자기 카드 낱말과 관련 있는 문제를 내고 상대방이 맞힌다.","4 맞히면 친구의 카드를 갖고, 못 맞히면 다른 친구를 만나러 간다.","5 정한 시간이 끝나고 카드를 가장 많이 모은 모둠이 이긴다."],"numbered":false,"title":"160~161쪽 교실 놀이 — 카드 모으기 놀이(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#14','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C9',2,'mc','auto','생각 그물에서 개인의 노력으로 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X19','SO6-2-u3-X20']::text[],false,'{"seq":14,"concept":"SO6-2-u3-C9","difficulty":2,"kind":"mc","stem":"생각 그물에서 개인의 노력으로 정리한 것은 어느 것인가요?","options":[{"t":"동식물이 살아가는 곳을 훼손하지 않고 보존하기","correct":true},{"t":"기후변화 협약에 가입하기","mis":"SO6-2-u3-X19"},{"t":"친환경 소재 제품을 생산하는 기술 개발하기","mis":"SO6-2-u3-X19"},{"t":"난민이 생활하는 데 필요한 물품 제공하기","mis":"SO6-2-u3-X20"}],"explanation":["개인은 생활 속에서 실천해요.","동식물의 서식지를 지켜요.","첫 번째가 개인의 노력이에요."],"asset":{"type":"passage","lines":["인구 분포 — 자연환경과 인문환경이 영향을 줌 · 특정한 지역에 모여 있음","인구수 — 많은 나라: 인도, 중국, 미국 등 · 적은 나라: 리비아, 투발루 등","인구 밀도 — 높은 나라: 방글라데시, 르완다, 인도 등 · 낮은 나라: 몽골, 오스트레일리아, 캐나다 등","지구촌 문제 — 자원과 에너지 고갈 · 생태계 파괴 · 기후변화 · 난민","노력 — 개인 · 기업 · 국가 · 국제기구 · 비정부 기구 → 세계시민"],"title":"158~159쪽 생각 그물(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#15','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C11',2,'mc','auto','155쪽 안내판에서 옳은 설명의 단서를 모두 만족하는 비행기는 어느 것인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X16']::text[],false,'{"seq":15,"concept":"SO6-2-u3-C11","difficulty":2,"kind":"mc","stem":"155쪽 안내판에서 옳은 설명의 단서를 모두 만족하는 비행기는 어느 것인가요?","options":[{"t":"HC01(제네바)","correct":true},{"t":"HC15(도쿄)","mis":"SO6-2-u3-X21"},{"t":"HC03(나이로비)","mis":"SO6-2-u3-X21"},{"t":"AZ01(카이로)","mis":"SO6-2-u3-X16"}],"explanation":["편명 HC·11:00·탑승을 모두 봐요.","HC15는 완료, HC03은 12:00이에요.","모두 만족하는 것은 HC01이에요."],"asset":{"type":"passage","lines":["AZ01 · 11:00 · 카이로 · 탑승구 11 · 탑승","PE09 · 12:00 · 뉴욕 · 탑승구 2 · 준비","HC01 · 11:00 · 제네바 · 탑승구 9 · 탑승","PE20 · 11:00 · 다카 · 탑승구 16 · 탑승","HC03 · 12:00 · 나이로비 · 탑승구 22 · 탑승","HC15 · 11:00 · 도쿄 · 탑승구 8 · 완료"],"title":"155쪽 출발 안내판(편명 · 출발 시각 · 도착지 · 탑승구 · 진행)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#16','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C7',2,'mc','auto','두영이를 찾는 지도에서 남아메리카 사람들이 「나무를 지켜 주세요.」라는 팻말을 들고 있어요. 이와 가장 관련 깊은 지구촌 문제는 어느 것인가요?',ARRAY['SO6-2-u3-X15']::text[],false,'{"seq":16,"concept":"SO6-2-u3-C7","difficulty":2,"kind":"mc","stem":"두영이를 찾는 지도에서 남아메리카 사람들이 「나무를 지켜 주세요.」라는 팻말을 들고 있어요. 이와 가장 관련 깊은 지구촌 문제는 어느 것인가요?","options":[{"t":"생태계 파괴","correct":true},{"t":"난민","mis":"SO6-2-u3-X15"},{"t":"인구 밀도","mis":"SO6-2-u3-X15"},{"t":"인구 구조","mis":"SO6-2-u3-X15"}],"explanation":["나무가 베어지는 곳을 떠올려요.","열대 우림이 파괴되고 있어요.","생태계 파괴 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#17','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C10',3,'essay','teacher','단원 평가 19 — 「개인이나 민간단체가 중심이 되어 공공의 이익을 지키려고 만든 단체」에 해당하는 단체를 하나 쓰고, 그 역할을 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"SO6-2-u3-C10","difficulty":3,"kind":"essay","stem":"단원 평가 19 — 「개인이나 민간단체가 중심이 되어 공공의 이익을 지키려고 만든 단체」에 해당하는 단체를 하나 쓰고, 그 역할을 쓰세요.","answer_guide":{"answer":"예: 국경 없는 의사회 — 전쟁이나 질병, 자연재해 등으로 고통받는 사람들에게 차별 없이 의료를 제공한다.","scoring_points":["비정부 기구 하나를 바르게 썼는가","그 기구의 역할을 바르게 썼는가","국제기구와 헷갈리지 않았는가"]},"explanation":["비정부 기구 셋을 떠올려요.","국경 없는 의사회·세계 자연 기금·그린피스예요.","하나를 골라 역할을 써요."],"asset":{"type":"passage","lines":["국제 연합 — 국제 평화와 안전을 지키고자 여러 분야에서 국제 협력","국제 연합 아동 기금 — 어려움을 겪는 어린이에게 의료·식량·교육 제공","국제 연합 난민 기구 — 난민 보호, 생활에 필요한 물품·의료·교육 제공","국경 없는 의사회 — 고통받는 사람들에게 차별 없이 의료 제공","세계 자연 기금 — 생물 다양성 보전, 기후변화에 대응하는 활동","그린피스 — 환경 연구, 해양 생태계 보호 활동"],"title":"150쪽 국제기구와 비정부 기구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#18','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C2',3,'error','auto','단원에서 배운 인구 분포를 친구들이 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['SO6-2-u3-X02','SO6-2-u3-X03','SO6-2-u3-X01']::text[],false,'{"seq":18,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"error","stem":"단원에서 배운 인구 분포를 친구들이 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"하율 — 「사람들은 땅이 넓은 곳일수록 많이 모여 살아.」","correct":true,"mis_target":"SO6-2-u3-X02"},{"t":"도겸 — 「기후가 온화한 중위도와 평야, 해안에 사람이 많아.」","mis":"SO6-2-u3-X03"},{"t":"시온 — 「산업이 발달해 일자리가 풍부한 곳에도 사람이 많아.」","mis":"SO6-2-u3-X01"}],"explanation":["넓이보다 환경이 중요해요.","리비아처럼 넓어도 사람이 적은 곳이 있어요.","하율이가 잘못 정리했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#19','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C4',3,'error','auto','133쪽 스스로 활동을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X09']::text[],false,'{"seq":19,"concept":"SO6-2-u3-C4","difficulty":3,"kind":"error","stem":"133쪽 스스로 활동을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「아이슬란드는 우리나라와 면적이 비슷하니 인구 밀도도 비슷할 거야.」","correct":true,"mis_target":"SO6-2-u3-X09"},{"t":"하늘 — 「우리나라는 면적이 비슷한 나라들보다 인구 밀도가 높아.」","mis":"SO6-2-u3-X09"},{"t":"준우 — 「헝가리는 과테말라보다 인구 밀도가 낮아.」","mis":"SO6-2-u3-X09"}],"explanation":["아이슬란드는 약 4명/km²예요.","우리나라는 약 515명/km²예요.","지민이가 잘못 말했어요."],"asset":{"type":"passage","lines":["우리나라 — 약 515명/km²(남한 통계)","아이슬란드 — 약 4명/km²","과테말라 — 약 169명/km²","헝가리 — 약 107명/km²"],"title":"133쪽 우리나라와 면적이 비슷한 나라의 인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#20','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C5',3,'error','auto','138쪽 독특한 인구 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X25']::text[],false,'{"seq":20,"concept":"SO6-2-u3-C5","difficulty":3,"kind":"error","stem":"138쪽 독특한 인구 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세린 — 「아랍 에미리트는 아기가 많이 태어나서 청장년층이 많은 거야.」","correct":true,"mis_target":"SO6-2-u3-X25"},{"t":"유찬 — 「여러 나라에서 근로자를 받아들여 청장년층이 많아졌어.」","mis":"SO6-2-u3-X25"},{"t":"나은 — 「전체 인구에서 외국인 근로자의 비중이 높아.」","mis":"SO6-2-u3-X25"}],"explanation":["청장년층이 많은 까닭을 떠올려요.","외국인 근로자를 받아들였어요.","세린이가 잘못 말했어요."],"asset":{"type":"passage","lines":["석유 자원이 풍부한 사우디아라비아, 아랍 에미리트, 쿠웨이트, 카타르 등은","경제성장 과정에서 인도, 파키스탄, 필리핀 등에서 근로자를 받아들였다.","그래서 전체 인구에서 외국인 근로자가 차지하는 비중이 높고","생산 활동에 참여할 수 있는 청장년층 인구가 많다."],"title":"138쪽 풍덩 사회 속으로 — 독특한 인구 구조를 가진 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#21','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C8',3,'error','auto','편지와 붙임쪽지를 읽고 친구들이 지구촌 문제를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X26','SO6-2-u3-X16']::text[],false,'{"seq":21,"concept":"SO6-2-u3-C8","difficulty":3,"kind":"error","stem":"편지와 붙임쪽지를 읽고 친구들이 지구촌 문제를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「탄소를 적게 내는 나라는 기후변화를 걱정하지 않아도 돼.」","correct":true,"mis_target":"SO6-2-u3-X26"},{"t":"우진 — 「우리가 배출한 탄소도 다른 나라에 피해를 줄 수 있어.」","mis":"SO6-2-u3-X26"},{"t":"소미 — 「지구촌 문제는 국가 사이에 생기기도 해.」","mis":"SO6-2-u3-X16"}],"explanation":["143쪽 편지를 떠올려요.","탄소를 적게 내는 나라도 가뭄을 겪어요.","태린이가 잘못 말했어요."],"asset":{"type":"passage","lines":["저는 아프리카 동쪽 나라에 살아요. 지금 최악의 가뭄을 겪고 있어요.","40년 만에 가장 건조한 기후가 나타나 물이 매우 부족해요.","어린이들도 6 km 이상 떨어진 곳에 가서 물을 구해 와요.","농작물이 제대로 자라지 못해 굶고 있는 사람이 많아요.","과도한 탄소 배출에 따른 기후변화의 영향이 크다고 해요.","우리 나라는 탄소 배출을 적게 하는데 왜 이런 일을 겪는 걸까요?"],"numbered":false,"title":"143쪽 아프리카에 사는 친구의 편지(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#22','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C11',3,'error','auto','세계시민의 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u3-X21','SO6-2-u3-X16']::text[],false,'{"seq":22,"concept":"SO6-2-u3-C11","difficulty":3,"kind":"error","stem":"세계시민의 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"규리 — 「나 하나쯤 일회용품을 마음껏 써도 지구에는 아무 영향이 없어.」","correct":true,"mis_target":"SO6-2-u3-X21"},{"t":"하온 — 「내 작은 실천이 지구를 살릴 수 있다는 것을 기억해야 해.」","mis":"SO6-2-u3-X21"},{"t":"도진 — 「지구촌 문제를 우리 모두의 문제로 여겨야 해.」","mis":"SO6-2-u3-X16"}],"explanation":["세계시민은 책임 있게 행동해요.","작은 실천도 영향을 줘요.","규리가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#23','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C11',4,'essay','teacher','생각 그물을 완성하듯 「지구촌 사람들」 단원에서 공부한 두 주제의 핵심을 한 문장씩 쓰고, 이 단원을 공부하며 새로 알게 된 점이나 느낀 점을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-2-u3-C11","difficulty":4,"kind":"essay","stem":"생각 그물을 완성하듯 「지구촌 사람들」 단원에서 공부한 두 주제의 핵심을 한 문장씩 쓰고, 이 단원을 공부하며 새로 알게 된 점이나 느낀 점을 쓰세요.","answer_guide":{"answer":"예: 세계의 인구는 자연환경과 인문환경의 영향을 받아 특정한 지역에 모여 있고, 나라마다 인구수·인구 밀도·인구 구조가 다르다. 지구촌은 자원과 에너지 고갈, 생태계 파괴, 기후변화, 난민 문제를 겪고 있어 개인·기업·국가·국제기구·비정부 기구가 함께 노력하고 있다. 세계의 인구 분포와 지속가능한 미래를 위한 다양한 노력을 알게 되었고, 세계시민으로서 작은 일부터 실천하고 싶다.","scoring_points":["1주제의 핵심을 썼는가","2주제의 핵심을 썼는가","새로 알게 된 점이나 느낀 점을 썼는가"]},"explanation":["세계의 인구 분포를 한 문장으로 써요.","지구촌의 문제와 노력을 한 문장으로 써요.","나의 생각을 덧붙여요."],"asset":{"type":"passage","lines":["인구 분포 — 자연환경과 인문환경이 영향을 줌 · 특정한 지역에 모여 있음","인구수 — 많은 나라: 인도, 중국, 미국 등 · 적은 나라: 리비아, 투발루 등","인구 밀도 — 높은 나라: 방글라데시, 르완다, 인도 등 · 낮은 나라: 몽골, 오스트레일리아, 캐나다 등","지구촌 문제 — 자원과 에너지 고갈 · 생태계 파괴 · 기후변화 · 난민","노력 — 개인 · 기업 · 국가 · 국제기구 · 비정부 기구 → 세계시민"],"title":"158~159쪽 생각 그물(줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#24','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C11',4,'essay','teacher','155쪽 재미있게 확인해요에서 탑승구 번호를 찾는 과정을 쓰세요. 옳은 설명과 틀린 설명을 가려 까닭을 쓰고, 단서로 안내판에서 비행기를 찾아 번호를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u3-C11","difficulty":4,"kind":"essay","stem":"155쪽 재미있게 확인해요에서 탑승구 번호를 찾는 과정을 쓰세요. 옳은 설명과 틀린 설명을 가려 까닭을 쓰고, 단서로 안내판에서 비행기를 찾아 번호를 쓰세요.","answer_guide":{"answer":"예: 설명 1·4·5는 옳고, 2는 지구촌 문제가 모두의 문제라 틀리며, 3은 지속가능한 미래를 위해 에너지를 아껴야 하므로 틀리다. 옳은 설명의 단서는 출발 시각 11:00, 진행 탑승, 편명 HC이다. 안내판에서 HC로 시작하고 11:00에 출발하며 탑승 중인 비행기는 HC01(제네바)이므로 탑승구 번호는 9번이다.","scoring_points":["옳은 설명과 틀린 설명을 바르게 가렸는가","틀린 설명의 까닭을 썼는가","단서를 조합해 9번을 찾았는가"]},"explanation":["설명을 하나씩 판단해요.","옳은 설명의 단서만 모아요.","단서를 모두 만족하는 줄을 찾아요."],"asset":{"type":"passage","lines":["AZ01 · 11:00 · 카이로 · 탑승구 11 · 탑승","PE09 · 12:00 · 뉴욕 · 탑승구 2 · 준비","HC01 · 11:00 · 제네바 · 탑승구 9 · 탑승","PE20 · 11:00 · 다카 · 탑승구 16 · 탑승","HC03 · 12:00 · 나이로비 · 탑승구 22 · 탑승","HC15 · 11:00 · 도쿄 · 탑승구 8 · 완료"],"title":"155쪽 출발 안내판(편명 · 출발 시각 · 도착지 · 탑승구 · 진행)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_soc_u3_review_d#25','soc',6,2,'u3','','tb_g6_2_soc_u3_review_d','unit_review','SO6-2-u3-C9',4,'mc','auto','지속가능한 미래를 위한 노력에 대해 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X18','SO6-2-u3-X19','SO6-2-u3-X20']::text[],false,'{"seq":25,"concept":"SO6-2-u3-C9","difficulty":4,"kind":"mc","stem":"지속가능한 미래를 위한 노력에 대해 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"오늘날의 모든 사람이 지구 환경을 개선하고 보존해 미래 세대에 물려주려면 개인·기업·국가·국제기구·비정부 기구가 함께 노력해야 한다","correct":true},{"t":"지금 세대가 편리하면 미래 세대는 생각하지 않아도 된다","mis":"SO6-2-u3-X18"},{"t":"국가만 노력하면 개인과 기업은 하지 않아도 된다","mis":"SO6-2-u3-X19"},{"t":"국제기구와 비정부 기구는 같은 단체이다","mis":"SO6-2-u3-X20"}],"explanation":["지속가능한 미래의 뜻을 떠올려요.","미래 세대를 생각해요.","여러 주체가 함께 노력해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
